    background: transparent;
    border: none;
    border-radius: 8px;
    font-family: inherit;
    font-size: 0.8rem;
    font-weight: 600;
    color: #94a3b8;
    cursor: pointer;
    transition: color 0.25s ease;
    position: relative;
    z-index: 1;
}

.toggleBtnActive {
    color: #0f172a;
}

.toggleBtn:hover:not(.toggleBtnActive) {
    color: #64748b;
}

/* Header */
.header {
    text-align: center;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.title {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.subtitle {
    font-size: 0.82rem;
    color: #94a3b8;
    font-weight: 400;
}

.errorMessage {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
    padding: 0.75rem 1rem;
    background: #fef2f2;
    border: 1px solid #fee2e2;
    border-radius: 12px;
    color: #ef4444;
    font-size: 0.85rem;
    text-align: center;
}

.resendLink {
    color: #ef4444;
    font-weight: 700;
    text-decoration: underline;
    cursor: pointer;
}

/* Social Row */
.socialRow {
    display: flex;
    gap: 0.6rem;
}

.socialBtn {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.6rem 0.75rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #374151;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.socialBtn:hover {
    background: #f9fafb;
    border-color: #d1d5db;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.05);
}

/* Divider */
.divider {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.dividerLine {
    flex: 1;
    height: 1px;
    background: #e5e7eb;
}

.dividerText {
    font-size: 0.72rem;
    color: #94a3b8;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

/* Form */
.form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.fieldGroup {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #374151;
}

.labelRow {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.forgotLink {
    font-size: 0.75rem;
    color: var(--primary-blue);
    text-decoration: none;
    font-weight: 600;
    transition: color 0.2s;
}

.forgotLink:hover {
    color: #0056d6;
}

.inputWrap {
    position: relative;
    display: flex;
    align-items: center;
}

.inputIcon {
    position: absolute;
    left: 0.8rem;
    color: #c0c7d0;
    pointer-events: none;
    z-index: 1;
    transition: color 0.2s ease;
}

.inputWrap:focus-within .inputIcon {
    color: var(--primary-blue);
}

.input {
    width: 100%;
    padding: 0.68rem 0.9rem 0.68rem 2.5rem;
    background: #f9fafb;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #0f172a;
    font-size: 0.85rem;
    font-family: inherit;
    outline: none;
    transition: all 0.2s ease;
}

.input::placeholder {
    color: #b0b8c4;
}

.input:focus {
    background: #ffffff;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
}

.input:hover:not(:focus) {
    border-color: #d1d5db;
}

.eyeBtn {
    position: absolute;
    right: 0.75rem;
    background: none;
    border: none;
    color: #b0b8c4;
    cursor: pointer;
    padding: 2px;
    display: flex;
    align-items: center;
    transition: color 0.2s;
}

.eyeBtn:hover {
    color: #64748b;
}

/* Options Row */
.optionsRow {
    display: flex;
    align-items: center;
}

.checkboxLabel {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    user-select: none;
}

.checkbox {
    display: none;
}

.checkboxCustom {
    width: 16px;
    height: 16px;
    border: 1.5px solid #d1d5db;
    border-radius: 4px;
    background: #ffffff;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.checkboxCustom svg {
    width: 9px;
    height: 9px;
    opacity: 0;
    transition: opacity 0.15s ease;
}

.checkbox:checked+.checkboxCustom {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
}

.checkbox:checked+.checkboxCustom svg {
    opacity: 1;
}

.checkboxText {
    font-size: 0.78rem;
    color: #64748b;
    font-weight: 500;
}

/* Submit button */
.submitBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.72rem 1.5rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 9px;
    font-size: 0.88rem;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.submitBtn:hover:not(:disabled) {
    background: #0056d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.submitBtn:active:not(:disabled) {
    transform: translateY(0);
}

.submitBtn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.spinnerWrap {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.spinner {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(255, 255, 255, 0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Footer */
.footer {
    text-align: center;
    font-size: 0.82rem;
    color: #94a3b8;
}

.footerLink {
    color: var(--primary-blue);
    font-weight: 700;
    text-decoration: none;
    transition: color 0.2s;
}

.footerLink:hover {
    color: #0056d6;
}

/* Terms — pinned to bottom */
.terms {
    position: absolute;
    bottom: 1.5rem;
    left: 50%;
    transform: translateX(-50%);
    font-size: 0.68rem;
    color: #b0b8c4;
    text-align: center;
    white-space: nowrap;
    z-index: 1;
}

.termsLink {
    color: #94a3b8;
    text-decoration: underline;
    text-underline-offset: 2px;
    transition: color 0.2s;
}

.termsLink:hover {
    color: var(--primary-blue);
}

/* Both candidate and recruiter use the same brand blue theme */

/* ============================
   RESPONSIVE — fits all screens
   ============================ */
@media (max-width: 480px) {
    .card {
        max-width: 100%;
        margin: 0 1rem;
        padding: 1.75rem 1.5rem;
        border-radius: 16px;
    }

    .title {
        font-size: 1.35rem;
    }

    .socialRow {
        flex-direction: column;
        gap: 0.45rem;
    }
}

@media (max-height: 700px) {
    .card {
        gap: 1rem;
        padding: 1.5rem 2rem;
    }

    .form {
        gap: 0.75rem;
    }

    .input {
        padding-top: 0.6rem;
        padding-bottom: 0.6rem;
    }

    .toggleBtn {
        padding: 0.45rem 0.5rem;
    }

    .submitBtn {
        padding: 0.6rem 1rem;
    }
}

"use client";

import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import { insforge } from '@/lib/insforge';
import styles from './login.module.css';

// Admin email list from .env — updateable via NEXT_PUBLIC_ADMIN_EMAILS
const ADMIN_EMAILS = (process.env.NEXT_PUBLIC_ADMIN_EMAILS || '')
    .split(',')
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean);

export default function LoginPage() {
    const router = useRouter();
    const { signIn } = useAuth();

    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [showPassword, setShowPassword] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [isEmailUnconfirmed, setIsEmailUnconfirmed] = useState(false);

    // Detect admin email as the user types
    const isAdminEmail = ADMIN_EMAILS.includes(email.trim().toLowerCase());

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();

        // 1. Basic Validation
        if (!email || !password) {
            setError('Email and password are required');
            return;
        }
        if (password.length < 8) {
            setError('Password must be at least 8 characters');
            return;
        }

        setIsLoading(true);
        setError('');
        setIsEmailUnconfirmed(false);

        try {
            // 2. Attempt sign in
            const result = await signIn(email, password);

            if (result.error) {
                if (result.error.toLowerCase().includes('confirm your email') || result.error.includes('email_not_confirmed')) {
                    setIsEmailUnconfirmed(true);
                    setError('Please confirm your email address before logging in.');
                } else {
                    setError(result.error);
                }
                setIsLoading(false);
                return;
            }

            // 3. Success — let middleware redirect to the right dashboard based on role.
            // router.refresh() re-requests the current page (/login); the middleware
            // sees the authenticated user and redirects to /dashboard/{role}.
            const resolvedRole = result.user?.role;
            const destination = isAdminEmail || resolvedRole === 'admin' || resolvedRole === 'super_admin'
                ? '/dashboard/admin'
                : resolvedRole === 'recruiter'
                    ? '/dashboard/recruiter'
                    : '/dashboard/candidate';

            window.location.assign(destination);

        } catch (err: any) {
            setError(err.message || 'An unexpected error occurred. Please try again.');
            setIsLoading(false);
        }
    };

    const handleOAuthLogin = async (provider: 'google' | 'linkedin') => {
        try {
            setError('');
            const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || window.location.origin;
            const { error: authError } = await insforge.auth.signInWithOAuth({
                provider,
                redirectTo: `${siteUrl}/auth/callback`,
            });
            if (authError) throw authError;
        } catch (err: any) {
            setError(`Failed to initiate ${provider} login. Please try again.`);
        }
    };

    return (
        <div className={styles.page}>
            <div className={styles.bgGlow1} />
            <div className={styles.bgGlow2} />
            <div className={styles.gridOverlay} />

            <div className={styles.card}>
                <Link href="/" className={styles.logoWrap}>
                    <Image
                        src="/TalentMesh_page-0002-removebg-preview.png"
                        alt="TalentMesh"
                        width={180}
                        height={50}
                        unoptimized
                        priority
                        className={styles.logoImg}
                    />
                </Link>

                <div className={styles.header}>
                    <h1 className={styles.title}>Sign in to your account</h1>
                </div>

                <div className={styles.socialRow}>
                    <button className={styles.socialBtn} type="button" onClick={() => handleOAuthLogin('google')}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
                            <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                            <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                            <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
                            <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                        </svg>
                        Google
                    </button>
                    <button className={styles.socialBtn} type="button" onClick={() => handleOAuthLogin('linkedin')}>
                        <svg width="20" height="20" viewBox="0 0 24 24" fill="#0A66C2">
                            <path d="M19 0h-14c-2.761 0-5 2.239-5 5v14c0 2.761 2.239 5 5 5h14c2.762 0 5-2.239 5-5v-14c0-2.761-2.238-5-5-5zm-11 19h-3v-11h3v11zm-1.5-12.268c-.966 0-1.75-.79-1.75-1.764s.784-1.764 1.75-1.764 1.75.79 1.75 1.764-.783 1.764-1.75 1.764zm13.5 12.268h-3v-5.604c0-3.368-4-3.113-4 0v5.604h-3v-11h3v1.765c1.396-2.586 7-2.777 7 2.476v6.759z" />
                        </svg>
                        LinkedIn
                    </button>
                </div>

                <div className={styles.divider}>
                    <span className={styles.dividerLine} />
                    <span className={styles.dividerText}>or</span>
                    <span className={styles.dividerLine} />
                </div>

                {error && (
                    <div className={styles.errorMessage}>
                        {error}
                        {isEmailUnconfirmed && (
                            <Link href="/auth/resend-verification" className={styles.resendLink}>
                                Resend email?
                            </Link>
                        )}
                    </div>
                )}

                <form className={styles.form} onSubmit={handleSubmit}>
                    <div className={styles.fieldGroup}>
                        <div className={styles.labelRow}>
                            <label className={styles.label} htmlFor="email">Email address</label>
                            {/* Show admin badge when admin email is detected */}
                            {isAdminEmail && (
                                <span style={{
                                    fontSize: '0.68rem',
                                    fontWeight: 700,
                                    color: '#6366f1',
                                    background: 'rgba(99,102,241,0.08)',
                                    border: '1px solid rgba(99,102,241,0.2)',
                                    borderRadius: '100px',
                                    padding: '2px 8px',
                                    letterSpacing: '0.04em',
                                    textTransform: 'uppercase',
                                }}>
                                    Admin Account
                                </span>
                            )}
                        </div>
                        <div className={styles.inputWrap}>
                            <input
                                id="email"
                                type="email"
                                className={styles.input}
                                placeholder="name@company.com"
                                value={email}
                                onChange={e => setEmail(e.target.value)}
                                required
                                autoComplete="email"
                            />
                        </div>
                    </div>

                    <div className={styles.fieldGroup}>
                        <div className={styles.labelRow}>
                            <label className={styles.label} htmlFor="password">Password</label>
                            {/* Dynamically route admin emails to the admin forgot-password page */}
                            <Link
                                href={isAdminEmail ? '/admin/forgot-password' : '/forgot-password'}
                                className={styles.forgotLink}
                            >
                                Forgot password?
                            </Link>
                        </div>
                        <div className={styles.inputWrap}>
                            <input
                                id="password"
                                type={showPassword ? 'text' : 'password'}
                                className={styles.input}
                                placeholder="••••••••"
                                value={password}
                                onChange={e => setPassword(e.target.value)}
                                required
                                autoComplete="current-password"
                            />
                            <button
                                type="button"
                                className={styles.eyeBtn}
                                onClick={() => setShowPassword(!showPassword)}
                            >
                                {showPassword ? (
                                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
                                        <line x1="1" y1="1" x2="23" y2="23" />
                                    </svg>
                                ) : (
                                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                                        <circle cx="12" cy="12" r="3" />
                                    </svg>
                                )}
                            </button>
                        </div>
                    </div>

                    <button
                        type="submit"
                        className={styles.submitBtn}
                        disabled={isLoading}
                    >
                        {isLoading ? 'Signing in...' : 'Sign In'}
                    </button>
                </form>

                <div className={styles.footer}>
                    <p>
                        Don&apos;t have an account?{' '}
                        <Link href="/signup" className={styles.footerLink}>Sign up</Link>
                    </p>
                    <div style={{ marginTop: '0.75rem', fontSize: '0.8rem' }}>
                        <Link href="/admin/login" className={styles.footerLink} style={{ opacity: 0.7 }}>
                            Admin Portal Access
                        </Link>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import { useSearchParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import Image from 'next/image';
import { insforge } from '@/lib/insforge';
import { validateResetPassword } from '@/lib/validation/auth';
import styles from '../forgot-password/forgot.module.css';

export default function ResetPasswordPage() {
    const router = useRouter();
    const searchParams = useSearchParams();
    const token = searchParams.get('token');
    const email = searchParams.get('email');

    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [success, setSuccess] = useState(false);
    const [error, setError] = useState('');

    useEffect(() => {
        if (!token) {
            setError('Invalid or missing reset token. Please try again from the forgot password page.');
        }
    }, [token]);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        if (!token) {
            setError('Missing reset token.');
            setIsLoading(false);
            return;
        }

        // 1. Validate
        const validation = validateResetPassword({ password, confirmPassword });
        if (!validation.success) {
            const firstError = Object.values(validation.errors || {})[0];
            setError(firstError as string || 'Invalid input.');
            setIsLoading(false);
            return;
        }

        try {
            // 2. Call SDK
            const { error: resetError } = await insforge.auth.resetPassword({
                newPassword: password,
                otp: token,
            });

            if (resetError) {
                setError(resetError.message);
                setIsLoading(false);
                return;
            }

            setSuccess(true);
        } catch (err: any) {
            setError(err.message || 'An unexpected error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.page}>
            <div className={styles.bgGlow1} />
            <div className={styles.bgGlow2} />
            <div className={styles.gridOverlay} />

            <div className={styles.card}>
                <Link href="/" className={styles.logoWrap}>
                    <Image
                        src="/TalentMesh_page-0002-removebg-preview.png"
                        alt="TalentMesh"
                        width={150}
                        height={42}
                        unoptimized
                        className={styles.logoImg}
                    />
                </Link>

                {!success ? (
                    <>
                        <div className={styles.header}>
                            <div className={styles.iconCircle}>
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--primary-blue)" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3L22 7l-3-3y-3-3" />
                                    <circle cx="11" cy="13" r="3" fill="var(--primary-blue)" opacity="0.2" />
                                    <path d="M12 22s-8-4.5-8-11.8A8 8 0 0 1 12 2a8 8 0 0 1 8 8.2c0 7.3-8 11.8-8 11.8z" stroke="var(--primary-blue)" strokeWidth="1.5" />
                                </svg>
                            </div>
                            <h1 className={styles.title}>New password</h1>
                            <p className={styles.subtitle}>
                                Set your new password for <br/>
                                <strong style={{ color: 'var(--primary-blue)' }}>{email || 'your account'}</strong>
                            </p>
                        </div>

                        <form className={styles.form} onSubmit={handleSubmit}>
                            {error && <div className={styles.errorAlert}>{error}</div>}

                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="new-password">New Password</label>
                                <div className={styles.inputWrap}>
                                    <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                                        <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                                    </svg>
                                    <input
                                        id="new-password"
                                        type="password"
                                        className={styles.input}
                                        placeholder="Min. 8 characters"
                                        value={password}
                                        onChange={e => setPassword(e.target.value)}
                                        required
                                        autoComplete="new-password"
                                    />
                                </div>
                            </div>

                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="confirm-password">Confirm Password</label>
                                <div className={styles.inputWrap}>
                                    <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                                        <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                                    </svg>
                                    <input
                                        id="confirm-password"
                                        type="password"
                                        className={styles.input}
                                        placeholder="Repeat your password"
                                        value={confirmPassword}
                                        onChange={e => setConfirmPassword(e.target.value)}
                                        required
                                        autoComplete="new-password"
                                    />
                                </div>
                            </div>

                            <button
                                type="submit"
                                className={styles.submitBtn}
                                disabled={isLoading || !token}
                            >
                                {isLoading ? (
                                    <span className={styles.spinnerWrap}>
                                        <span className={styles.spinner} />
                                        Updating...
                                    </span>
                                ) : 'Reset Password'}
                            </button>
                        </form>
                    </>
                ) : (
                    <div className={styles.successState}>
                        <div className={styles.successIcon}>
                            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#10b981" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <polyline points="20 6 9 17 4 12" />
                            </svg>
                        </div>
                        <h1 className={styles.title}>Password update successful</h1>
                        <p className={styles.subtitle}>
                            Your password has been changed successfully. <br/>
                            You can now sign in with your new password.
                        </p>
                        <Link href="/login" className={`${styles.submitBtn} ${styles.successLink}`}>
                            Go to Sign In
                        </Link>
                    </div>
                )}

                <p className={styles.backLine}>
                    Back to{' '}
                    <Link href="/login" className={styles.backLink}>
                        Sign in
                    </Link>
                </p>
            </div>
        </div>
    );
}

"use client";
import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import { UserRole } from '@/types/auth';
import { insforge } from '@/lib/insforge';
import { signupSchema } from '@/lib/validation/auth';
import styles from './signup.module.css';

type Role = 'job_seeker' | 'employer' | '';

export default function SignupPage() {
    const [step, setStep] = useState(1);
    const [role, setRole] = useState<Role>('');
    const [formData, setFormData] = useState({
        firstName: '',
        lastName: '',
        email: '',
        password: '',
        confirmPassword: '',
        company: '',
        agree: false,
    });
    const [showPassword, setShowPassword] = useState(false);
    const [otp, setOtp] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
    const [showNotice, setShowNotice] = useState(false);
    const router = useRouter();

    const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : value
        }));
    };

    const { signUp, login } = useAuth();
    const [error, setError] = useState('');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');
        setFieldErrors({});

        // 1. Password confirmation check
        if (formData.password !== formData.confirmPassword) {
            setFieldErrors({ confirmPassword: 'Passwords do not match' });
            setIsLoading(false);
            return;
        }

        const fullName = `${formData.firstName} ${formData.lastName}`.trim();
        const userRole: UserRole = role === 'job_seeker' ? 'candidate' : 'recruiter';

        // 2. Validate with signupSchema
        const validation = signupSchema.safeParse({
            name: fullName,
            email: formData.email,
            password: formData.password,
            role: userRole,
        });

        if (!validation.success) {
            const errors: Record<string, string> = {};
            validation.error.issues.forEach(issue => {
                const path = issue.path[0]?.toString();
                if (path === 'name') {
                    errors.firstName = issue.message;
                } else if (path) {
                    errors[path] = issue.message;
                }
            });
            setFieldErrors(errors);
            setIsLoading(false);
            return;
        }

        try {
            // 3. Call signUp from AuthContext
            const result = await signUp(
                formData.email,
                formData.password,
                userRole,
                fullName
            );

            if (result.error) {
                setError(result.error);
                setIsLoading(false);
                return;
            }

            if (result.requireEmailVerification) {
                setStep(3);
                setIsLoading(false);
                return;
            }

            // 5. Success! Redirection
            if (userRole === 'candidate') {
                router.push('/onboarding/candidate');
            } else {
                router.push('/onboarding/recruiter/setup');
            }
        } catch (err: any) {
            setError(err.message || 'An unexpected error occurred. Please try again.');
            setIsLoading(false);
        }
    };

    const handleVerify = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        try {
            const { data, error: verifyError } = await insforge.auth.verifyEmail({
                email: formData.email,
                otp,
            });

            if (verifyError) throw new Error(verifyError.message);
            if (!data?.user) throw new Error('Verification failed. Please try again.');

            const userId = data.user.id;
            const userRole = role === 'job_seeker' ? 'candidate' : 'recruiter';

            // Generate role-specific ID
            const prefix = userRole === 'recruiter' ? 'recr' : 'cand';
            const roleId = `${prefix}_${Math.random().toString(36).substring(2, 10)}`;

            // Create profile
            const { error: profileError } = await insforge.database
                .from('profiles')
                .insert([{
                    id: userId,
                    email: formData.email,
                    role: userRole,
                    role_id: roleId,
                    name: `${formData.firstName} ${formData.lastName}`
                }]);

            if (profileError) throw new Error(profileError.message);

            // Log activity
            await insforge.database.from('activity').insert([{
                user_id: userId,
                description: `Joined Talentmesh as ${userRole}`,
                type: 'signup'
            }]);

            const actualToken = data.accessToken || (data as any).session?.access_token || (data as any).access_token || '';
            console.log('Verify successful! data:', data);

            login(actualToken, {
                id: userId,
                email: formData.email,
                name: `${formData.firstName} ${formData.lastName}`,
                role: userRole as any,
                avatar_url: null
            });

            // Redirect based on role
            if (userRole === 'candidate') {
                router.push('/onboarding/candidate');
            } else {
                router.push('/onboarding/recruiter/setup');
            }

        } catch (err: any) {
            setError(err.message);
            setIsLoading(false);
        }
    };

    const handleGoogleSignup = async () => {
        if (!role) return;
        try {
            setError('');
            const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || window.location.origin;
            const { error: authError } = await insforge.auth.signInWithOAuth({
                provider: 'google',
                redirectTo: `${siteUrl}/auth/callback?role=${role}`,
            });
            if (authError) throw authError;
        } catch (err: any) {
            setError('Failed to initiate Google signup. Please try again.');
        }
    };

    const handleLinkedInSignup = async () => {
        if (!role) return;
        try {
            setError('');
            const siteUrl = process.env.NEXT_PUBLIC_SITE_URL || window.location.origin;
            const { error: authError } = await insforge.auth.signInWithOAuth({
                provider: 'linkedin',
                redirectTo: `${siteUrl}/auth/callback?role=${role}`,
            });
            if (authError) throw authError;
        } catch (err: any) {
            setError('Failed to initiate LinkedIn signup. Please verify it is enabled in your dashboard.');
        }
    };

    const passwordStrength = () => {
        const p = formData.password;
        if (!p) return 0;
        let score = 0;
        if (p.length >= 8) score++;
        if (/[A-Z]/.test(p)) score++;
        if (/[0-9]/.test(p)) score++;
        if (/[^A-Za-z0-9]/.test(p)) score++;
        return score;
    };

    const strength = passwordStrength();
    const strengthLabel = ['', 'Weak', 'Fair', 'Good', 'Strong'][strength];
    const strengthColor = ['', '#ef4444', '#f59e0b', '#22c55e', '#10b981'][strength];

    return (
        <div className={styles.page}>
            {/* Background decorations */}
            <div className={styles.bgGlow1} />
            <div className={styles.bgGlow2} />
            <div className={styles.gridOverlay} />

            <div className={styles.card}>
                {/* Logo */}
                <Link href="/" className={styles.logoWrap}>
                    <Image
                        src="/TalentMesh_page-0002-removebg-preview.png"
                        alt="TalentMesh"
                        width={140}
                        height={40}
                        unoptimized
                        className={styles.logoImg}
                    />
                </Link>

                {/* Progress stepper */}
                <div className={styles.progressSteps}>
                    <div className={`${styles.progressStep} ${step >= 1 ? styles.progressActive : ''}`}>
                        <span className={styles.progressDot}>
                            {step > 1 ? (
                                <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                                    <polyline points="20 6 9 17 4 12" />
                                </svg>
                            ) : '1'}
                        </span>
                        <span className={styles.progressLabel}>Role</span>
                    </div>
                    <div className={`${styles.progressLine} ${step >= 2 ? styles.progressLineActive : ''}`} />
                    <div className={`${styles.progressStep} ${step >= 2 ? styles.progressActive : ''}`}>
                        <span className={styles.progressDot}>2</span>
                        <span className={styles.progressLabel}>Details</span>
                    </div>
                </div>

                {/* Header */}
                <div className={styles.header}>
                    <h1 className={styles.title}>
                        {step === 1 ? 'Get started free' : 'Almost there'}
                    </h1>
                    <p className={styles.subtitle}>
                        {step === 1 ? (
                            <>Join thousands of professionals. Already a member? <Link href="/login" className={styles.switchLink}>Sign in</Link></>
                        ) : (
                            <>Fill in your details to create your account</>
                        )}
                    </p>
                </div>

                {/* STEP 1 — Role Selection */}
                {step === 1 && (
                    <div className={styles.stepContent}>
                        <div className={styles.roleCards}>
                            <button
                                type="button"
                                className={`${styles.roleCard} ${role === 'job_seeker' ? styles.roleCardActive : ''}`}
                                onClick={() => setRole('job_seeker')}
                                id="role-job-seeker"
                            >
                                <div className={styles.roleIconWrap}>
                                    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" />
                                        <circle cx="12" cy="7" r="4" />
                                    </svg>
                                </div>
                                <div className={styles.roleContent}>
                                    <span className={styles.roleTitle}>Job Seeker</span>
                                    <span className={styles.roleDesc}>Discover your dream career with AI-matched opportunities</span>
                                </div>
                                <div className={styles.roleCheck}>
                                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                                        <polyline points="20 6 9 17 4 12" />
                                    </svg>
                                </div>
                            </button>

                            <button
                                type="button"
                                className={`${styles.roleCard} ${role === 'employer' ? styles.roleCardActive : ''}`}
                                onClick={() => setRole('employer')}
                                id="role-employer"
                            >
                                <div className={styles.roleIconWrap}>
                                    <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <rect x="2" y="7" width="20" height="14" rx="2" ry="2" />
                                        <path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16" />
                                    </svg>
                                </div>
                                <div className={styles.roleContent}>
                                    <span className={styles.roleTitle}>Employer / Recruiter</span>
                                    <span className={styles.roleDesc}>Hire top talent with AI-powered sourcing & matching</span>
                                </div>
                                <div className={styles.roleCheck}>
                                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                                        <polyline points="20 6 9 17 4 12" />
                                    </svg>
                                </div>
                            </button>
                        </div>

                        {/* Divider */}
                        <div className={styles.divider}>
                            <span className={styles.dividerLine} />
                            <span className={styles.dividerText}>or sign up with</span>
                            <span className={styles.dividerLine} />
                        </div>

                        {/* Social */}
                        <div className={styles.socialRow}>
                            <button className={styles.socialBtn} type="button" onClick={handleGoogleSignup} disabled={!role}>
                                <svg width="18" height="18" viewBox="0 0 24 24" fill="none">
                                    <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4" />
                                    <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853" />
                                    <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05" />
                                    <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335" />
                                </svg>
                                Google
                            </button>
                            <button className={styles.socialBtn} type="button" onClick={handleLinkedInSignup} disabled={!role}>
                                <svg width="18" height="18" viewBox="0 0 24 24" fill="#0A66C2">
                                    <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433a2.062 2.062 0 0 1-2.063-2.065 2.064 2.064 0 1 1 2.063 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z" />
                                </svg>
                                LinkedIn
                            </button>
                        </div>

                        <button
                            className={styles.nextBtn}
                            onClick={() => { if (role) setStep(2); }}
                            disabled={!role}
                            type="button"
                        >
                            Continue
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <line x1="5" y1="12" x2="19" y2="12" />
                                <polyline points="12 5 19 12 12 19" />
                            </svg>
                        </button>
                    </div>
                )}

                {/* STEP 2 — Details Form */}
                {step === 2 && (
                    <form className={styles.form} onSubmit={handleSubmit}>
                        {error && <div style={{ color: '#ef4444', fontSize: '0.85rem', textAlign: 'center', marginBottom: '1rem', padding: '0.5rem', background: '#fef2f2', borderRadius: '8px' }}>{error}</div>}
                        <div className={styles.nameRow}>
                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="firstName">First name</label>
                                <input
                                    id="firstName" name="firstName" type="text"
                                    className={`${styles.input} ${fieldErrors.firstName ? styles.inputError : ''}`} 
                                    placeholder="John"
                                    value={formData.firstName} onChange={handleChange}
                                    required autoComplete="given-name"
                                />
                                {fieldErrors.firstName && <span className={styles.errorText}>{fieldErrors.firstName}</span>}
                            </div>
                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="lastName">Last name</label>
                                <input
                                    id="lastName" name="lastName" type="text"
                                    className={`${styles.input} ${fieldErrors.lastName ? styles.inputError : ''}`} 
                                    placeholder="Doe"
                                    value={formData.lastName} onChange={handleChange}
                                    required autoComplete="family-name"
                                />
                                {fieldErrors.lastName && <span className={styles.errorText}>{fieldErrors.lastName}</span>}
                            </div>
                        </div>

                        <div className={styles.fieldGroup}>
                            <label className={styles.label} htmlFor="signup-email">
                                {role === 'employer' ? 'Work email' : 'Email address'}
                            </label>
                            <div className={styles.inputWrap}>
                                <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" />
                                    <polyline points="22,6 12,13 2,6" />
                                </svg>
                                <input
                                    id="signup-email" name="email" type="email"
                                    className={`${styles.input} ${styles.inputWithIcon} ${fieldErrors.email ? styles.inputError : ''}`}
                                    placeholder={role === 'employer' ? 'you@company.com' : 'you@email.com'}
                                    value={formData.email} onChange={handleChange}
                                    required autoComplete="email"
                                />
                            </div>
                            {fieldErrors.email && <span className={styles.errorText}>{fieldErrors.email}</span>}
                        </div>

                        {role === 'employer' && (
                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="company">Company name</label>
                                <div className={styles.inputWrap}>
                                    <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <rect x="2" y="7" width="20" height="14" rx="2" ry="2" />
                                        <path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16" />
                                    </svg>
                                    <input
                                        id="company" name="company" type="text"
                                        className={`${styles.input} ${styles.inputWithIcon}`} placeholder="Your company"
                                        value={formData.company} onChange={handleChange}
                                        autoComplete="organization"
                                    />
                                </div>
                            </div>
                        )}

                        <div className={styles.fieldGroup}>
                            <label className={styles.label} htmlFor="signup-password">Password</label>
                            <div className={styles.inputWrap}>
                                <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                                    <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                                </svg>
                                <input
                                    id="signup-password" name="password"
                                    type={showPassword ? 'text' : 'password'}
                                    className={`${styles.input} ${styles.inputWithIcon} ${fieldErrors.password ? styles.inputError : ''}`} 
                                    placeholder="Min. 8 characters"
                                    value={formData.password} onChange={handleChange}
                                    required autoComplete="new-password"
                                />
                                <button type="button" className={styles.eyeBtn} onClick={() => setShowPassword(!showPassword)} aria-label="Toggle password">
                                    {showPassword ? (
                                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                            <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24" />
                                            <line x1="1" y1="1" x2="23" y2="23" />
                                        </svg>
                                    ) : (
                                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                            <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z" />
                                            <circle cx="12" cy="12" r="3" />
                                        </svg>
                                    )}
                                </button>
                            </div>
                            {fieldErrors.password && <span className={styles.errorText}>{fieldErrors.password}</span>}

                            {formData.password && (
                                <div className={styles.strengthBar}>
                                    <div className={styles.strengthSegments}>
                                        {[1, 2, 3, 4].map(i => (
                                            <div
                                                key={i}
                                                className={styles.strengthSegment}
                                                style={{ background: i <= strength ? strengthColor : '#e5e7eb' }}
                                            />
                                        ))}
                                    </div>
                                    <span className={styles.strengthLabel} style={{ color: strengthColor }}>
                                        {strengthLabel}
                                    </span>
                                </div>
                            )}
                        </div>

                        <div className={styles.fieldGroup}>
                            <label className={styles.label} htmlFor="confirm-password">Confirm Password</label>
                            <div className={styles.inputWrap}>
                                <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                    <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                                    <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                                </svg>
                                <input
                                    id="confirm-password" name="confirmPassword"
                                    type={showPassword ? 'text' : 'password'}
                                    className={`${styles.input} ${styles.inputWithIcon} ${fieldErrors.confirmPassword ? styles.inputError : ''}`} 
                                    placeholder="Confirm your password"
                                    value={formData.confirmPassword} onChange={handleChange}
                                    required autoComplete="new-password"
                                />
                            </div>
                            {fieldErrors.confirmPassword && <span className={styles.errorText}>{fieldErrors.confirmPassword}</span>}
                        </div>

                        <label className={styles.checkboxLabel}>
                            <input
                                type="checkbox" name="agree"
                                className={styles.checkbox}
                                checked={formData.agree}
                                onChange={handleChange}
                                required
                            />
                            <span className={styles.checkboxCustom}>
                                <svg viewBox="0 0 12 10" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <polyline points="1.5 5 4.5 8 10.5 2" />
                                </svg>
                            </span>
                            <span className={styles.checkboxText}>
                                I agree to the{' '}
                                <Link href="/terms" className={styles.inlineLink}>Terms</Link>
                                {' '}&{' '}
                                <Link href="/privacy" className={styles.inlineLink}>Privacy Policy</Link>
                            </span>
                        </label>

                        <div className={styles.formActions}>
                            <button type="button" className={styles.backBtn} onClick={() => setStep(1)}>
                                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                    <line x1="19" y1="12" x2="5" y2="12" />
                                    <polyline points="12 19 5 12 12 5" />
                                </svg>
                                Back
                            </button>
                            <button
                                type="submit"
                                className={styles.submitBtn}
                                disabled={isLoading || !formData.agree}
                            >
                                {isLoading ? (
                                    <span className={styles.spinnerWrap}>
                                        <span className={styles.spinner} />
                                        Creating...
                                    </span>
                                ) : (
                                    <>
                                        Create Account
                                        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                            <line x1="5" y1="12" x2="19" y2="12" />
                                            <polyline points="12 5 19 12 12 19" />
                                        </svg>
                                    </>
                                )}
                            </button>
                        </div>
                    </form>
                )}

                {/* STEP 3 — OTP Verification */}
                {step === 3 && (
                    <form className={styles.form} onSubmit={handleVerify}>
                        {error && <div style={{ color: '#ef4444', fontSize: '0.85rem', textAlign: 'center', marginBottom: '1rem', padding: '0.5rem', background: '#fef2f2', borderRadius: '8px' }}>{error}</div>}

                        <div style={{ textAlign: 'center', marginBottom: '2rem' }}>
                            <div style={{ marginBottom: '1rem', display: 'flex', justifyContent: 'center' }}>
                                <svg width="48" height="48" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z" />
                                    <polyline points="22,6 12,13 2,6" />
                                </svg>
                            </div>
                            <h2 style={{ fontSize: '1.5rem', fontWeight: 600, color: '#111827', marginBottom: '0.5rem' }}>Check your email</h2>
                            <p style={{ color: '#4b5563', lineHeight: 1.5 }}>
                                We sent a 6-digit verification code to<br /><strong>{formData.email}</strong>
                            </p>
                        </div>

                        <div className={styles.fieldGroup}>
                            <label className={styles.label} htmlFor="otp-code">Verification Code</label>
                            <input
                                id="otp-code" type="text"
                                className={styles.input} placeholder="123456"
                                value={otp} onChange={(e) => setOtp(e.target.value)}
                                required maxLength={6}
                                style={{ textAlign: 'center', letterSpacing: '0.5em', fontSize: '1.2rem', fontWeight: 600 }}
                            />
                        </div>

                        <button
                            type="submit"
                            className={styles.submitBtn}
                            disabled={isLoading || otp.length < 6}
                        >
                            {isLoading ? (
                                <span className={styles.spinnerWrap}>
                                    <span className={styles.spinner} />
                                    Verifying...
                                </span>
                            ) : (
                                'Verify & Continue'
                            )}
                        </button>
                    </form>
                )}
            </div>

            {/* Bottom terms */}
            <p className={styles.terms}>
                Protected by TalentMesh ·{' '}
                <Link href="/terms" className={styles.termsLink}>Terms</Link>
                {' '}&{' '}
                <Link href="/privacy" className={styles.termsLink}>Privacy</Link>
            </p>
        </div>
    );
}

/* ============================
   SIGNUP PAGE — Centered Card
   Full-screen, no scroll, form in center
   ============================ */

.page {
    width: 100vw;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8fafc;
    position: relative;
    overflow: hidden;
    font-family: var(--font-inter), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* Background decorations */
.bgGlow1 {
    position: absolute;
    top: -15%;
    left: -8%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.08) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 20s ease-in-out infinite alternate;
}

.bgGlow2 {
    position: absolute;
    bottom: -12%;
    right: -8%;
    width: 450px;
    height: 450px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.06) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 16s ease-in-out infinite alternate-reverse;
}

@keyframes glowPulse {
    0% {
        transform: scale(1);
        opacity: 0.7;
    }

    100% {
        transform: scale(1.15);
        opacity: 1;
    }
}

.gridOverlay {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 0, 0, 0.02) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
}

/* Card */
.card {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 430px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 20px;
    padding: 2rem 2.25rem;
    box-shadow:
        0 4px 6px -1px rgba(0, 0, 0, 0.03),
        0 10px 30px -5px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    gap: 1.1rem;
    animation: cardEnter 0.5s ease-out;
}

@keyframes cardEnter {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

/* Logo */
.logoWrap {
    display: flex;
    justify-content: center;
    text-decoration: none;
}

.logoImg {
    filter: none;
    opacity: 1;
}

/* Progress stepper */

.progressSteps {
    display: flex;
    align-items: center;
}

.progressStep {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    transition: opacity 0.3s ease;
}

.progressStep:not(.progressActive) {
    opacity: 0.3;
}

.progressDot {
    width: 26px;
    height: 26px;
    border-radius: 50%;
    background: #f1f5f9;
    border: 2px solid #e2e8f0;
    color: #94a3b8;
    font-size: 0.68rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.3s ease;
}

.progressStep.progressActive .progressDot {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
    color: white;
    box-shadow: 0 2px 6px rgba(0, 123, 255, 0.3);
}

.progressLabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: #94a3b8;
}

.progressStep.progressActive .progressLabel {
    color: #374151;
}

.progressLine {
    flex: 1;
    height: 2px;
    background: #e5e7eb;
    margin: 0 0.6rem;
    transition: background 0.3s ease;
    border-radius: 1px;
}

.progressLine.progressLineActive {
    background: var(--primary-blue);
}

/* Header */
.header {
    text-align: center;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.title {
    font-size: 1.4rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.subtitle {
    font-size: 0.8rem;
    color: #94a3b8;
}

.switchLink {
    color: var(--primary-blue);
    font-weight: 600;
    text-decoration: none;
    transition: color 0.2s;
}

.switchLink:hover {
    color: #0056d6;
}

/* Step content */
.stepContent {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.stepLabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: #94a3b8;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

/* Role cards */
.roleCards {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.roleCard {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    padding: 0.85rem 1rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 11px;
    cursor: pointer;
    transition: all 0.25s ease;
    text-align: left;
    width: 100%;
    font-family: inherit;
}

.roleCard:hover {
    border-color: #66b3ff;
    background: #f8fafc;
}

.roleCard.roleCardActive {
    border-color: var(--primary-blue);
    background: #e6f2ff;
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
}

.roleIconWrap {
    width: 40px;
    height: 40px;
    background: #f1f5f9;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    flex-shrink: 0;
    transition: all 0.2s ease;
}

.roleCard.roleCardActive .roleIconWrap {
    background: #cce4ff;
    color: var(--primary-blue);
}

.roleContent {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
}

.roleTitle {
    font-size: 0.85rem;
    font-weight: 700;
    color: #0f172a;
}

.roleDesc {
    font-size: 0.72rem;
    color: #94a3b8;
}

.roleCheck {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    background: var(--primary-blue);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    flex-shrink: 0;
    opacity: 0;
    transform: scale(0.5);
    transition: all 0.2s ease;
}

.roleCard.roleCardActive .roleCheck {
    opacity: 1;
    transform: scale(1);
}

/* Divider */
.divider {
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.dividerLine {
    flex: 1;
    height: 1px;
    background: #e5e7eb;
}

.dividerText {
    font-size: 0.72rem;
    color: #94a3b8;
    font-weight: 500;
    white-space: nowrap;
}

/* Social */
.socialRow {
    display: flex;
    gap: 0.6rem;
}

.socialBtn {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    padding: 0.55rem 0.75rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #374151;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.socialBtn:hover {
    background: #f9fafb;
    border-color: #d1d5db;
}

/* Next button */
.nextBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    width: 100%;
    padding: 0.7rem 1.5rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 9px;
    font-size: 0.88rem;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.nextBtn:hover:not(:disabled) {
    background: #0056d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.nextBtn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    box-shadow: none;
}

/* Form (step 2) */
.form {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
}

.nameRow {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.6rem;
}

.fieldGroup {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.label {
    font-size: 0.75rem;
    font-weight: 600;
    color: #374151;
}

.inputWrap {
    position: relative;
    display: flex;
    align-items: center;
}

.inputIcon {
    position: absolute;
    left: 0.75rem;
    color: #c0c7d0;
    pointer-events: none;
    z-index: 1;
    transition: color 0.2s ease;
}

.inputWrap:focus-within .inputIcon {
    color: var(--primary-blue);
}

.input {
    width: 100%;
    padding: 0.62rem 0.85rem;
    background: #f9fafb;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #0f172a;
    font-size: 0.84rem;
    font-family: inherit;
    outline: none;
    transition: all 0.2s ease;
}

.inputWithIcon {
    padding-left: 2.4rem;
}

.input::placeholder {
    color: #b0b8c4;
}

.input:focus {
    background: #ffffff;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
}

.input:hover:not(:focus) {
    border-color: #d1d5db;
}

.eyeBtn {
    position: absolute;
    right: 0.7rem;
    background: none;
    border: none;
    color: #b0b8c4;
    cursor: pointer;
    padding: 2px;
    display: flex;
    align-items: center;
    transition: color 0.2s;
}

.eyeBtn:hover {
    color: #64748b;
}

/* Strength bar */
.strengthBar {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-top: 0.2rem;
}

.strengthSegments {
    display: flex;
    gap: 3px;
    flex: 1;
}

.strengthSegment {
    height: 3px;
    flex: 1;
    border-radius: 2px;
    transition: background 0.3s ease;
}

.strengthLabel {
    font-size: 0.68rem;
    font-weight: 700;
    min-width: 32px;
    text-align: right;
}

/* Checkbox */
.checkboxLabel {
    display: flex;
    align-items: flex-start;
    gap: 0.5rem;
    cursor: pointer;
    user-select: none;
}

.checkbox {
    display: none;
}

.checkboxCustom {
    width: 16px;
    height: 16px;
    border: 1.5px solid #d1d5db;
    border-radius: 4px;
    background: #ffffff;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    margin-top: 1px;
}

.checkboxCustom svg {
    width: 9px;
    height: 9px;
    opacity: 0;
    transition: opacity 0.15s ease;
}

.checkbox:checked+.checkboxCustom {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
}

.checkbox:checked+.checkboxCustom svg {
    opacity: 1;
}

.checkboxText {
    font-size: 0.75rem;
    color: #64748b;
    line-height: 1.45;
}

.inlineLink {
    color: var(--primary-blue);
    text-decoration: none;
    font-weight: 600;
}

.inlineLink:hover {
    text-decoration: underline;
}

/* Actions */
.formActions {
    display: flex;
    gap: 0.55rem;
    align-items: center;
}

.backBtn {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.65rem 0.95rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #64748b;
    font-size: 0.82rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.backBtn:hover {
    background: #f9fafb;
    border-color: #d1d5db;
    color: #374151;
}

.submitBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    flex: 1;
    padding: 0.7rem 1rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 9px;
    font-size: 0.88rem;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.submitBtn:hover:not(:disabled) {
    background: #0056d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.submitBtn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    box-shadow: none;
}

.spinnerWrap {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.spinner {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(255, 255, 255, 0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Terms */
.terms {
    position: absolute;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%);
    font-size: 0.66rem;
    color: #b0b8c4;
    text-align: center;
    white-space: nowrap;
    z-index: 1;
}

.termsLink {
    color: #94a3b8;
    text-decoration: underline;
    text-underline-offset: 2px;
    transition: color 0.2s;
}

.termsLink:hover {
    color: var(--primary-blue);
}

/* Both candidate and recruiter use the same brand blue theme */

/* ============================
   RESPONSIVE
   ============================ */
@media (max-width: 480px) {
    .card {
        max-width: 100%;
        margin: 0 0.75rem;
        padding: 1.5rem 1.25rem;
        border-radius: 16px;
    }

    .title {
        font-size: 1.25rem;
    }

    .nameRow {
        grid-template-columns: 1fr;
    }

    .socialRow {
        flex-direction: column;
        gap: 0.4rem;
    }

    .formActions {
        flex-direction: column-reverse;
    }

    .backBtn {
        width: 100%;
        justify-content: center;
    }
}

@media (max-height: 750px) {
    .card {
        gap: 0.85rem;
        padding: 1.5rem 1.75rem;
    }

    .form {
        gap: 0.65rem;
    }

    .stepContent {
        gap: 0.75rem;
    }

    .input {
        padding-top: 0.55rem;
        padding-bottom: 0.55rem;
        font-size: 0.82rem;
    }

    .roleCard {
        padding: 0.7rem 0.85rem;
    }

    .nextBtn,
    .submitBtn {
        padding: 0.6rem 1rem;
    }
}

/* ============================
   ABOUT PAGE — TalentMesh
   Premium Architectural Edition
   ============================ */

.page {
    min-height: 100vh;
    background: #ffffff;
    font-family: var(--font-inter, 'Inter', sans-serif);
    color: #0f172a;
}

/* ── Stats Strip ── */
.statsStrip {
    background: linear-gradient(135deg, #0a0f1e 0%, #0d1b3e 50%, #081428 100%);
    padding: 5rem 2rem;
    color: #ffffff;
    position: relative;
    overflow: hidden;
}

.statsStrip::before {
    content: '';
    position: absolute;
    inset: 0;
    background: radial-gradient(ellipse 60% 100% at 50% 50%, rgba(0, 123, 255, 0.08) 0%, transparent 70%);
}

.statsGrid {
    max-width: 1200px;
    margin: 0 auto;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 2rem;
    position: relative;
}

.statItem {
    text-align: center;
    padding: 2rem 1rem;
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.04);
    border: 1px solid rgba(255, 255, 255, 0.06);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
}

.statItem:hover {
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(0, 123, 255, 0.3);
    transform: translateY(-4px);
    box-shadow: 0 8px 30px rgba(0, 123, 255, 0.15);
}

.statNum {
    font-size: 3rem;
    font-weight: 900;
    display: block;
    margin-bottom: 0.75rem;
    font-variant-numeric: tabular-nums;
    background: linear-gradient(135deg, #60a5fa, #3b82f6);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    text-shadow: none;
}

.statLabel {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: rgba(255, 255, 255, 0.45);
    font-weight: 700;
}

/* ── Our Story (Split Layout) ── */
.storySection {
    padding: 8rem 2rem;
    max-width: 1200px;
    margin: 0 auto;
}

.storyGrid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6rem;
    align-items: center;
}

.storyTag {
    color: #3b82f6;
    font-weight: 800;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 1.25rem;
    padding: 0.4rem 1rem;
    background: rgba(59, 130, 246, 0.08);
    border-radius: 50px;
    border: 1px solid rgba(59, 130, 246, 0.15);
}

.storyTitle {
    font-size: 2.5rem;
    font-weight: 900;
    margin-bottom: 1.5rem;
    letter-spacing: -0.03em;
    line-height: 1.1;
}

.storyText {
    font-size: 1.05rem;
    line-height: 1.8;
    color: #475569;
    margin-bottom: 1.5rem;
}

/* ── Mission Cards ── */
.missionVisual {
    display: flex;
    flex-direction: column;
    gap: 1.5rem;
}

.missionImageWrapper {
    position: relative;
    width: 100%;
    aspect-ratio: 16/9;
    border-radius: 24px;
    overflow: hidden;
    box-shadow: 0 20px 50px rgba(0, 0, 0, 0.1);
    margin-top: 2rem;
}

.missionImg {
    object-fit: cover;
    transition: transform 0.6s ease;
}

.missionImageWrapper:hover .missionImg {
    transform: scale(1.03);
}

.missionCard {
    padding: 2rem;
    border-radius: 20px;
    border: 1px solid rgba(0, 0, 0, 0.06);
    transition: all 0.4s cubic-bezier(0.4, 0, 0.2, 1);
    position: relative;
    overflow: hidden;
}

.missionCard::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    width: 4px;
    height: 100%;
    border-radius: 0 4px 4px 0;
    transition: all 0.4s ease;
}

.missionCardProblem {
    background: linear-gradient(135deg, #fef2f2 0%, #fff1f2 100%);
    box-shadow: 0 4px 20px rgba(239, 68, 68, 0.06);
}

.missionCardProblem::before {
    background: linear-gradient(to bottom, #ef4444, #f97316);
}

.missionCardProblem:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 30px rgba(239, 68, 68, 0.12);
}

.missionCardSolution {
    background: linear-gradient(135deg, #f0fdf4 0%, #ecfdf5 100%);
    box-shadow: 0 4px 20px rgba(16, 185, 129, 0.06);
}

.missionCardSolution::before {
    background: linear-gradient(to bottom, #10b981, #059669);
}

.missionCardSolution:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 30px rgba(16, 185, 129, 0.12);
}

.missionCardTitle {
    font-size: 1rem;
    font-weight: 800;
    margin-bottom: 0.5rem;
    display: flex;
    align-items: center;
    gap: 8px;
}

.missionCardTitleProblem {
    color: #dc2626;
}

.missionCardTitleSolution {
    color: #059669;
}

.missionCardText {
    font-size: 0.92rem;
    color: #475569;
    line-height: 1.6;
}

.missionCardTextSolution {
    color: #0f172a;
    font-weight: 600;
}

/* ── Innovation Labs Visual ── */
.labsVisual {
    background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
    border-radius: 24px;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 4rem;
    min-height: 300px;
    position: relative;
    overflow: hidden;
}

.labsVisual::before {
    content: '';
    position: absolute;
    width: 200px;
    height: 200px;
    background: radial-gradient(circle, rgba(59, 130, 246, 0.3) 0%, transparent 70%);
    border-radius: 50%;
    animation: labsPulse 4s ease-in-out infinite;
}

.labsVisual::after {
    content: '';
    position: absolute;
    width: 300px;
    height: 300px;
    background: radial-gradient(circle, rgba(129, 140, 248, 0.15) 0%, transparent 70%);
    border-radius: 50%;
    animation: labsPulse 4s ease-in-out infinite reverse;
}

.labsIcon {
    position: relative;
    z-index: 2;
    color: #60a5fa;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 1rem;
}

.labsIconSvg {
    width: 64px;
    height: 64px;
    color: #60a5fa;
    filter: drop-shadow(0 0 20px rgba(96, 165, 250, 0.4));
}

.labsIconLabel {
    font-size: 0.82rem;
    font-weight: 800;
    color: rgba(255, 255, 255, 0.5);
    text-transform: uppercase;
    letter-spacing: 0.15em;
}

@keyframes labsPulse {

    0%,
    100% {
        transform: scale(1);
        opacity: 0.6;
    }

    50% {
        transform: scale(1.3);
        opacity: 1;
    }
}

/* ── Innovation bullet list ── */
.innovationList {
    list-style: none;
    padding: 0;
    margin-top: 2rem;
}

.innovationItem {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 1.25rem;
    font-weight: 600;
    color: #0f172a;
    padding: 0.6rem 0;
    transition: transform 0.2s ease;
}

.innovationItem:hover {
    transform: translateX(4px);
}

.innovationDot {
    width: 10px;
    height: 10px;
    background: linear-gradient(135deg, #3b82f6, #60a5fa);
    border-radius: 50%;
    flex-shrink: 0;
    box-shadow: 0 0 8px rgba(59, 130, 246, 0.4);
}

/* ── Global section stats ── */
.globalStatValue {
    font-size: 2.75rem;
    font-weight: 900;
    margin-bottom: 0.5rem;
    background: linear-gradient(135deg, #60a5fa, #818cf8);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}

.globalStatLabel {
    font-weight: 600;
    opacity: 0.5;
    font-size: 0.88rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
    .storyGrid {
        grid-template-columns: 1fr;
        gap: 4rem;
    }

    .statsGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .statsGrid {
        grid-template-columns: 1fr;
    }

    .storyTitle {
        font-size: 2rem;
    }

    .statNum {
        font-size: 2.5rem;
    }
}

"use client";
import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import styles from '../login/admin-login.module.css';

export default function AdminForgotPasswordPage() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsLoading(true);
    setError('');
    setMessage('');

    try {
      // POST to the server-side API route — admin emails are NEVER checked client-side
      const res = await fetch('/api/admin/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: email.trim() }),
      });

      if (!res.ok) {
        throw new Error('Server error. Please try again.');
      }

      // Redirect to enter the OTP code
      router.push(`/admin/reset-password?email=${encodeURIComponent(email.trim())}`);
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className={styles.page}>
      <div className={styles.bgGlow} />
      <div className={styles.gridOverlay} />

      <div className={styles.container}>
        <Link href="/" className={styles.logoWrap}>
          <Image
            src="/TalentMesh_page-0002-removebg-preview.png"
            alt="TalentMesh"
            width={160}
            height={44}
            unoptimized
            style={{ height: 'auto' }}
          />
        </Link>

        <div className={styles.card}>
          <div className={styles.badgeWrap}>
            <span className={styles.badge}>Admin Portal</span>
          </div>

          <div className={styles.header}>
            <h1 className={styles.title}>Forgot Password</h1>
            <p className={styles.subtitle}>Enter your admin email to receive a reset link</p>
          </div>

          {error && <div className={styles.error}>{error}</div>}

          {message ? (
            <div style={{
              background: 'rgba(16, 185, 129, 0.08)',
              border: '1px solid rgba(16, 185, 129, 0.2)',
              color: '#6ee7b7',
              fontSize: '0.83rem',
              padding: '12px 16px',
              borderRadius: '10px',
              marginBottom: '8px',
              textAlign: 'center',
              lineHeight: 1.5,
            }}>
              {message}
            </div>
          ) : (
            <form className={styles.form} onSubmit={handleSubmit}>
              <div className={styles.fieldGroup}>
                <label className={styles.label} htmlFor="email">Admin Email Address</label>
                <div className={styles.inputWrap}>
                  <input
                    id="email"
                    type="email"
                    className={styles.input}
                    placeholder="admin@talentmesh.ai"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    disabled={isLoading}
                    autoComplete="email"
                  />
                </div>
              </div>

              <button
                type="submit"
                className={styles.submitBtn}
                disabled={isLoading}
              >
                {isLoading ? (
                  <>
                    <span className={styles.spinner} />
                    Sending...
                  </>
                ) : (
                  'Send Reset Link'
                )}
              </button>
            </form>
          )}

          <div className={styles.footer}>
            <Link href="/login" className={styles.backLink}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <line x1="19" y1="12" x2="5" y2="12" />
                <polyline points="12 19 5 12 12 5" />
              </svg>
              Back to Login
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
}

