import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@insforge/sdk';
import { insforgeAdmin } from '@/lib/insforge-admin';

export async function GET(request: NextRequest) {
    if (!insforgeAdmin) return new NextResponse('Admin client not initialized', { status: 500 });

    // 1. Verify Authorization
    const insforge = createClient({
        baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
        anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
        auth: {
            storage: {
                getItem: (key: string) => request.cookies.get(key)?.value ?? null,
                setItem: () => {},
                removeItem: () => {}
            }
        }
    } as any);

    const { data: { session } } = await insforge.auth.getCurrentSession();
    const user = session?.user;

    if (!user || (user.metadata as any)?.role !== 'super_admin') {
        return new NextResponse('Unauthorized: Admin access required', { status: 401 });
    }

    // 2. Fetch data (protected code continue below)

    const { searchParams } = new URL(request.url);
    const adminId = searchParams.get('adminId');
    const type = searchParams.get('type') || 'all';
    const activeTab = searchParams.get('activeTab');
    const search = searchParams.get('search');
    const from = searchParams.get('from');
    const to = searchParams.get('to');

    let query = insforgeAdmin.database
        .from('audit_logs')
        .select(`
            id,
            created_at,
            actor_id,
            action,
            table_name,
            record_id,
            status,
            ip_address,
            profiles:actor_id (name)
        `)
        .order('created_at', { ascending: false });

    if (activeTab === 'login') {
        query = query.ilike('action', '%security%').or('action.ilike.%login%').or('action.ilike.%mfa%');
    } else {
        if (adminId) query = query.eq('actor_id', adminId);
        if (from) query = query.gte('created_at', new Date(from).toISOString());
        if (to) query = query.lte('created_at', new Date(to).toISOString());

        if (type !== 'all') {
            if (type === 'user') query = query.ilike('action', '%user%').or('action.ilike.%recruiter%');
            if (type === 'job') query = query.ilike('action', '%job%');
            if (type === 'security') query = query.ilike('action', '%security%').or('action.ilike.%login%').or('action.ilike.%mfa%');
            if (type === 'settings') query = query.ilike('action', '%settings%');
        }
    }

    const { data, error } = await query;
    if (error) return new NextResponse(error.message, { status: 400 });

    // Convert to CSV
    const headers = ['Timestamp', 'Admin', 'Action', 'Resource', 'Status', 'IP Address'];
    const rows = (data || []).map(log => [
        new Date(log.created_at).toISOString(),
        log.profiles?.[0]?.name || 'System',
        log.action.toUpperCase(),
        `${log.table_name || ''} ${log.record_id || ''}`.trim(),
        log.status,
        log.ip_address
    ]);

    const csvContent = [
        headers.join(','),
        ...rows.map(row => row.map(cell => `"${(cell || '').replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const dateStr = new Date().toISOString().split('T')[0];

    return new NextResponse(csvContent, {
        headers: {
            'Content-Type': 'text/csv',
            'Content-Disposition': `attachment; filename="talentmesh-audit-${dateStr}.csv"`
        }
    });
}

import { NextRequest, NextResponse } from 'next/server';
import { createClient } from '@insforge/sdk';

/**
 * POST /api/admin/forgot-password
 *
 * Validates the email against the server-side ADMIN_EMAILS whitelist,
 * then sends a password-reset email via InsForge.
 *
 * Always returns 200 (generic message) so attackers cannot enumerate
 * which emails are registered as admins.
 */
export async function POST(request: NextRequest) {
  let email = '';
  try {
    const body = await request.json();
    email = (body.email || '').trim().toLowerCase();
  } catch {
    return NextResponse.json({ success: true }); // Malformed request — return generic success
  }

  if (!email) {
    return NextResponse.json({ success: true });
  }

  // --- Server-only whitelist check (ADMIN_EMAILS is NOT prefixed with NEXT_PUBLIC_) ---
  const adminEmails = (process.env.ADMIN_EMAILS || '')
    .split(',')
    .map((e) => e.trim().toLowerCase())
    .filter(Boolean);

  const isAdmin = adminEmails.includes(email);

  // If not an admin email, silently do nothing (security: no info leakage)
  if (!isAdmin) {
    return NextResponse.json({ success: true });
  }

  // --- Send password reset email via InsForge SDK ---
  try {
    const insforge = createClient({
      baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
      anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
    });

    // Note: InsForge SDK sendResetPasswordEmail only accepts { email }.
    // The redirect URL after reset must be configured in your InsForge
    // backend settings (Auth → Email Templates → Reset Password redirectTo).
    const { error } = await insforge.auth.sendResetPasswordEmail({ email });

    if (error) {
      console.error('[Admin ForgotPW] sendResetPasswordEmail error:', error.message);
      // Still return generic success — don't leak server errors to the client
    }
  } catch (err) {
    console.error('[Admin ForgotPW] Unexpected error:', err);
  }

  return NextResponse.json({ success: true });
}

import { NextResponse } from 'next/server';
import { insforgeAdmin } from '@/lib/insforge-admin';
import { createClient } from '@insforge/sdk';
import { cookies } from 'next/headers';

export async function PATCH(
  request: Request,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id: recruiterId } = await params;
  const { action } = await request.json();

  // 1. Verify admin session
  const cookieStore = await cookies();
  const token = cookieStore.get('tm_access_token')?.value;
  const role = cookieStore.get('tm_role')?.value;

  if (!token || (role !== 'admin' && role !== 'super_admin')) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  // 2. Identify the admin making the change
  // Create a temporary client to verify the user's token
  const userClient = createClient({
    baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
    anonKey: token
  });

  const { data: sessionData, error: sessionError } = await userClient.auth.getCurrentSession();

  if (sessionError || !sessionData?.session?.user) {
    console.error('Invalid session or user not found:', sessionError);
    return NextResponse.json({ error: 'Invalid admin session' }, { status: 401 });
  }
  const adminUser = sessionData.session.user;

  try {
    // 1. Check if admin client is available
    if (!insforgeAdmin) {
      return NextResponse.json({ error: 'Admin client not configured. Missing INSFORGE_SERVICE_KEY.' }, { status: 500 });
    }

    if (action === 'approve') {
      // Approve recruiter
      const { error: approveError } = await insforgeAdmin.database
        .from('recruiter_profiles')
        .update({
          is_approved: true,
          approved_by: adminUser.id,
          approved_at: new Date().toISOString()
        })
        .eq('id', recruiterId);

      if (approveError) throw approveError;

      // Insert notification for recruiter
      await insforgeAdmin.database.from('notifications').insert([{
        user_id: recruiterId,
        type: 'account_approved',
        title: 'Account Approved',
        message: 'Your recruiter account has been approved. You can now access all dashboard features.'
      }]);

      return NextResponse.json({ success: true });
    } else if (action === 'suspend') {
      // Suspend recruiter (using is_active in profiles)
      const { error: suspendError } = await insforgeAdmin.database
        .from('profiles')
        .update({ is_active: false })
        .eq('id', recruiterId);

      if (suspendError) throw suspendError;

      return NextResponse.json({ success: true });
    }

    return NextResponse.json({ error: 'Invalid action' }, { status: 400 });

  } catch (err: any) {
    console.error('Admin action error:', err);
    return NextResponse.json({ error: err.message }, { status: 500 });
  }
}

import { createClient } from '@insforge/sdk';
import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';

function isAdminEmail(email: string | null | undefined): boolean {
  if (!email) return false;

  const envEmails = process.env.ADMIN_EMAILS || process.env.NEXT_PUBLIC_ADMIN_EMAILS || '';
  return envEmails
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean)
    .includes(email.toLowerCase());
}

export async function GET() {
  const cookieStore = await cookies();
  const token = cookieStore.get('tm_access_token')?.value;

  if (!token) {
    return NextResponse.json({ user: null }, { status: 401 });
  }

  const insforge = createClient({
    baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
    anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
    edgeFunctionToken: token,
  });

  const { data: { user }, error: userError } = await insforge.auth.getCurrentUser();

  if (userError || !user) {
    return NextResponse.json({ user: null }, { status: 401 });
  }

  const { data: profile } = await insforge.database
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .single();

  const role = profile?.role || (isAdminEmail(user.email) ? 'admin' : 'candidate');

  return NextResponse.json({
    user: {
      id: user.id,
      email: user.email,
      name: profile?.name || user.email?.split('@')[0] || '',
      role: isAdminEmail(user.email) && !['admin', 'super_admin'].includes(role) ? 'admin' : role,
      avatar_url: profile?.avatar_url || null,
      company_id: profile?.company_id,
      created_at: profile?.created_at,
      mfa_enabled: profile?.mfa_enabled || false,
      password_set_at: profile?.password_set_at,
    },
  });
}

import { NextResponse } from 'next/server';

import {
  applyResumeAutofill,
  calculateCandidateProfileStrength,
  getDefaultCandidateProfile,
  normalizeCandidateProfile,
  type CandidateSettingsBundle,
} from '@/lib/candidate-profile';
import { getServerInsforgeClient } from '@/lib/server-insforge';

type CandidateLookup = {
  record: Record<string, unknown> | null;
  key: 'user_id' | 'id';
};

type AuthenticatedContext = {
  insforge: NonNullable<Awaited<ReturnType<typeof getServerInsforgeClient>>>;
  user: {
    id: string;
    email?: string | null;
  };
};

const UUID_REGEX =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

function isUuid(value: unknown): value is string {
  return typeof value === 'string' && UUID_REGEX.test(value);
}

function getStringValue(record: Record<string, unknown> | null, key: string): string {
  const value = record?.[key];
  return typeof value === 'string' ? value : '';
}

function getNullableStringValue(record: Record<string, unknown> | null, key: string): string | null {
  const value = record?.[key];
  return typeof value === 'string' && value ? value : null;
}

async function getAuthenticatedContext() {
  const insforge = await getServerInsforgeClient();

  if (!insforge) {
    return {
      error: NextResponse.json({ error: 'Unauthorized' }, { status: 401 }),
    };
  }

  const { data: userData, error } = await insforge.auth.getCurrentUser();
  if (error || !userData?.user) {
    return {
      error: NextResponse.json({ error: 'Unauthorized' }, { status: 401 }),
    };
  }

  const userId = userData.user.id;
  if (!isUuid(userId)) {
    return {
      error: NextResponse.json(
        { error: 'Authenticated user is missing a valid UUID.' },
        { status: 401 },
      ),
    };
  }

  return {
    context: {
      insforge,
      user: {
        id: userId,
        email: userData.user.email,
      },
    } satisfies AuthenticatedContext,
  };
}

async function findCandidateProfile(
  insforge: NonNullable<Awaited<ReturnType<typeof getServerInsforgeClient>>>,
  userId: string,
): Promise<CandidateLookup> {
  if (!userId) {
    throw new Error('Cannot query candidate profile without a valid authenticated user ID.');
  }

  const byUserId = await insforge.database
    .from('candidate_profiles')
    .select('*')
    .eq('user_id', userId)
    .limit(1);

  if (!byUserId.error) {
    return { record: byUserId.data?.[0] ?? null, key: 'user_id' };
  }

  const byId = await insforge.database
    .from('candidate_profiles')
    .select('*')
    .eq('id', userId)
    .limit(1);

  if (byId.error) {
    throw new Error(byId.error.message);
  }

  return { record: byId.data?.[0] ?? null, key: 'id' };
}

function buildResponse(profileRow: Record<string, unknown>, candidateRow: Record<string, unknown> | null): CandidateSettingsBundle {
  const fallbackJobType =
    typeof candidateRow?.job_type === 'string'
      ? candidateRow.job_type
      : Array.isArray(candidateRow?.job_types) && candidateRow.job_types.length > 0
        ? String(candidateRow.job_types[0])
        : candidateRow?.open_to_remote === true
          ? 'Remote'
          : '';

  const normalizedCandidate = normalizeCandidateProfile({
    ...getDefaultCandidateProfile(),
    ...candidateRow,
    job_type: fallbackJobType,
  });

  return {
    profile: {
      id: getStringValue(profileRow, 'id'),
      email: getStringValue(profileRow, 'email'),
      name: getStringValue(profileRow, 'name'),
      phone: getStringValue(profileRow, 'phone'),
      location: getStringValue(profileRow, 'location'),
      role_id: getNullableStringValue(profileRow, 'role_id'),
    },
    candidateProfile: normalizedCandidate,
  };
}

async function syncResumeAutofill(
  insforge: NonNullable<Awaited<ReturnType<typeof getServerInsforgeClient>>>,
  userId: string,
  lookup: CandidateLookup,
  bundle: CandidateSettingsBundle,
) {
  const autofilled = applyResumeAutofill(bundle.candidateProfile);
  const shouldPersist =
    autofilled.headline !== bundle.candidateProfile.headline ||
    autofilled.skills.join('|') !== bundle.candidateProfile.skills.join('|');

  if (!shouldPersist) {
    return bundle;
  }

  const nextStrength = calculateCandidateProfileStrength(bundle.profile, autofilled);
  const payload: Record<string, unknown> = {
    headline: autofilled.headline,
    skills: autofilled.skills,
    profile_strength: nextStrength,
  };

  if (lookup.record) {
    await insforge.database
      .from('candidate_profiles')
      .update(payload)
      .eq(lookup.key, userId);
  }

  return {
    ...bundle,
    candidateProfile: {
      ...autofilled,
      profile_strength: nextStrength,
    },
  };
}

export async function GET() {
  try {
    const auth = await getAuthenticatedContext();
    if (auth.error) {
      return auth.error;
    }

    const { insforge, user } = auth.context;
    const { data: profileRow, error: profileError } = await insforge.database
      .from('profiles')
      .select('*')
      .eq('id', user.id)
      .single();

    if (profileError || !profileRow) {
      return NextResponse.json({ error: profileError?.message ?? 'Profile not found' }, { status: 404 });
    }

    const lookup = await findCandidateProfile(insforge, user.id);
    const bundle = buildResponse(profileRow, lookup.record);
    const completedBundle = await syncResumeAutofill(insforge, user.id, lookup, bundle);

    return NextResponse.json(completedBundle);
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unexpected error';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function PUT(request: Request) {
  try {
    const auth = await getAuthenticatedContext();
    if (auth.error) {
      return auth.error;
    }

    const body = await request.json() as {
      profile?: Partial<CandidateSettingsBundle['profile']>;
      candidateProfile?: Partial<CandidateSettingsBundle['candidateProfile']>;
    };
    const profileInput = body?.profile ?? {};
    const candidateInput = body?.candidateProfile ?? {};

    const { insforge, user } = auth.context;
    const { data: profileRow, error: profileError } = await insforge.database
      .from('profiles')
      .select('*')
      .eq('id', user.id)
      .single();

    if (profileError || !profileRow) {
      return NextResponse.json({ error: profileError?.message ?? 'Profile not found' }, { status: 404 });
    }

    const lookup = await findCandidateProfile(insforge, user.id);
    const existingBundle = buildResponse(profileRow, lookup.record);

    const nextProfile = {
      name: typeof profileInput.name === 'string' ? profileInput.name.trim() : existingBundle.profile.name,
      phone: typeof profileInput.phone === 'string' ? profileInput.phone.trim() : existingBundle.profile.phone,
      location: typeof profileInput.location === 'string' ? profileInput.location.trim() : existingBundle.profile.location,
    };

    const mergedCandidate = applyResumeAutofill(normalizeCandidateProfile({
      ...existingBundle.candidateProfile,
      ...candidateInput,
    }));

    const profileStrength = calculateCandidateProfileStrength(
      {
        name: nextProfile.name,
        phone: nextProfile.phone,
        location: nextProfile.location,
      },
      mergedCandidate,
    );

    const { error: updateProfileError } = await insforge.database
      .from('profiles')
      .update(nextProfile)
      .eq('id', user.id);

    if (updateProfileError) {
      return NextResponse.json({ error: updateProfileError.message }, { status: 400 });
    }

    const candidatePayload: Record<string, unknown> = {
      headline: mergedCandidate.headline,
      skills: mergedCandidate.skills,
      experience_years: mergedCandidate.experience_years,
      education: mergedCandidate.education,
      resume_url: mergedCandidate.resume_url,
      salary_min: mergedCandidate.salary_min,
      salary_max: mergedCandidate.salary_max,
      preferred_locations: mergedCandidate.preferred_locations,
      job_type: mergedCandidate.job_type,
      profile_strength: profileStrength,
    };

    if (!isUuid(user.id)) {
      return NextResponse.json(
        { error: 'Cannot save onboarding data without a valid authenticated user UUID.' },
        { status: 400 },
      );
    }

    let saveCandidateError: { message: string } | null = null;

    if (lookup.record) {
      const { error } = await insforge.database
        .from('candidate_profiles')
        .update(candidatePayload)
        .eq(lookup.key, user.id);
      saveCandidateError = error;
    } else {
      const insertPayload =
        lookup.key === 'user_id'
          ? { user_id: user.id, ...candidatePayload }
          : { id: user.id, ...candidatePayload };

      if (
        ('user_id' in insertPayload && !isUuid(insertPayload.user_id)) ||
        ('id' in insertPayload && !isUuid(insertPayload.id))
      ) {
        return NextResponse.json(
          { error: 'Refusing to insert candidate profile without a valid authenticated UUID.' },
          { status: 400 },
        );
      }

      const { error } = await insforge.database
        .from('candidate_profiles')
        .insert([insertPayload]);
      saveCandidateError = error;
    }

    if (saveCandidateError) {
      return NextResponse.json({ error: saveCandidateError.message }, { status: 400 });
    }

    return NextResponse.json({
      profile: {
        ...existingBundle.profile,
        ...nextProfile,
      },
      candidateProfile: {
        ...mergedCandidate,
        profile_strength: profileStrength,
      },
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Unexpected error';
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import nodemailer from 'nodemailer';

export async function POST(request: NextRequest) {
  try {
    const { email, name, role } = await request.json();

    if (!email || !name) {
      return NextResponse.json({ error: 'Email and name are required' }, { status: 400 });
    }

    const transporter = nodemailer.createTransport({
      service: 'gmail',
      auth: {
        user: process.env.GMAIL_USER,
        pass: process.env.GMAIL_APP_PASSWORD,
      },
    });

    const roleName = role === 'recruiter' ? 'Recruiter' : 'Candidate';

    const mailOptions = {
      from: `"TalentMesh" <${process.env.GMAIL_USER}>`,
      to: email,
      subject: `Welcome to TalentMesh, ${name}!`,
      html: `
        <div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #eee; border-radius: 10px;">
          <h2 style="color: #2563eb;">Welcome to TalentMesh!</h2>
          <p>Hello <strong>${name}</strong>,</p>
          <p>We are thrilled to have you join us as a <strong>${roleName}</strong>. TalentMesh is designed to bridge the gap between talented individuals and great companies through AI-powered recruiting.</p>
          <p>Here are your first steps:</p>
          <ul>
            <li>Complete your profile</li>
            <li>Explore our dashboard</li>
            <li>Start connecting with opportunities</li>
          </ul>
          <p>If you have any questions, feel any free to reply to this email.</p>
          <p>Best regards,<br/>The TalentMesh Team</p>
          <hr style="border: 0; border-top: 1px solid #eee; margin: 20px 0;" />
          <p style="font-size: 0.8em; color: #777;">&copy; ${new Date().getFullYear()} TalentMesh. All rights reserved.</p>
        </div>
      `,
    };

    await transporter.sendMail(mailOptions);
    return NextResponse.json({ success: true, message: 'Welcome email sent successfully' });
  } catch (err: any) {
    console.error('Error sending welcome email:', err);
    return NextResponse.json({ error: err.message || 'Failed to send welcome email' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { insforgeAdmin } from '@/lib/insforge-admin';
import { createClient } from '@insforge/sdk';
import * as OTPAuth from 'otpauth';
import { cookies } from 'next/headers';

/**
 * POST /api/mfa/enroll
 * Generates a new TOTP secret and stores it as an unverified factor.
 * Returns the TOTP URI (for QR code rendering) and the raw secret.
 */
export async function POST(request: Request) {
  try {
    if (!insforgeAdmin) {
      return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
    }

    // Get current user from the access token cookie
    const cookieStore = await cookies();
    const accessToken = cookieStore.get('tm_access_token')?.value;

    if (!accessToken) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
    }

    // Create a client with the user's token to get their identity
    const userClient = createClient({
      baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
      anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
    });

    // Verify the session
    const { data: sessionData, error: sessionError } = await userClient.auth.getCurrentSession();
    if (sessionError || !sessionData?.session?.user) {
      return NextResponse.json({ error: 'Invalid session' }, { status: 401 });
    }

    const user = sessionData.session.user;

    // Delete any existing unverified factors for this user
    await insforgeAdmin.database
      .from('mfa_factors')
      .delete()
      .eq('user_id', user.id)
      .eq('status', 'unverified');

    // Generate TOTP secret
    const totp = new OTPAuth.TOTP({
      issuer: 'TalentMesh',
      label: user.email ?? 'Admin',
      algorithm: 'SHA1',
      digits: 6,
      period: 30,
      secret: new OTPAuth.Secret({ size: 20 }),
    });

    const secret = totp.secret.base32;
    const uri = totp.toString();

    // Store the factor
    const { data: factor, error: insertError } = await insforgeAdmin.database
      .from('mfa_factors')
      .insert({
        user_id: user.id,
        secret,
        friendly_name: 'TalentMesh Admin',
        status: 'unverified',
      })
      .select('id')
      .single();

    if (insertError) {
      console.error('MFA enroll insert error:', insertError);
      return NextResponse.json({ error: 'Failed to save MFA factor' }, { status: 500 });
    }

    return NextResponse.json({
      id: factor.id,
      secret,
      uri,
    });
  } catch (err: any) {
    console.error('MFA enroll error:', err);
    return NextResponse.json({ error: err.message || 'Enrollment failed' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { insforgeAdmin } from '@/lib/insforge-admin';
import { createClient } from '@insforge/sdk';
import { cookies } from 'next/headers';

/**
 * GET /api/mfa/status
 * Returns the MFA status for the current user:
 *   - mfaEnabled: whether the user has a verified TOTP factor
 *   - mfaVerifiedThisSession: whether the mfa_verified cookie is set
 */
export async function GET() {
  try {
    if (!insforgeAdmin) {
      return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
    }

    const cookieStore = await cookies();
    const accessToken = cookieStore.get('tm_access_token')?.value;

    if (!accessToken) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
    }

    const userClient = createClient({
      baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
      anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
    });

    const { data: sessionData, error: sessionError } = await userClient.auth.getCurrentSession();
    if (sessionError || !sessionData?.session?.user) {
      return NextResponse.json({ error: 'Invalid session' }, { status: 401 });
    }

    const user = sessionData.session.user;

    const { data: profile } = await insforgeAdmin.database
      .from('profiles')
      .select('mfa_enabled')
      .eq('id', user.id)
      .single();

    const mfaVerifiedCookie = cookieStore.get('mfa_verified')?.value === 'true';

    return NextResponse.json({
      mfaEnabled: profile?.mfa_enabled ?? false,
      mfaVerifiedThisSession: mfaVerifiedCookie,
    });
  } catch (err: any) {
    console.error('MFA status error:', err);
    return NextResponse.json({ error: err.message || 'Failed to get MFA status' }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { insforgeAdmin } from '@/lib/insforge-admin';
import { createClient } from '@insforge/sdk';
import * as OTPAuth from 'otpauth';
import { cookies } from 'next/headers';

/**
 * POST /api/mfa/verify
 * Verifies a TOTP code against the user's stored MFA factor.
 * On success: marks factor as verified, sets mfa_enabled on profile,
 * and sets an mfa_verified cookie for the current session.
 *
 * Body: { code: string, factorId?: string }
 *   - factorId is optional; if omitted, uses the user's first verified factor
 *     (for login-time verification) or first unverified factor (for enrollment).
 */
export async function POST(request: Request) {
  try {
    if (!insforgeAdmin) {
      return NextResponse.json({ error: 'Server configuration error' }, { status: 500 });
    }

    const body = await request.json();
    const { code, factorId } = body;

    if (!code || typeof code !== 'string') {
      return NextResponse.json({ error: 'Code is required' }, { status: 400 });
    }

    // Get current user
    const cookieStore = await cookies();
    const accessToken = cookieStore.get('tm_access_token')?.value;

    if (!accessToken) {
      return NextResponse.json({ error: 'Not authenticated' }, { status: 401 });
    }

    const userClient = createClient({
      baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
      anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
    });

    const { data: sessionData, error: sessionError } = await userClient.auth.getCurrentSession();
    if (sessionError || !sessionData?.session?.user) {
      return NextResponse.json({ error: 'Invalid session' }, { status: 401 });
    }

    const user = sessionData.session.user;

    // Check lockout
    const { data: profile } = await insforgeAdmin.database
      .from('profiles')
      .select('mfa_locked_until')
      .eq('id', user.id)
      .single();

    if (profile?.mfa_locked_until) {
      const lockedUntil = new Date(profile.mfa_locked_until);
      if (lockedUntil > new Date()) {
        const minutesLeft = Math.ceil((lockedUntil.getTime() - Date.now()) / 60000);
        return NextResponse.json(
          { error: `Account locked. Try again in ${minutesLeft} minute(s).` },
          { status: 429 }
        );
      }
    }

    // Find the factor
    let query = insforgeAdmin.database
      .from('mfa_factors')
      .select('*')
      .eq('user_id', user.id);

    if (factorId) {
      query = query.eq('id', factorId);
    }

    const { data: factors, error: factorError } = await query;

    if (factorError || !factors || factors.length === 0) {
      return NextResponse.json({ error: 'No MFA factor found' }, { status: 404 });
    }

    // Prefer verified factor (login flow), then unverified (enrollment flow)
    const factor = factors.find((f: any) => f.status === 'verified')
      || factors.find((f: any) => f.status === 'unverified')
      || factors[0];

    // Validate TOTP
    const totp = new OTPAuth.TOTP({
      issuer: 'TalentMesh',
      label: user.email ?? 'Admin',
      algorithm: 'SHA1',
      digits: 6,
      period: 30,
      secret: OTPAuth.Secret.fromBase32(factor.secret),
    });

    const delta = totp.validate({ token: code, window: 1 });

    if (delta === null) {
      return NextResponse.json({ error: 'Invalid code', valid: false }, { status: 400 });
    }

    // Code is valid — mark factor as verified
    if (factor.status === 'unverified') {
      await insforgeAdmin.database
        .from('mfa_factors')
        .update({ status: 'verified' })
        .eq('id', factor.id);
    }

    // Set mfa_enabled on profile
    await insforgeAdmin.database
      .from('profiles')
      .update({ mfa_enabled: true, mfa_locked_until: null })
      .eq('id', user.id);

    // Set mfa_verified cookie (1 hour, matches session cookie lifetime)
    const response = NextResponse.json({ valid: true });
    response.cookies.set('mfa_verified', 'true', {
      path: '/',
      maxAge: 3600,
      sameSite: 'lax',
      httpOnly: true,
    });

    return response;
  } catch (err: any) {
    console.error('MFA verify error:', err);
    return NextResponse.json({ error: err.message || 'Verification failed' }, { status: 500 });
  }
}

"use client";
import { useEffect, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { insforge } from '@/lib/insforge';

function AuthCallbackContent() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const defaultRole = searchParams.get('role'); // Get role from query param (?role=recruiter)

  useEffect(() => {
    const handleCallback = async () => {
      // 1. Trigger a session refresh to pick up the OAuth tokens
      const { data: { session } } = await insforge.auth.getCurrentSession();

      if (!session) {
        // Fallback if session is missing after a short delay
        setTimeout(async () => {
          const { data: { session: retrySession } } = await insforge.auth.getCurrentSession();
          if (!retrySession) {
            router.push('/login');
          } else {
            processSession(retrySession);
          }
        }, 1000);
        return;
      }

      processSession(session);
    };

    const processSession = async (session: { user: any; accessToken: string }) => {
      const user = session.user;

      // Extract metadata provided by the provider (Google/LinkedIn)
      // InsForge maps provider-specific data to user.profile and user.metadata
      const profileInfo = user.profile || {};
      const metadataInfo = user.metadata || {};
      const identityData = user.identities?.[0]?.identity_data || {};

      const realName =
        profileInfo.name ||
        metadataInfo.full_name ||
        metadataInfo.name ||
        identityData.full_name ||
        identityData.name ||
        split_part(user.email, '@', 1);

      const avatarUrl =
        profileInfo.avatar_url ||
        metadataInfo.avatar_url ||
        metadataInfo.picture ||
        identityData.avatar_url ||
        identityData.picture ||
        null;

      // Update the profile row with the latest data from the provider
      // We also set the role from the query param if it's provided and not yet set in DB
      const { data: existingProfile } = await insforge.database
        .from('profiles')
        .select('role, role_id')
        .eq('id', user.id)
        .single();

      const finalRole = existingProfile?.role || defaultRole || 'candidate';

      // Generate role-specific ID if not exists
      let roleId = existingProfile?.role_id;
      if (!roleId) {
        const prefix = finalRole === 'super_admin' ? 'admin' : finalRole === 'recruiter' ? 'recr' : 'cand';
        roleId = `${prefix}_${Math.random().toString(36).substring(2, 10)}`;
      }

      const { error: upsertError } = await insforge.database
        .from('profiles')
        .upsert([{
          id: user.id,
          email: user.email,
          name: realName,
          avatar_url: avatarUrl,
          role: finalRole,
          // role_id: roleId, // Omit to avoid "column not found" error
          updated_at: new Date().toISOString(),
        }]);

      if (upsertError) {
        // Handle orphaned profile unique constraint failures (when user deleted in Auth but not Public.Profiles)
        if (upsertError.message.includes('duplicate key') || upsertError.message.includes('unique constraint')) {
          console.log('Resolving orphaned profile conflict for:', user.email);
          await insforge.database.from('profiles').delete().eq('email', user.email);

          await insforge.database
            .from('profiles')
            .upsert([{
              id: user.id,
              email: user.email,
              name: realName,
              avatar_url: avatarUrl,
              role: finalRole,
              // role_id: roleId,
              updated_at: new Date().toISOString(),
            }]);
        } else {
          console.error('Profile Creation Error:', upsertError.message);
        }
      }

      // Set cookies immediately for middleware
      // First clear any existing session cookies to avoid duplicates
      document.cookie = 'tm_access_token=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT';
      document.cookie = 'tm_role=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT';

      document.cookie = `tm_access_token=${session.accessToken}; path=/; max-age=3600; SameSite=Lax`;
      document.cookie = `tm_role=${finalRole}; path=/; max-age=3600; SameSite=Lax`;
      // Redirect based on the final role
      if (finalRole === 'admin' || finalRole === 'super_admin') {
        router.replace('/dashboard/admin');
      } else if (finalRole === 'recruiter') {
        router.push('/onboarding/recruiter/setup');
      } else {
        router.push('/onboarding/candidate');
      }
    };

    handleCallback();
  }, [router, defaultRole]);

  return (
    <div style={{
      minHeight: '100vh',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      background: '#0c0c14',
      color: '#e2e2f0',
      fontFamily: 'sans-serif',
      gap: '12px'
    }}>
      <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#6366f1" strokeWidth="2.5" style={{ animation: 'spin 2s linear infinite' }}>
        <path d="M12 2v4m0 12v4M4.93 4.93l2.83 2.83m8.48 8.48l2.83 2.83M2 12h4m12 0h4M4.93 19.07l2.83-2.83m8.48-8.48l2.83-2.83" />
      </svg>
      <style>{`
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
      Signing you in...
    </div>
  );
}

export default function AuthCallback() {
  return (
    <Suspense fallback={<div>Loading...</div>}>
      <AuthCallbackContent />
    </Suspense>
  );
}

function split_part(str: string, delim: string, idx: number): string {
  return (str ?? '').split(delim)[idx - 1] ?? '';
}

