"use client";

import { useState, useEffect, useRef, FormEvent } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { logAction } from '@/lib/admin/audit';
import { insforge } from '@/lib/insforge';
import styles from './mfa-verify.module.css';

export default function MFAVerifyPage() {
    const router = useRouter();
    const [code, setCode] = useState('');
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [isBackup, setIsBackup] = useState(false);
    const [attempts, setAttempts] = useState(0);
    const inputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        if (inputRef.current) inputRef.current.focus();
    }, [isBackup]);

    const handleVerify = async (val: string) => {
        if (val.length !== 6 && !isBackup) return;

        setIsLoading(true);
        setError('');

        try {
            // Call our custom MFA verify API route
            const res = await fetch('/api/mfa/verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ code: val }),
            });
            const data = await res.json();

            // Get current user for logging
            const { data: sessionData } = await insforge.auth.getCurrentSession();
            const user = sessionData?.session?.user;

            if (!res.ok) {
                if (user) {
                    await logAction({
                        adminId: user.id,
                        action: 'security_mfa_failed',
                        status: 'failure'
                    });
                }
                const newAttempts = attempts + 1;
                setAttempts(newAttempts);
                if (newAttempts >= 5) {
                    setError('Too many failed attempts. Account locked for 15 minutes.');
                } else {
                    setError(`Incorrect code. ${5 - newAttempts} attempts remaining.`);
                }
                setCode('');
                return;
            }

            // Success
            if (user) {
                await logAction({
                    adminId: user.id,
                    action: 'security_mfa_success',
                    status: 'success'
                });
            }

            // Determine destination based on profile role
            const { data: profile } = await insforge.database
                .from('profiles')
                .select('role')
                .eq('id', user?.id)
                .single();

            const role = profile?.role;
            const dest = role === 'super_admin' ? '/dashboard/admin' 
                       : role === 'recruiter' ? '/dashboard/recruiter' 
                       : '/dashboard/candidate';
            router.push(dest);
        } catch (err: any) {
            setError(err.message || 'Verification failed');
        } finally {
            setIsLoading(false);
        }
    };

    const handleBackupVerify = async (e: FormEvent) => {
        e.preventDefault();
        setError('Manual backup code verification not fully implemented in this demo. Please use TOTP.');
    };

    const onInputChange = (val: string) => {
        const cleanVal = val.replace(/\D/g, '').substring(0, 6);
        setCode(cleanVal);
        if (cleanVal.length === 6) {
            handleVerify(cleanVal);
        }
    };

    return (
        <div className={styles.page}>
            <div className={styles.card}>
                <div className={styles.logoWrap}>
                    <Image
                        src="/TalentMesh_page-0002-removebg-preview.png"
                        alt="TalentMesh"
                        width={180}
                        height={50}
                        unoptimized
                        priority
                    />
                </div>

                <div className={styles.header}>
                    <h1 className={styles.title}>Two-Factor Authentication</h1>
                    <p className={styles.subtitle}>
                        {isBackup 
                            ? 'Enter one of your 8-digit backup codes to sign in.' 
                            : 'Enter the 6-digit code from your authenticator app.'}
                    </p>
                </div>

                {error && <div className={styles.errorMessage}>{error}</div>}

                {!isBackup ? (
                    <div className={styles.inputContainer}>
                        <input
                            ref={inputRef}
                            type="text"
                            maxLength={6}
                            value={code}
                            onChange={(e) => onInputChange(e.target.value)}
                            className={styles.mfaInput}
                            disabled={isLoading || attempts >= 5}
                            placeholder="000000"
                            autoFocus
                        />
                        {isLoading && <div className={styles.loaderLine} />}
                    </div>
                ) : (
                    <form onSubmit={handleBackupVerify} className={styles.form}>
                        <input
                            ref={inputRef}
                            type="text"
                            className={styles.backupInput}
                            placeholder="Enter backup code"
                            required
                        />
                        <button type="submit" className={styles.submitBtn} disabled={isLoading}>
                            Verify Backup Code
                        </button>
                    </form>
                )}

                <div className={styles.footer}>
                    <button 
                        onClick={() => setIsBackup(!isBackup)} 
                        className={styles.ghostBtn}
                    >
                        {isBackup ? 'Use Authenticator App' : 'Use a backup code instead'}
                    </button>

                    <Link href="/login" className={styles.link}>
                        Back to Login
                    </Link>
                </div>
            </div>
        </div>
    );
}

"use client";
import React, { useState } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter, useSearchParams } from 'next/navigation';
import { insforge } from '@/lib/insforge';
import { resetPasswordSchema } from '@/lib/validation/auth';
import styles from './reset.module.css';

export default function ResetPasswordPage() {
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const [success, setSuccess] = useState(false);
    const router = useRouter();
    const searchParams = useSearchParams();
    const token = searchParams.get('token');

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        // 1. Validate with resetPasswordSchema
        const validation = resetPasswordSchema.safeParse({ password, confirmPassword });
        if (!validation.success) {
            setError(validation.error.issues[0].message);
            setIsLoading(false);
            return;
        }

        try {
            // 2. Update password
            if (!token) {
                setError('Invalid or expired reset token. Please request a new one.');
                setIsLoading(false);
                return;
            }

            const { error: resetError } = await insforge.auth.resetPassword({
                newPassword: password,
                otp: token,
            });

            if (resetError) {
                setError(resetError.message);
                setIsLoading(false);
                return;
            }

            setSuccess(true);
        } catch (err: any) {
            setError(err.message || 'An unexpected error occurred. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.page}>
            {/* Background decorations */}
            <div className={styles.bgGlow1} />
            <div className={styles.bgGlow2} />
            <div className={styles.gridOverlay} />

            <div className={styles.card}>
                {/* Logo */}
                <Link href="/" className={styles.logoWrap}>
                    <Image
                        src="/TalentMesh_page-0002-removebg-preview.png"
                        alt="TalentMesh"
                        width={150}
                        height={42}
                        unoptimized
                        className={styles.logoImg}
                    />
                </Link>

                {!success ? (
                    <>
                        <div className={styles.header}>
                            <div className={styles.formIconCircle}>
                                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--primary-blue)" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
                                    <path d="M21 2l-2 2m-7.61 7.61a5.5 5.5 0 1 1-7.778 7.778 5.5 5.5 0 0 1 7.777-7.777zm0 0L15.5 7.5m0 0l3 3m-3-3l2.5-2.5" />
                                </svg>
                            </div>
                            <h1 className={styles.title}>New password</h1>
                            <p className={styles.subtitle}>
                                Set a strong password for your account
                            </p>
                        </div>

                        <form className={styles.form} onSubmit={handleSubmit}>
                            {error && <div style={{ color: '#ef4444', fontSize: '0.82rem', textAlign: 'center', marginBottom: '0.5rem', padding: '0.6rem', background: '#fef2f2', borderRadius: '8px', border: '1px solid #fee2e2' }}>{error}</div>}

                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="password">New Password</label>
                                <div className={styles.inputWrap}>
                                    <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <rect x="3" y="11" width="18" height="11" rx="2" ry="2" />
                                        <path d="M7 11V7a5 5 0 0 1 10 0v4" />
                                    </svg>
                                    <input
                                        id="password"
                                        type="password"
                                        className={styles.input}
                                        placeholder="••••••••"
                                        value={password}
                                        onChange={e => setPassword(e.target.value)}
                                        required
                                    />
                                </div>
                            </div>

                            <div className={styles.fieldGroup}>
                                <label className={styles.label} htmlFor="confirmPassword">Confirm Password</label>
                                <div className={styles.inputWrap}>
                                    <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                        <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" />
                                        <polyline points="22 4 12 14.01 9 11.01" />
                                    </svg>
                                    <input
                                        id="confirmPassword"
                                        type="password"
                                        className={styles.input}
                                        placeholder="••••••••"
                                        value={confirmPassword}
                                        onChange={e => setConfirmPassword(e.target.value)}
                                        required
                                    />
                                </div>
                            </div>

                            <button
                                type="submit"
                                className={styles.submitBtn}
                                disabled={isLoading}
                            >
                                {isLoading ? (
                                    <span className={styles.spinnerWrap}>
                                        <span className={styles.spinner} />
                                        Updating...
                                    </span>
                                ) : 'Reset Password'}
                            </button>
                        </form>
                    </>
                ) : (
                    <div className={styles.successState}>
                        <div className={styles.successIcon}>
                            <svg width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="#10b981" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <polyline points="20 6 9 17 4 12" />
                            </svg>
                        </div>
                        <h1 className={styles.title}>Password updated</h1>
                        <p className={styles.subtitle}>
                            Your password has been reset successfully. <br />
                            You can now sign in with your new password.
                        </p>
                    </div>
                )}

                <p className={styles.footer}>
                    {success ? (
                        <Link href="/login" className={styles.loginLink}>Back to sign in</Link>
                    ) : (
                        <>
                            Wait, I remember it!{' '}
                            <Link href="/login" className={styles.loginLink}>Sign in</Link>
                        </>
                    )}
                </p>
            </div>

            {/* Bottom terms */}
            <p className={styles.terms}>
                By using our service, you agree to our{' '}
                <Link href="/terms" className={styles.termsLink}>Terms</Link>
                {' '}&{' '}
                <Link href="/privacy" className={styles.termsLink}>Privacy Policy</Link>
            </p>
        </div>
    );
}

/* Reset Password — white bg + light centered card (Login match) */

.page {
    width: 100vw;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8fafc;
    position: relative;
    overflow: hidden;
    font-family: var(--font-inter), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* Background decorations */
.bgGlow1 {
    position: absolute;
    top: -15%;
    right: -10%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.08) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 20s ease-in-out infinite alternate;
}

.bgGlow2 {
    position: absolute;
    bottom: -15%;
    left: -10%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.06) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 16s ease-in-out infinite alternate-reverse;
}

@keyframes glowPulse {
    0% {
        transform: scale(1);
        opacity: 0.7;
    }

    100% {
        transform: scale(1.15);
        opacity: 1;
    }
}

.gridOverlay {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 0, 0, 0.02) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
}

/* Card */
.card {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 420px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 20px;
    padding: 2.25rem 2.5rem;
    box-shadow:
        0 4px 6px -1px rgba(0, 0, 0, 0.03),
        0 10px 30px -5px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
    animation: cardEnter 0.5s ease-out;
}

@keyframes cardEnter {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

/* Logo */
.logoWrap {
    display: flex;
    justify-content: center;
    text-decoration: none;
}

.logoImg {
    filter: none;
    opacity: 1;
}

/* Header */
.header {
    text-align: center;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.iconCircle {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: #f0fdf4;
    border: 1px solid #dcfce7;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 0.25rem;
}

/* Overriding icon circle for reset (if it had one, but let's keep it green-ish for success or blue for form) */
.formIconCircle {
    width: 48px;
    height: 48px;
    border-radius: 12px;
    background: #eff6ff;
    border: 1px solid #dbeafe;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 0.25rem;
}

.title {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.subtitle {
    font-size: 0.82rem;
    color: #94a3b8;
    font-weight: 400;
}

/* Form */
.form {
    display: flex;
    flex-direction: column;
    gap: 1rem;
}

.fieldGroup {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.label {
    font-size: 0.78rem;
    font-weight: 600;
    color: #374151;
}

.inputWrap {
    position: relative;
    display: flex;
    align-items: center;
}

.inputIcon {
    position: absolute;
    left: 0.8rem;
    color: #c0c7d0;
    pointer-events: none;
    z-index: 1;
    transition: color 0.2s ease;
}

.inputWrap:focus-within .inputIcon {
    color: var(--primary-blue);
}

.input {
    width: 100%;
    padding: 0.68rem 0.9rem 0.68rem 2.5rem;
    background: #f9fafb;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #0f172a;
    font-size: 0.85rem;
    font-family: inherit;
    outline: none;
    transition: all 0.2s ease;
}

.input::placeholder {
    color: #b0b8c4;
}

.input:focus {
    background: #ffffff;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
}

.input:hover:not(:focus) {
    border-color: #d1d5db;
}

/* Submit button */
.submitBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.5rem;
    width: 100%;
    padding: 0.72rem 1.5rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 9px;
    font-size: 0.88rem;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.submitBtn:hover:not(:disabled) {
    background: #0056d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.submitBtn:active:not(:disabled) {
    transform: translateY(0);
}

.submitBtn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.spinnerWrap {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.spinner {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(255, 255, 255, 0.3);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

/* Success state */
.successState {
    display: flex;
    flex-direction: column;
    align-items: center;
    text-align: center;
    gap: 0.65rem;
}

.successIcon {
    width: 52px;
    height: 52px;
    border-radius: 14px;
    background: #ecfdf5;
    border: 1px solid #d1fae5;
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 0.25rem;
}

/* Footer / Back Link */
.footer {
    text-align: center;
    font-size: 0.82rem;
    color: #94a3b8;
    margin-top: 0.5rem;
}

.loginLink {
    color: var(--primary-blue);
    font-weight: 700;
    text-decoration: none;
    transition: color 0.2s;
}

.loginLink:hover {
    color: #0056d6;
}

/* Terms — pinned to bottom */
.terms {
    position: absolute;
    bottom: 1.5rem;
    left: 50%;
    transform: translateX(-50%);
    font-size: 0.68rem;
    color: #b0b8c4;
    text-align: center;
    white-space: nowrap;
    z-index: 1;
}

.termsLink {
    color: #94a3b8;
    text-decoration: underline;
    text-underline-offset: 2px;
    transition: color 0.2s;
}

.termsLink:hover {
    color: var(--primary-blue);
}

@media (max-width: 480px) {
    .card {
        max-width: 100%;
        margin: 0 1rem;
        padding: 1.75rem 1.5rem;
        border-radius: 16px;
    }

    .title {
        font-size: 1.35rem;
    }
}

"use client";

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { useRouter } from 'next/navigation';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';
import styles from './set-password.module.css';
import { z } from 'zod';

const passwordSchema = z.object({
    name: z.string().min(2, 'Name must be at least 2 characters'),
    password: z.string()
        .min(8, 'Password must be at least 8 characters')
        .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
        .regex(/[0-9]/, 'Password must contain at least one number'),
    confirmPassword: z.string()
}).refine((data) => data.password === data.confirmPassword, {
    message: "Passwords don't match",
    path: ["confirmPassword"],
});

export default function SetPasswordPage() {
    const router = useRouter();
    const { user, refreshUser } = useAuth();

    const [name, setName] = useState('');
    const [password, setPassword] = useState('');
    const [confirmPassword, setConfirmPassword] = useState('');
    const [isLoading, setIsLoading] = useState(true);
    const [isSubmitting, setIsSubmitting] = useState(false);
    const [error, setError] = useState('');
    const [sessionStatus, setSessionStatus] = useState<'checking' | 'active' | 'expired'>('checking');

    // 1. Initial Session Check (Invite creates a session)
    useEffect(() => {
        const checkSession = async () => {
            const { data: { session } } = await insforge.auth.getCurrentSession();

            if (!session?.user) {
                setSessionStatus('expired');
                setIsLoading(false);
                return;
            }

            setSessionStatus('active');
            // Try to get name from metadata
            const metadata = (session.user.metadata || {}) as any;
            setName(metadata.name || session.user.email?.split('@')[0] || '');
            setIsLoading(false);
        };
        checkSession();
    }, []);

    // 2. Password Strength Logic
    const getPasswordStrength = (pwd: string) => {
        if (pwd.length === 0) return { label: '', color: '#ddd', width: '0%' };
        if (pwd.length < 8) return { label: 'Too short', color: '#ef4444', width: '33%' };

        const hasUpper = /[A-Z]/.test(pwd);
        const hasNumber = /[0-9]/.test(pwd);

        if (hasUpper && hasNumber && pwd.length >= 10) return { label: 'Strong', color: '#22c55e', width: '100%' };
        if (hasUpper || hasNumber) return { label: 'Medium', color: '#f59e0b', width: '66%' };

        return { label: 'Weak', color: '#f97316', width: '40%' };
    };

    const strength = getPasswordStrength(password);

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setError('');

        const result = passwordSchema.safeParse({ name, password, confirmPassword });
        if (!result.success) {
            setError(result.error.issues[0].message);
            return;
        }

        setIsSubmitting(true);

        try {
            const sessionRes = await insforge.auth.getCurrentSession();
            const session = sessionRes.data?.session;

            if (!session) {
                throw new Error("Your session has expired or is invalid. Please try clicking the invite link again.");
            }

            // A. Update Auth User via REST API (since SDK doesn't expose updateUser)
            const response = await fetch(`${process.env.NEXT_PUBLIC_INSFORGE_URL}/auth/v1/user`, {
                method: 'PUT',
                headers: {
                    'Authorization': `Bearer ${session.accessToken}`,
                    'apikey': process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({
                    password,
                    data: { name, password_set_at: new Date().toISOString() }
                })
            });

            if (!response.ok) {
                const errorData = await response.json().catch(() => ({}));
                throw new Error(errorData.msg || errorData.error_description || errorData.message || 'Failed to update password');
            }

            // B. Update Database Profile
            const { error: profileError } = await insforge.database
                .from('profiles')
                .update({
                    name,
                    password_set_at: new Date().toISOString()
                })
                .eq('id', user?.id || session.user.id);

            if (profileError) throw profileError;

            // C. Success
            await refreshUser();
            router.push('/auth/setup-mfa');

        } catch (err: any) {
            setError(err.message || 'Failed to update password');
            setIsSubmitting(false);
        }
    };

    if (isLoading) {
        return (
            <div className={styles.loadingContainer}>
                <div className={styles.spinner} />
                <p>Verifying invitation...</p>
            </div>
        );
    }

    if (sessionStatus === 'expired') {
        return (
            <div className={styles.page}>
                <div className={styles.card}>
                    <div className={styles.header}>
                        <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>📧</div>
                        <h1 className={styles.title}>Invite Expired</h1>
                        <p className={styles.subtitle}>
                            This invitation link has expired or is invalid.
                            Please contact your administrator for a new invite.
                        </p>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className={styles.page}>
            <div className={styles.card}>
                <Link href="/" className={styles.logoWrap}>
                    <Image
                        src="/TalentMesh_page-0002-removebg-preview.png"
                        alt="TalentMesh"
                        width={180}
                        height={50}
                        unoptimized
                        priority
                    />
                </Link>

                <div className={styles.header}>
                    <h1 className={styles.title}>Welcome to TalentMesh Admin</h1>
                    <p className={styles.subtitle}>
                        You&apos;ve been invited as a Super Admin. Set your password to get started.
                    </p>
                </div>

                {error && <div className={styles.errorMessage}>{error}</div>}

                <form className={styles.form} onSubmit={handleSubmit}>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Full Name</label>
                        <input
                            type="text"
                            className={styles.input}
                            value={name}
                            onChange={e => setName(e.target.value)}
                            required
                        />
                    </div>

                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>New Password</label>
                        <input
                            type="password"
                            className={styles.input}
                            value={password}
                            onChange={e => setPassword(e.target.value)}
                            required
                            placeholder="Min 8 chars, 1 uppercase, 1 number"
                        />
                        <div className={styles.strengthBarWrap}>
                            <div
                                className={styles.strengthBar}
                                style={{ width: strength.width, backgroundColor: strength.color }}
                            />
                        </div>
                        {password && <span className={styles.strengthLabel}>{strength.label}</span>}
                    </div>

                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Confirm Password</label>
                        <input
                            type="password"
                            className={styles.input}
                            value={confirmPassword}
                            onChange={e => setConfirmPassword(e.target.value)}
                            required
                        />
                    </div>

                    <button
                        type="submit"
                        className={styles.submitBtn}
                        disabled={isSubmitting}
                    >
                        {isSubmitting ? 'Setting up account...' : 'Set Password'}
                    </button>
                </form>
            </div>
        </div>
    );
}

