.cardDate {
    font-size: 0.78rem;
    color: var(--medium-grey);
    margin-bottom: 0.75rem;
}

.cardTitle {
    font-size: 1.1rem;
    font-weight: 800;
    color: var(--deep-navy);
    line-height: 1.35;
    margin-bottom: 0.75rem;
}

.cardDesc {
    font-size: 0.875rem;
    color: var(--medium-grey);
    line-height: 1.65;
    margin-bottom: 1.5rem;
}

.readLink {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--primary-blue);
    font-weight: 800;
    font-size: 0.85rem;
    text-decoration: none;
    transition: gap 0.2s;
}

.readLink:hover {
    gap: 10px;
}

/* Newsletter */
.newsletterSection {
    padding: 4rem 0 8rem;
}

.newsletterCard {
    background: var(--gradient-premium);
    border-radius: 40px;
    padding: 6rem 4rem;
    text-align: center;
    color: #fff;
}

.newsletterCard h2 {
    font-size: clamp(2rem, 3.5vw, 3rem);
    font-weight: 900;
    margin-bottom: 1rem;
}

.newsletterCard p {
    opacity: 0.75;
    font-size: 1.1rem;
    max-width: 500px;
    margin: 0 auto 3rem;
    line-height: 1.7;
}

.emailForm {
    display: flex;
    gap: 0.75rem;
    max-width: 500px;
    margin: 0 auto;
}

.emailInput {
    flex: 1;
    padding: 1rem 1.5rem;
    border-radius: 14px;
    border: none;
    background: rgba(255, 255, 255, 0.15);
    color: #fff;
    font-size: 0.95rem;
    outline: none;
    backdrop-filter: blur(10px);
}

.emailInput::placeholder {
    color: rgba(255, 255, 255, 0.5);
}

.subscribeBtn {
    background: #fff;
    color: var(--primary-blue);
    border: none;
    padding: 1rem 2rem;
    border-radius: 14px;
    font-weight: 800;
    font-size: 0.95rem;
    cursor: pointer;
    white-space: nowrap;
    transition: transform 0.2s;
}

.subscribeBtn:hover {
    transform: translateY(-2px);
}

/* Responsive */
@media (max-width: 1024px) {
    .articlesGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 768px) {
    .hero {
        padding: 7rem 0 5rem;
    }

    .featuredCard {
        grid-template-columns: 1fr;
    }

    .featuredBanner {
        min-height: 200px;
    }

    .articlesGrid {
        grid-template-columns: 1fr;
    }

    .newsletterCard {
        padding: 4rem 2rem;
        border-radius: 24px;
    }

    .emailForm {
        flex-direction: column;
    }
}

"use client";
// UNIQUE_TAG: REAL_BLOG_PAGE_FIX_V1
import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import Link from 'next/link';
import styles from './blog.module.css';
import { insforge } from '@/lib/insforge';
import AnimateOnScroll from '@/components/AnimateOnScroll';

const IconSparkle = () => (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" stroke="none">
        <path d="m12 3 1.912 5.885L20 10.8l-5.088 1.912L13 18.6l-1.912-5.888L6 10.8l5.088-1.915L12 3Z" />
    </svg>
);
const IconArrowRight = () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M5 12h14m-7-7 7 7-7 7" />
    </svg>
);

const CATEGORIES = ["All", "Technology", "Culture", "Career Advice", "Engineering", "Product"];

export default function BlogPage() {
    const [posts, setPosts] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeCategory, setActiveCategory] = useState("All");
    const [search, setSearch] = useState("");

    useEffect(() => {
        async function fetchPosts() {
            try {
                const { data } = await insforge.database
                    .from('blog')
                    .select('*')
                    .eq('status', 'published')
                    .order('created_at', { ascending: false });
                setPosts(data || []);
            } catch (err) {
                console.error('Fetch posts error:', err);
            } finally {
                setLoading(false);
            }
        }
        fetchPosts();
    }, []);

    const filtered = posts.filter(p => {
        const matchesCat = activeCategory === "All" || p.category === activeCategory;
        const matchesSearch = p.title.toLowerCase().includes(search.toLowerCase()) ||
            p.excerpt?.toLowerCase().includes(search.toLowerCase());
        return matchesCat && matchesSearch;
    });

    const featuredPost = filtered[0];
    const displayPosts = filtered.slice(1);

    if (loading) return (
        <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#fff' }}>
            <div style={{ width: 40, height: 40, border: '4px solid #f3f3f3', borderTopColor: '#007BFF', borderRadius: '50%', animation: 'spin 1s linear infinite' }} />
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
    );

    return (
        <main style={{ background: '#fff' }}>
            {/* 1. Hero */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <div className={styles.heroContent}>
                        <div className={styles.badge}>
                            <IconSparkle /> Updated Daily • 12.4k Readers
                        </div>
                        <h1 className={styles.title}>
                            Insights &{' '}
                            <span className={styles.highlight}>perspectives.</span>
                        </h1>
                        <p className={styles.description}>
                            The latest thinking on AI, hiring, and the future of work — from the TalentMesh team and industry leaders.
                        </p>
                        <div className={styles.searchBar}>
                            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="rgba(255,255,255,0.5)" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                <circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" />
                            </svg>
                            <input
                                type="text"
                                placeholder="Search articles..."
                                value={search}
                                onChange={e => setSearch(e.target.value)}
                            />
                            <button className={styles.searchBtn}>Search</button>
                        </div>
                    </div>
                </div>
            </section>

            {/* 2. Featured Post */}
            {featuredPost && (
                <AnimateOnScroll animation="fadeUp">
                    <section className={styles.featuredSection}>
                        <div className="premium-container">
                            <div className={styles.featuredCard}>
                                <div className={styles.featuredBanner}>
                                    <Image
                                        src={featuredPost.cover_image || "/images/tech-office.jpg"}
                                        alt={featuredPost.title}
                                        fill
                                        className={styles.featuredImg}
                                        style={{ objectFit: 'cover' }}
                                    />
                                </div>
                                <div className={styles.featuredBody}>
                                    <span className={styles.featuredCategory}>⭐ Featured • {featuredPost.category}</span>
                                    <div className={styles.featuredDate}>{new Date(featuredPost.created_at).toLocaleDateString()}</div>
                                    <h2 className={styles.featuredTitle}>{featuredPost.title}</h2>
                                    <p className={styles.featuredDesc}>{featuredPost.excerpt}</p>
                                    <Link href={`/blog/${featuredPost.slug}`} className={styles.readMoreBtn}>
                                        Read Article <IconArrowRight />
                                    </Link>
                                </div>
                            </div>
                        </div>
                    </section>
                </AnimateOnScroll>
            )}

            {/* 3. Articles Grid */}
            <AnimateOnScroll animation="fadeUp" delay={100}>
                <section className={styles.articlesSection}>
                    <div className="premium-container">
                        <div className={styles.categoryRow}>
                            {CATEGORIES.map(cat => (
                                <button
                                    key={cat}
                                    className={`${styles.chip} ${activeCategory === cat ? styles.chipActive : ''}`}
                                    onClick={() => setActiveCategory(cat)}
                                >
                                    {cat}
                                </button>
                            ))}
                        </div>

                        {displayPosts.length > 0 ? (
                            <div className={styles.articlesGrid}>
                                {displayPosts.map((post, i) => (
                                    <div key={post.id} className={styles.articleCard}>
                                        <div className={styles.cardBanner}>
                                            <Image
                                                src={post.cover_image || "/images/tech-office.jpg"}
                                                alt={post.title}
                                                fill
                                                className={styles.cardImg}
                                                style={{ objectFit: 'cover' }}
                                            />
                                            <span className={styles.catTag}>{post.category}</span>
                                        </div>
                                        <div className={styles.cardBody}>
                                            <div className={styles.cardDate}>{new Date(post.created_at).toLocaleDateString()}</div>
                                            <h3 className={styles.cardTitle}>{post.title}</h3>
                                            <p className={styles.cardDesc}>{post.excerpt}</p>
                                            <Link href={`/blog/${post.slug}`} className={styles.readLink}>
                                                Read Article <IconArrowRight />
                                            </Link>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        ) : !featuredPost && (
                            <div style={{ textAlign: 'center', padding: '4rem 0', color: 'var(--medium-grey)' }}>
                                <div style={{ fontSize: '3rem', marginBottom: '1rem' }}>🔍</div>
                                <p style={{ fontSize: '1.1rem' }}>No articles found. Try a different search or category.</p>
                            </div>
                        )}
                    </div>
                </section>
            </AnimateOnScroll>

            {/* 4. Newsletter */}
            <AnimateOnScroll animation="scaleUp">
                <section className={styles.newsletterSection}>
                    <div className="premium-container">
                        <div className={styles.newsletterCard}>
                            <h2>Never miss an update.</h2>
                            <p>
                                Get the latest insights on AI recruitment and talent strategy delivered straight to your inbox every week.
                            </p>
                            <div className={styles.emailForm}>
                                <input
                                    type="email"
                                    placeholder="Enter your email address"
                                    className={styles.emailInput}
                                />
                                <button className={styles.subscribeBtn}>Subscribe</button>
                            </div>
                        </div>
                    </div>
                </section>
            </AnimateOnScroll>
        </main>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Image from 'next/image';
import Link from 'next/link';
import styles from '../blog.module.css';
import { insforge } from '@/lib/insforge';
import AnimateOnScroll from '@/components/AnimateOnScroll';

const IconArrowLeft = () => (
    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M19 12H5m7-7-7 7 7 7" />
    </svg>
);

const IconArrowRight = () => (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M5 12h14m-7-7 7 7-7 7" />
    </svg>
);

export default function BlogDetailPage() {
    const { slug } = useParams();
    const router = useRouter();
    const [post, setPost] = useState<any>(null);
    const [related, setRelated] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchPost() {
            try {
                const { data, error } = await insforge.database
                    .from('blog')
                    .select('*, author:profiles(name)')
                    .eq('slug', slug)
                    .single();

                if (error || !data) throw new Error('Not found');

                setPost(data);

                // Fetch Related
                const { data: rel } = await insforge.database
                    .from('blog')
                    .select('*')
                    .eq('status', 'published')
                    .neq('id', data.id)
                    .eq('category', data.category)
                    .limit(3);
                setRelated(rel || []);
            } catch (err) {
                console.error(err);
                router.push('/blog');
            } finally {
                setLoading(false);
            }
        }
        if (slug) fetchPost();
    }, [slug, router]);

    if (loading) return (
        <div style={{ height: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: '#fff' }}>
            <div style={{ width: 40, height: 40, border: '4px solid #f3f3f3', borderTopColor: '#007BFF', borderRadius: '50%', animation: 'spin 1s linear infinite' }} />
            <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
        </div>
    );

    if (!post) return null;

    return (
        <main style={{ background: '#fff', minHeight: '100vh', paddingBottom: '6rem' }}>
            {/* Header / Back */}
            <div className="premium-container" style={{ paddingTop: '2rem' }}>
                <button onClick={() => router.back()} style={{ display: 'flex', alignItems: 'center', gap: '0.5rem', background: 'none', border: 'none', color: '#64748b', fontWeight: 600, cursor: 'pointer', fontSize: '0.9rem' }}>
                    <IconArrowLeft /> Back to Blog
                </button>
            </div>

            {/* Article Content */}
            <article>
                <header className="premium-container" style={{ marginTop: '3rem', textAlign: 'center' }}>
                    <AnimateOnScroll animation="fadeUp">
                        <span style={{ color: 'var(--primary-blue)', fontWeight: 700, fontSize: '0.85rem', textTransform: 'uppercase', letterSpacing: '0.1em' }}>
                            {post.category}
                        </span>
                        <h1 style={{ fontSize: '3.5rem', fontWeight: 800, marginTop: '1rem', color: '#0f172a', lineHeight: '1.2', maxWidth: '900px', margin: '1rem auto' }}>
                            {post.title}
                        </h1>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '1rem', marginTop: '2rem', color: '#64748b', fontSize: '0.9rem' }}>
                            <div style={{ width: '40px', height: '40px', background: 'var(--primary-blue)', borderRadius: '50%', color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 700 }}>
                                {post.author?.name?.charAt(0) || 'A'}
                            </div>
                            <div style={{ textAlign: 'left' }}>
                                <div style={{ fontWeight: 700, color: '#0f172a' }}>{post.author?.name || 'Talentmesh Editorial'}</div>
                                <div>{new Date(post.created_at).toLocaleDateString(undefined, { month: 'long', day: 'numeric', year: 'numeric' })} • 5 min read</div>
                            </div>
                        </div>
                    </AnimateOnScroll>
                </header>

                <AnimateOnScroll animation="fadeUp" delay={100}>
                    <div className="premium-container" style={{ marginTop: '4rem' }}>
                        <div style={{ position: 'relative', width: '100%', height: '500px', borderRadius: '24px', overflow: 'hidden', boxShadow: '0 20px 40px rgba(0,0,0,0.1)' }}>
                            <Image 
                                src={post.cover_image || "/images/tech-office.jpg"} 
                                alt={post.title} 
                                fill 
                                style={{ objectFit: 'cover' }}
                                priority
                            />
                        </div>
                    </div>
                </AnimateOnScroll>

                <div className="premium-container" style={{ marginTop: '5rem', maxWidth: '800px' }}>
                    <AnimateOnScroll animation="fadeUp" delay={200}>
                        <div style={{ fontSize: '1.25rem', color: '#334155', lineHeight: '1.8', whiteSpace: 'pre-wrap', fontFamily: 'var(--font-inter)' }}>
                            {post.content}
                        </div>
                    </AnimateOnScroll>
                </div>
            </article>

            {/* Related Posts */}
            {related.length > 0 && (
                <section style={{ marginTop: '10rem', background: '#f8fafc', padding: '6rem 0' }}>
                    <div className="premium-container">
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '3rem' }}>
                            <h2 style={{ fontSize: '2rem', fontWeight: 800, color: '#0f172a' }}>Related Articles</h2>
                            <Link href="/blog" style={{ color: 'var(--primary-blue)', fontWeight: 700, textDecoration: 'none' }}>View All</Link>
                        </div>
                        <div className="premium-grid-3">
                            {related.map(rel => (
                                <Link href={`/blog/${rel.slug}`} key={rel.id} style={{ textDecoration: 'none' }}>
                                    <div className="glass-card" style={{ background: '#fff', height: '100%', display: 'flex', flexDirection: 'column' }}>
                                        <div style={{ position: 'relative', height: '180px' }}>
                                            <Image src={rel.cover_image || "/images/tech-office.jpg"} alt={rel.title} fill style={{ objectFit: 'cover' }} />
                                        </div>
                                        <div style={{ padding: '1.5rem' }}>
                                            <span style={{ fontSize: '0.7rem', fontWeight: 700, color: 'var(--primary-blue)', textTransform: 'uppercase' }}>{rel.category}</span>
                                            <h3 style={{ fontSize: '1.1rem', fontWeight: 700, color: '#0f172a', marginTop: '0.5rem' }}>{rel.title}</h3>
                                            <div style={{ marginTop: '1rem', display: 'flex', alignItems: 'center', gap: '0.4rem', color: 'var(--primary-blue)', fontWeight: 700, fontSize: '0.8rem' }}>
                                                Read More <IconArrowRight />
                                            </div>
                                        </div>
                                    </div>
                                </Link>
                            ))}
                        </div>
                    </div>
                </section>
            )}

            {/* Newsletter Shortcut */}
            <div className="premium-container" style={{ marginTop: '8rem' }}>
                <div style={{ background: 'linear-gradient(135deg, #0f172a 0%, #1e40af 100%)', borderRadius: '32px', padding: '4rem', textAlign: 'center', color: '#fff' }}>
                    <h2 style={{ fontSize: '2.5rem', fontWeight: 800 }}>Enjoyed this article?</h2>
                    <p style={{ marginTop: '1rem', color: '#cbd5e1', fontSize: '1.1rem' }}>Subscribe to our newsletter and never miss an update on AI recruitment.</p>
                    <div style={{ marginTop: '2.5rem', display: 'flex', gap: '1rem', justifyContent: 'center', flexWrap: 'wrap' }}>
                        <input type="email" placeholder="your@email.com" style={{ padding: '1rem 1.5rem', borderRadius: '12px', border: 'none', width: '100%', maxWidth: '300px', fontSize: '1rem' }} />
                        <button style={{ padding: '1rem 2rem', borderRadius: '12px', border: 'none', background: '#fff', color: '#0f172a', fontWeight: 700, cursor: 'pointer' }}>Subscribe Now</button>
                    </div>
                </div>
            </div>
        </main>
    );
}

/* ─── Page Layout ────────────────────────────────────────────────────────────── */
.page {
    padding-top: 68px;
    /* navbar height */
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ───────────────────────────────────────────────────────────────────── */
.hero {
    background: radial-gradient(ellipse 80% 60% at 50% 0%, var(--alice-blue, #E3F2FD), var(--light-ice-blue, #F0F7FF));
    padding: 56px 0 48px;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.heroContent {
    text-align: center;
}

.heroTitle {
    font-size: clamp(2rem, 5vw, 3.25rem);
    font-weight: 800;
    color: var(--cobalt-blue, #0D47A1);
    margin: 0 0 12px;
    letter-spacing: -0.02em;
    line-height: 1.15;
}

.heroSub {
    font-size: 1.1rem;
    color: var(--medium-grey, #475569);
    margin: 0 auto 32px;
    max-width: 540px;
}

/* Search bar */
.searchCard {
    display: flex;
    align-items: center;
    background: white;
    border-radius: 16px;
    box-shadow: 0 8px 32px -4px rgba(0, 0, 0, 0.12);
    overflow: hidden;
    max-width: 780px;
    margin: 0 auto;
    border: 1px solid rgba(144, 202, 249, 0.4);
}

.searchField {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 0 16px;
    flex: 1;
    color: var(--medium-grey);
    min-width: 0;
}

.searchInput,
.searchSelect {
    border: none;
    outline: none;
    background: transparent;
    font-size: 0.93rem;
    color: var(--deep-navy, #0d2137);
    width: 100%;
    padding: 18px 0;
    font-family: inherit;
    appearance: none;
}

.searchInput::placeholder {
    color: rgba(71, 85, 105, 0.55);
}

.searchSelect {
    cursor: pointer;
}

.searchDivider {
    width: 1px;
    height: 32px;
    background: var(--sky-blue, #90CAF9);
    flex-shrink: 0;
}

.searchBtn {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--primary-blue, #007BFF);
    color: white;
    border: none;
    padding: 0 28px;
    height: 58px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.searchBtn:hover {
    background: #0069d9;
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

/* Popular Tags */
.popularTags {
    display: flex;
    align-items: center;
    gap: 8px;
    justify-content: center;
    flex-wrap: wrap;
    margin-top: 20px;
}

.popularLabel {
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--medium-grey);
    text-transform: uppercase;
    letter-spacing: 0.06em;
}

.popularTag {
    padding: 6px 14px;
    border-radius: 999px;
    border: 1px solid var(--sky-blue, #90CAF9);
    background: var(--alice-blue, #E3F2FD);
    color: var(--ocean-deep, #1565C0);
    font-size: 0.82rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
}

.popularTag:hover {
    background: var(--dodger-blue, #2196F3);
    color: white;
    border-color: var(--dodger-blue);
}

/* ─── Body Layout ────────────────────────────────────────────────────────────── */
.body {
    display: flex;
    gap: 28px;
    padding: 32px 0 60px;
    align-items: flex-start;
}

/* ─── Sidebar ────────────────────────────────────────────────────────────────── */
.sidebar {
    width: 256px;
    min-width: 256px;
    background: white;
    border-radius: 14px;
    border: 1px solid var(--sky-blue, #90CAF9);
    border-left: 3px solid var(--sky-blue, #90CAF9);
    overflow: hidden;
    position: sticky;
    top: 88px;
}

.sidebarHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 16px 12px;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.sidebarTitle {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--cobalt-blue);
}

.sidebarClose {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--medium-grey);
    padding: 4px;
    display: none;
    line-height: 0;
}

/* Active filter chips */
.activeFilters {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    padding: 10px 14px;
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.activeChip {
    display: flex;
    align-items: center;
    gap: 4px;
    background: var(--cool-sky-2, #42A5F5);
    color: white;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 3px 8px;
    border-radius: 999px;
}

.activeChip button {
    background: none;
    border: none;
    color: white;
    cursor: pointer;
    font-size: 0.85rem;
    padding: 0;
    line-height: 1;
}

.clearAll {
    font-size: 0.75rem;
    color: var(--primary-blue);
    background: none;
    border: none;
    cursor: pointer;
    text-decoration: underline;
    padding: 2px 0;
}

/* Filter groups */
.filterGroup {
    border-bottom: 1px solid var(--sky-blue, #90CAF9);
}

.filterGroup:last-child {
    border-bottom: none;
}

.filterGroupHdr {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 12px 16px;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--cobalt-blue, #0D47A1);
    text-transform: uppercase;
    letter-spacing: 0.07em;
    text-align: left;
}

.filterGroupBody {
    padding: 4px 16px 12px;
}

.filterCheck {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.87rem;
    color: var(--medium-grey, #475569);
    cursor: pointer;
    padding: 5px 0;
    transition: color 0.15s;
}

.filterCheck:hover {
    color: var(--primary-blue);
}

.filterCheck input {
    accent-color: var(--primary-blue, #007BFF);
    width: 15px;
    height: 15px;
    cursor: pointer;
}

/* ─── Main Content ────────────────────────────────────────────────────────────── */
.main {
    flex: 1;
    min-width: 0;
}

.overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.4);
    z-index: 900;
}

/* Mobile filter btn */
.mobileFilterBtn {
    display: none;
    align-items: center;
    gap: 8px;
    background: white;
    border: 1px solid var(--sky-blue);
    border-radius: 8px;
    padding: 10px 18px;
    font-size: 0.9rem;
    font-weight: 600;
    color: var(--cobalt-blue);
    cursor: pointer;
    margin-bottom: 16px;
}

.filterCount {
    background: var(--primary-blue);
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    border-radius: 999px;
    padding: 1px 7px;
}

/* Category chips */
.categoryRow {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    scrollbar-width: none;
    margin-bottom: 20px;
    padding-bottom: 2px;
}

.categoryRow::-webkit-scrollbar {
    display: none;
}

.categoryChip {
    display: flex;
    align-items: center;
    white-space: nowrap;
    padding: 7px 16px;
    border-radius: 999px;
    background: var(--alice-blue, #E3F2FD);
    color: var(--ocean-deep, #1565C0);
    border: 1px solid transparent;
    font-size: 0.83rem;
    font-weight: 500;
    cursor: pointer;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.categoryChip:hover {
    background: var(--light-ice-blue);
    border-color: var(--sky-blue);
}

.categoryChipActive {
    background: var(--dodger-blue, #2196F3) !important;
    color: white !important;
    box-shadow: 0 2px 8px rgba(33, 150, 243, 0.35);
}

/* Results header */
.resultsHdr {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 16px;
}

.resultsCount {
    font-size: 0.9rem;
    color: var(--medium-grey);
}

.resultsCount strong {
    color: var(--cobalt-blue);
}

.aiPill {
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: var(--alice-blue);
    border: 1px solid rgba(0, 123, 255, 0.2);
    padding: 4px 12px;
    border-radius: 999px;
}

/* ─── Job Cards ────────────────────────────────────────────────────────────────── */
.jobGrid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
    gap: 20px;
}

.jobCard {
    background: white;
    border-radius: 14px;
    border: 1px solid var(--sky-blue, #90CAF9);
    padding: 20px;
    display: flex;
    flex-direction: column;
    gap: 14px;
    transition: transform 0.22s ease, box-shadow 0.22s ease;
    cursor: pointer;
}

.jobCard:hover {
    transform: translateY(-4px);
    box-shadow: 0 16px 40px rgba(0, 0, 0, 0.10);
    border-color: rgba(255, 255, 255, 0.8);
}

.cardTop {
    display: flex;
    align-items: flex-start;
    gap: 12px;
}

.jobLogo {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-weight: 700;
    font-size: 0.85rem;
    flex-shrink: 0;
}

.jobInfo {
    flex: 1;
    min-width: 0;
}

.jobTitle {
    font-size: 1rem;
    font-weight: 700;
    color: var(--cobalt-blue, #0D47A1);
    margin-bottom: 4px;
    transition: text-decoration 0.15s;
}

.jobCard:hover .jobTitle {
    text-decoration: underline;
}

.jobMeta {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.82rem;
    color: var(--medium-grey, #475569);
    flex-wrap: wrap;
}

.metaDot {
    opacity: 0.4;
}

/* Save button */
.saveBtn {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--sky-blue, #90CAF9);
    padding: 6px;
    border-radius: 8px;
    line-height: 0;
    transition: all 0.2s ease;
    flex-shrink: 0;
}

.saveBtn:hover {
    color: var(--primary-blue);
    background: var(--alice-blue);
}

.saveBtnActive {
    color: var(--primary-blue) !important;
    animation: pulse 0.35s ease;
}

@keyframes pulse {
    0% {
        transform: scale(1);
    }

    50% {
        transform: scale(1.3);
    }

    100% {
        transform: scale(1);
    }
}

/* Badge row */
.badgeRow {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
}

.typeBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    color: white;
    background: var(--dodger-blue, #2196F3);
}

.type_Remote {
    background: var(--cool-sky-2, #42A5F5);
}

.type_PartTime {
    background: var(--brilliant-azure, #1E88E5);
}

.type_Contract {
    background: #7C3AED;
}

.type_Internship {
    background: #059669;
}

.salaryBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: var(--alice-blue, #E3F2FD);
    color: var(--ocean-deep, #1565C0);
}

.countryBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: linear-gradient(135deg, #f0fdf4, #ecfdf5);
    color: #065f46;
    border: 1px solid rgba(16, 185, 129, 0.15);
    display: flex;
    align-items: center;
    gap: 3px;
}

.matchBadge {
    font-size: 0.72rem;
    font-weight: 700;
    padding: 3px 10px;
    border-radius: 999px;
    background: rgba(0, 123, 255, 0.08);
    display: flex;
    align-items: center;
    gap: 4px;
}

/* Card footer */
.cardFooter {
    display: flex;
    align-items: center;
    justify-content: space-between;
    border-top: 1px solid var(--sky-blue, #90CAF9);
    padding-top: 12px;
    margin-top: auto;
}

.postedMeta {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.78rem;
    color: var(--medium-grey);
}

.cardActions {
    display: flex;
    gap: 8px;
    align-items: center;
}

.applyBtn {
    background: var(--primary-blue, #007BFF);
    color: white;
    border: none;
    padding: 7px 16px;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.applyBtn:hover {
    background: #0069d9;
    box-shadow: 0 4px 12px rgba(0, 123, 255, 0.35);
}

.viewBtn {
    display: flex;
    align-items: center;
    gap: 4px;
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--ocean-deep, #1565C0);
    text-decoration: none;
    transition: color 0.15s;
}

.viewBtn:hover {
    color: var(--primary-blue);
}

/* ─── Empty State ─────────────────────────────────────────────────────────────── */
.emptyState {
    text-align: center;
    padding: 64px 24px;
    background: white;
    border-radius: 16px;
    border: 1px solid var(--sky-blue);
}

.emptyIco {
    margin-bottom: 16px;
}

.emptyTitle {
    font-size: 1.25rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 6px;
}

.emptyDesc {
    font-size: 0.95rem;
    color: var(--medium-grey);
    margin: 0 0 16px;
}

.emptyLink {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    color: var(--primary-blue);
    font-weight: 600;
    text-decoration: underline;
    font-size: 0.95rem;
}

/* ─── Pagination ───────────────────────────────────────────────────────────────── */
.pagination {
    display: flex;
    justify-content: center;
    gap: 8px;
    margin-top: 40px;
}

.pageBtn {
    width: 38px;
    height: 38px;
    border-radius: 8px;
    border: 1px solid var(--sky-blue);
    background: var(--alice-blue);
    color: var(--ocean-deep);
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.15s ease;
}

.pageBtn:hover {
    background: var(--light-ice-blue);
    border-color: var(--primary-blue);
}

.pageBtnActive {
    background: var(--primary-blue) !important;
    color: white !important;
    border-color: var(--primary-blue) !important;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

/* ─── Responsive ────────────────────────────────────────────────────────────────── */
@media (max-width: 1024px) {
    .sidebar {
        position: fixed;
        left: 0;
        top: 0;
        bottom: 0;
        z-index: 910;
        transform: translateX(-100%);
        transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
        border-radius: 0 16px 16px 0;
        overflow-y: auto;
        width: 280px;
        min-width: 280px;
    }

    .sidebarOpen {
        transform: translateX(0);
    }

    .sidebarClose {
        display: flex;
    }

    .mobileFilterBtn {
        display: flex;
    }
}

@media (max-width: 640px) {
    .hero {
        padding: 40px 0 32px;
    }

    .searchCard {
        flex-direction: column;
        border-radius: 12px;
    }

    .searchField {
        width: 100%;
    }

    .searchDivider {
        width: 100%;
        height: 1px;
    }

    .searchBtn {
        width: 100%;
        justify-content: center;
    }

    .jobGrid {
        grid-template-columns: 1fr;
    }
}

