}

.card h2 {
  margin: 0 0 10px;
  color: #0f172a;
  font-size: 1.1rem;
}

.card p {
  margin: 0;
  color: #475569;
  line-height: 1.6;
}

.cardLink {
  display: inline-block;
  margin-top: 16px;
  color: #2563eb;
  font-weight: 700;
}

@media (max-width: 720px) {
  .page {
    padding: 18px;
  }

  .hero {
    flex-direction: column;
  }

  .statusCard {
    min-width: 0;
    width: 100%;
  }
