'use client';
import React, { useState, useEffect, useMemo } from 'react';
import Link from 'next/link';
import { getMyApplications, withdrawApplication, type Application, type ApplicationStatus } from '@/lib/api/applications';
import { useAuth } from '@/lib/auth/AuthContext';
import { insforge } from '@/lib/insforge';
import { formatDistanceToNow } from 'date-fns';
import Toast from '@/components/ui/Toast';
import styles from '../candidate.module.css';

// ─── Icons ──────────────────────────────────────────────────────────────────────
const IC = {
    Location: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" /><circle cx="12" cy="10" r="3" /></svg>,
    Briefcase: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" /><path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2" /></svg>,
    Clock: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>,
    Check: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>,
    External: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" /><polyline points="15 3 21 3 21 9" /><line x1="10" y1="14" x2="21" y2="3" /></svg>,
    Withdraw: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M18 6 6 18M6 6l12 12" /></svg>,
};

const STATUS_MAP: Record<ApplicationStatus, { label: string, color: string, stage: number }> = {
    applied: { label: 'Applied', color: '#3b82f6', stage: 1 },
    reviewing: { label: 'Under Review', color: '#f59e0b', stage: 2 },
    shortlisted: { label: 'Shortlisted', color: '#10b981', stage: 3 },
    interview: { label: 'Interviewing', color: '#7c3aed', stage: 4 },
    offer: { label: 'Offer Received', color: '#10b981', stage: 5 },
    accepted: { label: 'Accepted', color: '#10b981', stage: 5 },
    rejected: { label: 'Not Selected', color: '#ef4444', stage: 0 },
    withdrawn: { label: 'Withdrawn', color: '#64748b', stage: 0 },
};

export default function ApplicationsPage() {
    const { user } = useAuth();
    const [applications, setApplications] = useState<Application[]>([]);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState<'all' | 'active' | 'rejected' | 'withdrawn'>('all');
    const [toast, setToast] = useState<{ message: string, type: 'success' | 'error' | 'info' } | null>(null);

    const fetchData = async () => {
        try {
            const data = await getMyApplications();
            setApplications(data);
        } catch (err) {
            console.error('Failed to fetch applications:', err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (user) {
            fetchData();

            const channelName = `candidate-apps-${user.id}`;
            insforge.realtime.connect().catch(console.error);
            insforge.realtime.subscribe(channelName).catch(console.error);

            const handleUpdate = (payload: any) => {
                const updatedApp = payload?.new || payload;
                if (updatedApp && updatedApp.id && updatedApp.status) {
                    setApplications(prev => prev.map(app => app.id === updatedApp.id ? { ...app, ...updatedApp } : app));
                    setToast({ message: `Your application status has been updated to ${updatedApp.status}`, type: 'info' });
                }
            };

            insforge.realtime.on('postgres_changes', handleUpdate);
            insforge.realtime.on('UPDATE', handleUpdate);

            return () => { 
                insforge.realtime.unsubscribe(channelName);
            };
        }
    }, [user]);

    const stats = useMemo(() => {
        return {
            total: applications.length,
            active: applications.filter(a => !['rejected', 'withdrawn', 'accepted'].includes(a.status)).length,
            offers: applications.filter(a => a.status === 'offer').length
        };
    }, [applications]);

    const filteredApps = useMemo(() => {
        if (activeTab === 'all') return applications;
        if (activeTab === 'active') return applications.filter(a => !['rejected', 'withdrawn', 'accepted'].includes(a.status));
        return applications.filter(a => a.status === activeTab);
    }, [applications, activeTab]);

    const handleWithdraw = async (id: string) => {
        if (!confirm('Are you sure you want to withdraw this application?')) return;

        const originalApps = [...applications];
        setApplications(prev => prev.map(app => app.id === id ? { ...app, status: 'withdrawn' } : app));

        try {
            await withdrawApplication(id);
            setToast({ message: 'Application withdrawn successfully', type: 'success' });
        } catch (err) {
            setApplications(originalApps);
            setToast({ message: 'Failed to withdraw application', type: 'error' });
        }
    };

    if (loading) return <div style={{ padding: '80px 0', textAlign: 'center' }}>Loading applications...</div>;

    return (
        <div style={{ padding: '1rem', display: 'flex', flexDirection: 'column', gap: '2rem' }}>
            {toast && <Toast message={toast.message} type={toast.type} onClose={() => setToast(null)} />}

            {/* Header & Stats */}
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                    <h1 style={{ fontSize: '1.75rem', fontWeight: 800, color: '#0f172a', margin: 0 }}>My Applications</h1>
                    <p style={{ color: '#64748b', fontSize: '0.9rem', marginTop: '0.25rem' }}>Track your journey across {stats.total} roles.</p>
                </div>
                <div style={{ display: 'flex', gap: '1rem' }}>
                    <div className={styles.statCard} style={{ padding: '0.75rem 1.5rem', background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '12px', textAlign: 'center' }}>
                        <div style={{ fontSize: '1.25rem', fontWeight: 800, color: '#0f172a' }}>{stats.total}</div>
                        <div style={{ fontSize: '0.75rem', color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em', fontWeight: 700 }}>Applied</div>
                    </div>
                    <div className={styles.statCard} style={{ padding: '0.75rem 1.5rem', background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '12px', textAlign: 'center' }}>
                        <div style={{ fontSize: '1.25rem', fontWeight: 800, color: '#166534' }}>{stats.active}</div>
                        <div style={{ fontSize: '0.75rem', color: '#15803d', textTransform: 'uppercase', letterSpacing: '0.05em', fontWeight: 700 }}>Active</div>
                    </div>
                    <div className={styles.statCard} style={{ padding: '0.75rem 1.5rem', background: '#fffbeb', border: '1px solid #fde68a', borderRadius: '12px', textAlign: 'center' }}>
                        <div style={{ fontSize: '1.25rem', fontWeight: 800, color: '#92400e' }}>{stats.offers}</div>
                        <div style={{ fontSize: '0.75rem', color: '#b45309', textTransform: 'uppercase', letterSpacing: '0.05em', fontWeight: 700 }}>Offers</div>
                    </div>
                </div>
            </div>

            {/* Filters */}
            <div style={{ display: 'flex', gap: '0.5rem', borderBottom: '1px solid #e2e8f0', paddingBottom: '1px' }}>
                {(['all', 'active', 'rejected', 'withdrawn'] as const).map(tab => (
                    <button
                        key={tab}
                        onClick={() => setActiveTab(tab)}
                        style={{
                            padding: '0.75rem 1.5rem',
                            border: 'none',
                            background: 'transparent',
                            color: activeTab === tab ? 'var(--primary-blue)' : '#64748b',
                            fontSize: '0.9rem',
                            fontWeight: 700,
                            cursor: 'pointer',
                            borderBottom: activeTab === tab ? '2px solid var(--primary-blue)' : '2px solid transparent',
                            transition: 'all 0.2s',
                            textTransform: 'capitalize'
                        }}
                    >
                        {tab}
                    </button>
                ))}
            </div>

            {/* List */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
                {filteredApps.length === 0 ? (
                    <div style={{ padding: '80px 0', textAlign: 'center', background: '#f8fafc', borderRadius: '16px', border: '1px dashed #cbd5e1' }}>
                        <div style={{ fontSize: '2.5rem', marginBottom: '1rem' }}>📁</div>
                        <h3 style={{ fontSize: '1.2rem', fontWeight: 700, color: '#0f172a' }}>No applications yet</h3>
                        <p style={{ color: '#64748b', marginBottom: '1.5rem' }}>Start your journey by browsing available roles.</p>
                        <Link href="/dashboard/candidate/jobs" style={{ background: 'var(--primary-blue)', color: 'white', padding: '0.75rem 1.5rem', borderRadius: '10px', textDecoration: 'none', fontWeight: 600 }}>Browse Jobs</Link>
                    </div>
                ) : (
                    filteredApps.map(app => {
                        const statusInfo = STATUS_MAP[app.status];
                        const isTerminal = ['rejected', 'withdrawn', 'accepted'].includes(app.status);

                        return (
                            <div key={app.id} style={{ 
                                background: 'white', 
                                border: '1px solid #e2e8f0', 
                                borderRadius: '16px', 
                                padding: '1.5rem',
                                transition: 'transform 0.2s, box-shadow 0.2s',
                                display: 'flex',
                                flexDirection: 'column',
                                gap: '1.25rem'
                            }}>
                                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                    <div style={{ display: 'flex', gap: '1rem', alignItems: 'center' }}>
                                        <div style={{ 
                                            width: '56px', height: '56px', borderRadius: '12px', 
                                            background: '#f1f5f9', border: '1px solid #e2e8f0',
                                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                                            fontWeight: 800, color: 'var(--primary-blue)', overflow: 'hidden'
                                        }}>
                                            {app.jobs.companies.logo_url ? (
                                                <img src={app.jobs.companies.logo_url} alt={app.jobs.companies.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                            ) : app.jobs.companies.name[0]}
                                        </div>
                                        <div>
                                            <h3 style={{ fontSize: '1.1rem', fontWeight: 800, color: '#0f172a', margin: 0 }}>{app.jobs.title}</h3>
                                            <div style={{ display: 'flex', gap: '1rem', marginTop: '0.25rem', fontSize: '0.85rem', color: '#64748b', fontWeight: 500 }}>
                                                <span>{app.jobs.companies.name}</span>
                                                <span>•</span>
                                                <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><IC.Location /> {app.jobs.location}</span>
                                                <span>•</span>
                                                <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><IC.Briefcase /> {app.jobs.type}</span>
                                            </div>
                                        </div>
                                    </div>
                                    <div style={{ textAlign: 'right' }}>
                                        <span style={{ 
                                            background: statusInfo.color + '15', 
                                            color: statusInfo.color,
                                            padding: '0.4rem 0.8rem',
                                            borderRadius: '8px',
                                            fontSize: '0.75rem',
                                            fontWeight: 700,
                                            textTransform: 'uppercase',
                                            letterSpacing: '0.02em',
                                            display: 'inline-block'
                                        }}>
                                            {statusInfo.label}
                                        </span>
                                        <div style={{ marginTop: '0.5rem', fontSize: '0.75rem', color: '#94a3b8' }}>
                                            Applied {formatDistanceToNow(new Date(app.applied_at))} ago
                                        </div>
                                    </div>
                                </div>

                                {/* Progress Bar */}
                                {!isTerminal ? (
                                    <div style={{ background: '#f8fafc', padding: '1.25rem', borderRadius: '12px' }}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '0.75rem' }}>
                                            {['Applied', 'Review', 'Shortlist', 'Interview', 'Offer'].map((s, idx) => (
                                                <span key={s} style={{ 
                                                    fontSize: '0.7rem', 
                                                    fontWeight: 700, 
                                                    color: statusInfo.stage > idx ? 'var(--primary-blue)' : '#94a3b8',
                                                    textTransform: 'uppercase'
                                                }}>{s}</span>
                                            ))}
                                        </div>
                                        <div style={{ display: 'flex', gap: '4px', height: '6px' }}>
                                            {[1, 2, 3, 4, 5].map(step => (
                                                <div key={step} style={{ 
                                                    flex: 1, 
                                                    background: statusInfo.stage >= step ? 'var(--primary-blue)' : '#e2e8f0',
                                                    borderRadius: '4px'
                                                }} />
                                            ))}
                                        </div>
                                    </div>
                                ) : (
                                    app.status === 'rejected' && (
                                        <div style={{ background: '#fef2f2', padding: '1rem', borderRadius: '12px', border: '1px solid #fee2e2', color: '#991b1b', fontSize: '0.9rem' }}>
                                            Thank you for your interest. The company has decided to move forward with other candidates at this time.
                                        </div>
                                    )
                                )}

                                <div style={{ display: 'flex', gap: '0.75rem', justifyContent: 'flex-end' }}>
                                    {['applied', 'reviewing', 'shortlisted'].includes(app.status) && (
                                        <button 
                                            onClick={() => handleWithdraw(app.id)}
                                            style={{ 
                                                padding: '0.6rem 1rem', borderRadius: '10px', 
                                                background: 'white', border: '1px solid #e2e8f0',
                                                color: '#ef4444', fontWeight: 600, fontSize: '0.85rem',
                                                cursor: 'pointer', display: 'flex', alignItems: 'center', gap: '0.4rem'
                                            }}
                                        >
                                            <IC.Withdraw /> Withdraw
                                        </button>
                                    )}
                                    <Link href={`/dashboard/candidate/jobs/${app.job_id}`} style={{ 
                                        padding: '0.6rem 1rem', borderRadius: '10px', 
                                        background: '#f1f5f9', color: '#475569',
                                        textDecoration: 'none', fontWeight: 600, fontSize: '0.85rem',
                                        display: 'flex', alignItems: 'center', gap: '0.4rem'
                                    }}>
                                        View Job <IC.External />
                                    </Link>
                                </div>
                            </div>
                        );
                    })
                )}
            </div>
        </div>
    );
}

/* ============================
   CANDIDATE DASHBOARD PAGES
   ============================ */

.dash {
    display: flex;
    flex-direction: column;
    gap: 1.15rem;
}

/* Greeting */
.greet {}

.greetTitle {
    font-size: 1.35rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
}

.greetSub {
    font-size: 0.8rem;
    color: #94a3b8;
    margin-top: 0.1rem;
}

/* Stats */
.stats {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.75rem;
}

.stat {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1rem 1.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
    transition: box-shadow 0.2s ease;
}

.stat:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
}

.statTop {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.statLabel {
    font-size: 0.72rem;
    color: #94a3b8;
    font-weight: 500;
}

.statIconBox {
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
}

.statVal {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
}

.statChange {
    font-size: 0.68rem;
    color: #10b981;
    font-weight: 600;
}

.statHint {
    font-size: 0.68rem;
    color: #94a3b8;
}

/* Main grid */
.mainGrid {
    display: grid;
    grid-template-columns: 1fr 320px;
    gap: 0.75rem;
}

.leftCol {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.rightCol {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

/* Cards */
.card {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
}

.cardHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.cardTitle {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0;
}

.viewAll {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: none;
    border: none;
    cursor: pointer;
}

.viewAll:hover {
    text-decoration: underline;
}

.moreBtn {
    background: none;
    border: none;
    color: #94a3b8;
    cursor: pointer;
    font-size: 1.1rem;
    letter-spacing: 0.1em;
}

/* Job cards */
.jobCard {
    display: flex;
    gap: 0.75rem;
    padding: 0.85rem;
    border: 1px solid #f1f5f9;
    border-radius: 10px;
    transition: all 0.15s ease;
}

.jobCard:hover {
    background: #fafbfc;
    border-color: #e2e8f0;
}

.jobIcon {
    width: 42px;
    height: 42px;
    border-radius: 10px;
    background: #f1f5f9;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1rem;
    font-weight: 700;
    color: #475569;
    flex-shrink: 0;
}

.jobBody {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    min-width: 0;
}

.jobRow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.jobTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.matchBadge {
    font-size: 0.62rem;
    font-weight: 700;
    color: #10b981;
    background: #f0fdf4;
    padding: 0.15rem 0.5rem;
    border-radius: 12px;
    white-space: nowrap;
}

.jobMeta {
    font-size: 0.7rem;
    color: #94a3b8;
}

.jobTags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
    margin-top: 0.15rem;
}

.tag {
    font-size: 0.62rem;
    font-weight: 500;
    color: #475569;
    background: #f5f7fa;
    padding: 0.15rem 0.5rem;
    border-radius: 5px;
    border: 1px solid #eef0f2;
}

.jobFoot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.3rem;
}

.jobTime {
    font-size: 0.65rem;
    color: #b0b8c4;
}

.viewJobBtn {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: #eff6ff;
    border: none;
    padding: 0.3rem 0.7rem;
    border-radius: 6px;
    cursor: pointer;
    transition: all 0.15s ease;
}

.viewJobBtn:hover {
    background: var(--primary-blue);
    color: white;
}

/* Activity */
.actItem {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.55rem 0;
    border-bottom: 1px solid #f5f7fa;
}

.actItem:last-of-type {
    border-bottom: none;
}

.actIcon {
    font-size: 0.95rem;
    flex-shrink: 0;
}

.actContent {
    flex: 1;
    display: flex;
    flex-direction: column;
}

.actText {
    font-size: 0.78rem;
    color: #374151;
}

.actText b {
    font-weight: 700;
    color: #0f172a;
}

.actTime {
    font-size: 0.65rem;
    color: #b0b8c4;
}

.actAction {
    font-size: 0.68rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: none;
    border: none;
    cursor: pointer;
}

.viewAllFooter {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    background: none;
    border: none;
    cursor: pointer;
    padding-top: 0.3rem;
    align-self: center;
}

.viewAllFooter:hover {
    color: var(--primary-blue);
}

/* Schedule */
.scheduleItem {
    display: flex;
    flex-direction: column;
    gap: 0.2rem;
    padding: 0.75rem;
    border-left: 3px solid var(--primary-blue);
    border-radius: 0 8px 8px 0;
    background: #fafbfc;
}

.schedBadge {
    font-size: 0.6rem;
    font-weight: 800;
    color: var(--primary-blue);
    letter-spacing: 0.04em;
}

.schedTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.schedMeta {
    font-size: 0.7rem;
    color: #94a3b8;
}

.schedDetails {
    display: flex;
    gap: 0.75rem;
    font-size: 0.68rem;
    color: #64748b;
    margin-top: 0.15rem;
}

.joinBtn {
    margin-top: 0.3rem;
    font-size: 0.72rem;
    font-weight: 600;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 6px;
    padding: 0.3rem 0.7rem;
    color: #374151;
    cursor: pointer;
    align-self: flex-start;
    transition: all 0.15s ease;
}

.joinBtn:hover {
    background: var(--primary-blue);
    color: white;
    border-color: var(--primary-blue);
}

.schedDateBlock {
    display: flex;
    align-items: center;
    gap: 0.3rem;
}

.schedDay {
    font-size: 0.62rem;
    font-weight: 700;
    color: #94a3b8;
}

.schedNum {
    font-size: 1.1rem;
    font-weight: 800;
    color: #0f172a;
}

/* Quick Actions */
.quickAction {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.7rem;
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 8px;
    cursor: pointer;
    transition: all 0.15s ease;
    width: 100%;
    font-family: inherit;
    color: #374151;
}

.quickAction:hover {
    background: #f5f7fa;
    border-color: #e2e8f0;
}

.qaIcon {
    font-size: 0.95rem;
}

.qaLabel {
    flex: 1;
    font-size: 0.78rem;
    font-weight: 500;
    text-align: left;
}

/* Featured */
.featuredCard {
    background: linear-gradient(135deg, #1e293b 0%, #0f172a 100%);
    border-radius: 12px;
    padding: 1.2rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
    color: white;
}

.featuredLabel {
    font-size: 0.58rem;
    font-weight: 700;
    color: #94a3b8;
    letter-spacing: 0.08em;
    text-transform: uppercase;
}

.featuredName {
    font-size: 1rem;
    font-weight: 800;
}

.featuredLink {
    font-size: 0.72rem;
    font-weight: 600;
    color: #60a5fa;
    background: none;
    border: none;
    cursor: pointer;
    align-self: flex-start;
    padding: 0;
    margin-top: 0.15rem;
}

/* ── Jobs Page ── */
.jobsPage {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.searchRow {
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}

.searchBarFull {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.55rem 0.85rem;
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 9px;
    min-width: 200px;
}

.searchBarFull input {
    border: none;
    background: none;
    outline: none;
    font-size: 0.82rem;
    color: #0f172a;
    font-family: inherit;
    flex: 1;
}

.searchBarFull input::placeholder {
    color: #b0b8c4;
}

.filterBtn {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.55rem 0.75rem;
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 9px;
    font-size: 0.78rem;
    font-weight: 500;
    color: #64748b;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.15s ease;
    white-space: nowrap;
}

.filterBtn:hover {
    background: #f5f7fa;
    border-color: #e2e8f0;
}

.filterBtnActive {
    background: #eff6ff;
    border-color: var(--primary-blue);
    color: var(--primary-blue);
}

.jobsGrid {
    display: grid;
    grid-template-columns: 380px 1fr;
    gap: 0.75rem;
}

.jobsList {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.jobListCard {
    display: flex;
    gap: 0.65rem;
    padding: 0.85rem;
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 10px;
    cursor: pointer;
    transition: all 0.15s ease;
}

.jobListCard:hover {
    border-color: #bfdbfe;
}

.jobListCardActive {
    border-color: var(--primary-blue);
    background: #fafbfe;
    box-shadow: 0 0 0 2px rgba(0, 123, 255, 0.06);
}

.jobListIcon {
    width: 38px;
    height: 38px;
    border-radius: 9px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.9rem;
    font-weight: 700;
    flex-shrink: 0;
}

.jobListBody {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
}

.jobListTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.jobListCompany {
    font-size: 0.7rem;
    color: #64748b;
}

.jobListMeta {
    display: flex;
    gap: 0.4rem;
    margin-top: 0.2rem;
    flex-wrap: wrap;
}

.jobListTag {
    font-size: 0.6rem;
    font-weight: 500;
    color: #475569;
    background: #f5f7fa;
    padding: 0.1rem 0.4rem;
    border-radius: 4px;
}

.jobListMatch {
    font-size: 0.62rem;
    font-weight: 700;
    color: var(--primary-blue);
    margin-left: auto;
    white-space: nowrap;
}

/* Job Detail Panel */
.jobDetail {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    overflow: hidden;
    position: sticky;
    top: 60px;
}

.jobDetailBanner {
    height: 120px;
    background: linear-gradient(135deg, #1e293b, #334155);
    display: flex;
    align-items: flex-end;
    padding: 0.75rem 1rem;
}

.jobDetailCompany {
    color: white;
    font-size: 0.88rem;
    font-weight: 700;
}

.jobDetailContent {
    padding: 1.1rem;
    display: flex;
    flex-direction: column;
    gap: 0.6rem;
}

.jobDetailTitle {
    font-size: 1.1rem;
    font-weight: 800;
    color: #0f172a;
}

.jobDetailInfoRow {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    font-size: 0.72rem;
    color: #64748b;
}

.jobDetailActions {
    display: flex;
    gap: 0.4rem;
}

.applyBtn {
    padding: 0.6rem 1.75rem;
    background: linear-gradient(135deg, var(--primary-blue), #2563eb);
    color: white;
    border: none;
    border-radius: 10px;
    font-size: 0.9rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    font-family: inherit;
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
    border: 1px solid rgba(255, 255, 255, 0.15);
    display: inline-flex;
    align-items: center;
    justify-content: center;
    white-space: nowrap;
}

.applyBtn:hover {
    background: linear-gradient(135deg, #2563eb, #1d4ed8);
    transform: translateY(-2px) scale(1.02);
    box-shadow: 0 6px 18px rgba(37, 99, 235, 0.4);
}

.saveBtn {
    padding: 0.5rem 0.65rem;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 8px;
    cursor: pointer;
    color: #64748b;
    display: flex;
    align-items: center;
    transition: all 0.15s ease;
}

.saveBtn:hover {
    background: #eef0f2;
}

.matchBox {
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 10px;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.matchBoxTitle {
    font-size: 0.78rem;
    font-weight: 700;
    color: #166534;
}

.matchPoints {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.25rem;
}

.matchPoint {
    font-size: 0.68rem;
    color: #15803d;
    display: flex;
    align-items: flex-start;
    gap: 0.25rem;
}

.matchWarn {
    color: #d97706;
}

.jobSection {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.jobSectionTitle {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
}

.jobSectionText {
    font-size: 0.78rem;
    color: #475569;
    line-height: 1.55;
}

.jobSectionList {
    list-style: disc;
    padding-left: 1.2rem;
}

.jobSectionList li {
    font-size: 0.78rem;
    color: #475569;
    line-height: 1.6;
}

/* ── Applications Pipeline ── */
.pipelinePage {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.pipelineHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 0.5rem;
}

.pipelineTitle {
    font-size: 1.15rem;
    font-weight: 800;
    color: #0f172a;
}

.pipelineSub {
    font-size: 0.78rem;
    color: #94a3b8;
}

.pipelineActions {
    display: flex;
    gap: 0.4rem;
}

.pipelineViewBtn {
    padding: 0.4rem 0.55rem;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 6px;
    cursor: pointer;
    color: #64748b;
    font-size: 0.78rem;
    display: flex;
    align-items: center;
    transition: all 0.15s ease;
}

.pipelineViewBtnActive {
    background: #eff6ff;
    color: var(--primary-blue);
    border-color: var(--primary-blue);
}

.addAppBtn {
    padding: 0.4rem 0.75rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 6px;
    font-size: 0.78rem;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
}

.kanban {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 0.6rem;
}

.kanbanCol {
    display: flex;
    flex-direction: column;
    gap: 0.4rem;
}

.kanbanHeader {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.5rem;
    font-size: 0.72rem;
    font-weight: 700;
    color: #475569;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.kanbanCount {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    font-size: 0.6rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
}

.kanbanCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 10px;
    padding: 0.75rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    transition: all 0.15s ease;
    cursor: pointer;
}

.kanbanCard:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
}

.kanbanCardHead {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.kanbanLogo {
    width: 28px;
    height: 28px;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.55rem;
    font-weight: 700;
    flex-shrink: 0;
    background: #f1f5f9;
    color: #475569;
}

.kanbanCompany {
    font-size: 0.78rem;
    font-weight: 700;
    color: #0f172a;
}

.kanbanRole {
    font-size: 0.68rem;
    color: #94a3b8;
}

.kanbanExtra {
    font-size: 0.62rem;
    color: #94a3b8;
    margin-top: 0.15rem;
}

.kanbanTag {
    display: inline-block;
    font-size: 0.58rem;
    font-weight: 600;
    padding: 0.1rem 0.4rem;
    border-radius: 4px;
}

.kanbanLink {
    font-size: 0.68rem;
    font-weight: 600;
    color: var(--primary-blue);
    text-decoration: none;
    margin-top: 0.15rem;
}

.offerBanner {
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 6px;
    padding: 0.35rem 0.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: 0.15rem;
}

.offerLabel {
    font-size: 0.62rem;
    font-weight: 700;
    color: #10b981;
}

.offerAmount {
    font-size: 0.72rem;
    font-weight: 800;
    color: #0f172a;
}

.offerExpiry {
    font-size: 0.58rem;
    color: #10b981;
    text-align: right;
}

/* ── Profile Page ── */
.profilePage {
    display: grid;
    grid-template-columns: 260px 1fr;
    gap: 0.75rem;
}

.profileSidebar {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.profileCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1.2rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.5rem;
    text-align: center;
}

.profileAvatar {
    width: 80px;
    height: 80px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--primary-blue), #60a5fa);
    color: white;
    font-size: 1.6rem;
    font-weight: 800;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
}

.onlineDot {
    position: absolute;
    bottom: 2px;
    right: 2px;
    width: 12px;
    height: 12px;
    background: #10b981;
    border-radius: 50%;
    border: 2.5px solid white;
}

.profileName {
    font-size: 1rem;
    font-weight: 800;
    color: #0f172a;
}

.profileRole {
    font-size: 0.78rem;
    color: #64748b;
}

.profileLoc {
    font-size: 0.72rem;
    color: #94a3b8;
}

.profileTags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    justify-content: center;
}

.editProfileBtn {
    width: 100%;
    padding: 0.5rem;
    background: #f5f7fa;
    border: 1px solid #eef0f2;
    border-radius: 8px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #374151;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.15s ease;
}

.editProfileBtn:hover {
    background: #eef0f2;
}

.scoreCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
}

.scoreHeader {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    width: 100%;
}

.scoreTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.scoreBadge {
    font-size: 0.58rem;
    font-weight: 700;
    color: var(--primary-blue);
    background: #eff6ff;
    padding: 0.1rem 0.4rem;
    border-radius: 8px;
}

.scoreRing {
    width: 100px;
    height: 100px;
    border-radius: 50%;
    border: 6px solid #eef0f2;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;
    position: relative;
    margin: 0.5rem 0;
}

.scoreRingFill {
    position: absolute;
    inset: -6px;
    border-radius: 50%;
    border: 6px solid var(--primary-blue);
    border-top-color: transparent;
    border-right-color: transparent;
    transform: rotate(45deg);
}

.scoreNum {
    font-size: 1.5rem;
    font-weight: 800;
    color: #0f172a;
}

.scoreSub {
    font-size: 0.6rem;
    font-weight: 600;
    color: var(--primary-blue);
}

.scoreText {
    font-size: 0.68rem;
    color: #94a3b8;
    text-align: center;
}

.openToggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding-top: 0.5rem;
    border-top: 1px solid #f1f5f9;
}

.openLabel {
    font-size: 0.75rem;
    font-weight: 600;
    color: #0f172a;
}

.openHint {
    font-size: 0.62rem;
    color: #94a3b8;
}

.toggleSwitch {
    width: 38px;
    height: 20px;
    background: var(--primary-blue);
    border-radius: 10px;
    position: relative;
    cursor: pointer;
    border: none;
}

.toggleDot {
    position: absolute;
    top: 2px;
    right: 2px;
    width: 16px;
    height: 16px;
    background: white;
    border-radius: 50%;
    transition: all 0.2s ease;
}

.contactCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.contactTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.contactItem {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.contactIcon {
    font-size: 0.85rem;
    flex-shrink: 0;
}

.contactMeta {
    display: flex;
    flex-direction: column;
}

.contactLabel {
    font-size: 0.62rem;
    color: #94a3b8;
}

.contactValue {
    font-size: 0.75rem;
    font-weight: 500;
    color: #0f172a;
}

.contactLink {
    color: var(--primary-blue);
    text-decoration: none;
}

/* Profile main content */
.profileMain {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.profileActions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0.5rem;
}

.profileActionCard {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 10px;
    padding: 0.9rem 1rem;
    display: flex;
    align-items: center;
    justify-content: space-between;
    cursor: pointer;
    transition: all 0.15s ease;
}

.profileActionCard:hover {
    border-color: #e2e8f0;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.03);
}

.profileActionLabel {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.profileActionHint {
    font-size: 0.68rem;
    color: #94a3b8;
}

.profileSection {
    background: #ffffff;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    padding: 1.1rem;
}

.sectionHead {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 0.65rem;
}

.sectionTitle {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
    display: flex;
    align-items: center;
    gap: 0.4rem;
}

.addBtn {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--primary-blue);
    background: none;
    border: none;
    cursor: pointer;
}

.expItem {
    display: flex;
    gap: 0.6rem;
    padding: 0.65rem 0;
    border-bottom: 1px solid #f5f7fa;
}

.expItem:last-child {
    border-bottom: none;
}

.expIcon {
    width: 36px;
    height: 36px;
    border-radius: 8px;
    background: #f1f5f9;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 700;
    color: #475569;
    flex-shrink: 0;
}

.expBody {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 0.1rem;
}

.expTitle {
    font-size: 0.82rem;
    font-weight: 700;
    color: #0f172a;
}

.expCompany {
    font-size: 0.72rem;
    color: #64748b;
}

.expDesc {
    font-size: 0.72rem;
    color: #94a3b8;
    line-height: 1.45;
    margin-top: 0.2rem;
}

.expTags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.2rem;
}

.skillsGrid {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.skillGroup {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.skillGroupTitle {
    font-size: 0.68rem;
    font-weight: 700;
    color: #94a3b8;
    text-transform: uppercase;
    letter-spacing: 0.04em;
}

.skillTags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.3rem;
}

.skillTag {
    font-size: 0.68rem;
    font-weight: 500;
    color: var(--primary-blue);
    background: #eff6ff;
    padding: 0.2rem 0.55rem;
    border-radius: 5px;
}

.toolTag {
    font-size: 0.68rem;
    font-weight: 500;
    color: #475569;
    background: #f5f7fa;
    padding: 0.2rem 0.55rem;
    border-radius: 5px;
    border: 1px solid #eef0f2;
}

/* ── Responsive ── */
@media (max-width: 1024px) {
    .mainGrid {
        grid-template-columns: 1fr;
    }

    .rightCol {
        order: -1;
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.75rem;
    }

    .jobsGrid {
        grid-template-columns: 1fr;
    }

    .kanban {
        grid-template-columns: repeat(2, 1fr);
    }

    .profilePage {
        grid-template-columns: 1fr;
    }

    .profileSidebar {
        display: grid;
        grid-template-columns: 1fr 1fr;
        gap: 0.75rem;
    }
}

@media (max-width: 768px) {
    .stats {
        grid-template-columns: 1fr;
    }

    .rightCol {
        grid-template-columns: 1fr;
    }

    .kanban {
        grid-template-columns: 1fr;
    }

    .profileSidebar {
        grid-template-columns: 1fr;
    }

    .profileActions {
        grid-template-columns: 1fr;
    }

    .matchPoints {
        grid-template-columns: 1fr;
    }

    .searchRow {
        flex-direction: column;
    }
}

/* Profile Edit & Strength Styles */
.avatarImg {
    width: 100%;
    height: 100%;
    border-radius: 50%;
    object-fit: cover;
}

.avatarOverlay {
    position: absolute;
    inset: 0;
    background: rgba(0, 0, 0, 0.3);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    opacity: 0;
    transition: opacity 0.2s ease;
}

.profileAvatar:hover .avatarOverlay {
    opacity: 1;
}

.uploadProgressSmall {
    width: 100%;
    height: 4px;
    background: #eef0f2;
    border-radius: 2px;
    margin-top: 0.5rem;
    overflow: hidden;
}

.uploadProgress {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: #eef0f2;
}

.progressFill {
    height: 100%;
    background: var(--primary-blue);
    transition: width 0.3s ease;
}

.saveBtnFull {
    width: 100%;
    padding: 0.6rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 700;
    cursor: pointer;
    margin-top: 0.5rem;
}

.saveBtnFull:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.ringSvg {
    width: 100px;
    height: 100px;
    transform: rotate(-90deg);
}

.ringBg {
    fill: none;
    stroke: #f1f5f9;
    stroke-width: 8;
}

.ringBar {
    fill: none;
    stroke: var(--primary-blue);
    stroke-width: 8;
    stroke-linecap: round;
    stroke-dasharray: 283;
    transition: stroke-dashoffset 0.5s ease;
}

.strengthMissing {
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    margin: 0.5rem 0;
    width: 100%;
}

.strengthMissing button {
    background: none;
    border: none;
    padding: 0;
    color: #64748b;
    font-size: 0.68rem;
    text-align: left;
    cursor: pointer;
}

.strengthMissing button:hover {
    color: var(--primary-blue);
    text-decoration: underline;
}

.toggleOn {
    background: #10b981 !important;
}

.toggleOn .toggleDot {
    right: 2px;
}

.in {
    border: 1px solid #eef0f2;
    border-radius: 4px;
    padding: 0.2rem 0.4rem;
    font-size: 0.75rem;
    width: 100%;
    outline-color: var(--primary-blue);
}

.editGrid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
    margin-top: 0.5rem;
}

.field {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.field label {
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
}

.field input, .field textarea {
    padding: 0.55rem;
    border: 1px solid #eef0f2;
    border-radius: 8px;
    font-size: 0.82rem;
    outline-color: var(--primary-blue);
}

.fieldFull {
    grid-column: 1 / -1;
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.fieldFull label {
    font-size: 0.72rem;
    font-weight: 600;
    color: #64748b;
}

.fieldFull textarea {
    min-height: 80px;
    resize: vertical;
}

.inputError {
    border-color: #ef4444 !important;
}

.errorText {
    font-size: 0.68rem;
    color: #ef4444;
    margin-top: 0.1rem;
}

.skillsTagEditor {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.skillChip {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    background: #eff6ff;
    color: var(--primary-blue);
    padding: 0.25rem 0.6rem;
    border-radius: 6px;
    font-size: 0.72rem;
    font-weight: 600;
}

.skillChip button {
    background: none;
    border: none;
    color: inherit;
    font-size: 1rem;
    line-height: 0;
    cursor: pointer;
    padding: 0;
}

.tagInput {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    padding: 0.4rem;
    border: 1px solid #eef0f2;
    border-radius: 8px;
    min-height: 42px;
}

.tagInput input {
    border: none !important;
    padding: 0 !important;
    flex: 1;
    min-width: 120px;
}

.loading {
    padding: 2rem;
    text-align: center;
    color: #64748b;
}

.error {
    padding: 2rem;
    text-align: center;
    color: #ef4444;
}

.readRow {
    display: flex;
    gap: 2rem;
    padding: 0.5rem 0;
}

.readItem {
    display: flex;
    flex-direction: column;
}

.readItem strong {
    font-size: 1rem;
    color: #0f172a;
}

.readItem span {
    font-size: 0.72rem;
    color: #64748b;
}

"use client";
import React, { useState } from 'react';
import Link from 'next/link';
import styles from '../candidate.module.css';

/* ─── Icons ─── */
const IC = {
    search: <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#94a3b8" strokeWidth="2"><circle cx="11" cy="11" r="8" /><path d="m21 21-4.3-4.3" /></svg>,
    mapPin: <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" /><circle cx="12" cy="10" r="3" /></svg>,
    dollar: <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><line x1="12" y1="1" x2="12" y2="23" /><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" /></svg>,
    briefcase: <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><rect x="2" y="7" width="20" height="14" rx="2" ry="2" /><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16" /></svg>,
    check: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#10b981" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>,
    alert: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#d97706" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z" /><line x1="12" y1="9" x2="12" y2="13" /><line x1="12" y1="17" x2="12.01" y2="17" /></svg>,
    bookmark: <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z" /></svg>,
    clock: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>,
    cal: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><rect x="3" y="4" width="18" height="18" rx="2" /><line x1="16" y1="2" x2="16" y2="6" /><line x1="8" y1="2" x2="8" y2="6" /><line x1="3" y1="10" x2="21" y2="10" /></svg>,
};

import { getApprovedJobs, type Job } from '@/lib/api/jobs';
import { getMyApplications, checkAlreadyApplied, type ApplicationStatus } from '@/lib/api/applications';
import { useAuth } from '@/lib/auth/AuthContext';
import { formatDistanceToNow } from 'date-fns';

/** ─── Helpers ─── */
const formatSalary = (min: number | null, max: number | null, currency: string = 'INR') => {
    if (!min && !max) return 'Competitive';
    const symbol = currency === 'USD' ? '$' : '₹';
    const kMin = min ? `${(min / 1000).toFixed(0)}K` : '';
    const kMax = max ? `${(max / 1000).toFixed(0)}K` : '';
    if (kMin && kMax) return `${symbol}${kMin}–${symbol}${kMax}`;
    return kMin ? `${symbol}${kMin}+` : `${symbol}${kMax}`;
};

const formatDate = (date: string) => {
    try {
        const d = new Date(date);
        const dist = formatDistanceToNow(d, { addSuffix: true });
        return dist.replace('about ', '').replace('less than a minute ago', 'just now');
    } catch {
        return 'recently';
    }
};

const getInitials = (name: string) => {
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
};

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899'];
const getBrandColor = (id: string) => COLORS[id.charCodeAt(0) % COLORS.length];

export default function JobsPage() {

    const { user } = useAuth();
    const [jobs, setJobs] = useState<Job[]>([]);
    const [appliedIds, setAppliedIds] = useState<Set<string>>(new Set());
    const [loading, setLoading] = useState(true);
    const [loadingMore, setLoadingMore] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [page, setPage] = useState(0);
    const [hasMore, setHasMore] = useState(true);

    const [search, setSearch] = useState('');
    const [type, setType] = useState('');
    const [location, setLocation] = useState('');

    // Fetch user applications to show "Applied" badges
    const fetchAppliedIds = async () => {
        if (!user) return;
        try {
            const apps = await getMyApplications();
            setAppliedIds(new Set(apps.map(a => a.job_id)));
        } catch (err: any) {
            // Silently fail - badge won't show but jobs still load
            // This handles JWT expiry / token errors gracefully
            console.warn('Could not fetch applied IDs (non-critical):', err?.message);
        }
    };

    const fetchJobsList = async (pageNum: number, isNewSearch: boolean = false) => {
        if (pageNum === 0) setLoading(true);
        else setLoadingMore(true);
        setError(null);

        try {
            const results = await getApprovedJobs({
                search: search || undefined,
                type: type || undefined,
                location: location || undefined,
                page: pageNum
            });

            if (isNewSearch) {
                setJobs(results);
            } else {
                setJobs(prev => [...prev, ...results]);
            }

            setHasMore(results.length === 20);
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
            setLoadingMore(false);
        }
    };

    // Initial load
    React.useEffect(() => {
        if (user) {
            fetchAppliedIds();
        }
    }, [user]);

    // Handle filters with debounce for search
    React.useEffect(() => {
        const timer = setTimeout(() => {
            setPage(0);
            fetchJobsList(0, true);
        }, 400);
        return () => clearTimeout(timer);
    }, [search, type, location]);

    const handleLoadMore = () => {
        const next = page + 1;
        setPage(next);
        fetchJobsList(next, false);
    };

    const clearFilters = () => {
        setSearch('');
        setType('');
        setLocation('');
    };

    const typeOptions = ['Full-time', 'Contract', 'Remote', 'Internship'];

    if (error) {
        return (
            <div className={styles.jobsPage}>
                <div style={{ textAlign: 'center', padding: '4rem 2rem' }}>
                    <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>⚠️</div>
                    <h3 style={{ color: '#0f172a', marginBottom: '0.5rem' }}>Failed to load jobs</h3>
                    <p style={{ color: '#64748b', fontSize: '0.9rem', marginBottom: '1.5rem' }}>{error}</p>
                    <button className={styles.applyBtn} onClick={() => fetchJobsList(0, true)}>Try Again</button>
                </div>
            </div>
        );
    }

    return (
        <div className={styles.jobsPage}>
            <div className={styles.searchRow}>
                <div className={styles.searchBarFull}>
                    {IC.search}
                    <input 
                        placeholder="Search job title, keyword, or company" 
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                    />
                </div>
                <div style={{ display: 'flex', gap: '0.5rem', flexWrap: 'wrap' }}>
                    {typeOptions.map(t => (
                        <button 
                            key={t}
                            className={`${styles.filterBtn} ${type === t ? styles.filterBtnActive : ''}`}
                            onClick={() => setType(type === t ? '' : t)}
                        >
                            {t}
                        </button>
                    ))}
                    <input 
                        className={styles.filterBtn}
                        style={{ outline: 'none', width: '140px' }}
                        placeholder="Location..."
                        value={location}
                        onChange={(e) => setLocation(e.target.value)}
                    />
                </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.5rem' }}>
                <h2 style={{ fontSize: '1rem', fontWeight: 800, color: '#0f172a' }}>
                    {loading ? 'Finding jobs...' : `Recommended for You (${jobs.length})`}
                </h2>
                <Link href="/dashboard/candidate/saved" style={{ textDecoration: 'none' }}>
                    <span className={styles.matchBadge} style={{ display: 'flex', alignItems: 'center', gap: '0.3rem', cursor: 'pointer', background: '#f8fafc', color: '#64748b' }}>
                        {IC.bookmark} Saved Jobs
                    </span>
                </Link>
            </div>

            {loading ? (
                <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))', gap: '1rem', marginTop: '0.5rem' }}>
                    {[1, 2, 3, 4, 5, 6].map(i => (
                        <div key={i} className={styles.jobListCard} style={{ height: 200, background: '#f8fafc', border: 'none', opacity: 0.6 }} />
                    ))}
                </div>
            ) : jobs.length === 0 ? (
                <div style={{ textAlign: 'center', padding: '4rem 2rem' }}>
                    <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>🔍</div>
                    <h3 style={{ color: '#0f172a', marginBottom: '0.5rem' }}>No jobs found</h3>
                    <p style={{ color: '#64748b', fontSize: '0.9rem', marginBottom: '1.5rem' }}>Try adjusting your search or filters to find what you're looking for.</p>
                    {(search || type || location) && (
                        <button className={styles.filterBtn} onClick={clearFilters} style={{ margin: '0 auto' }}>Clear All Filters</button>
                    )}
                </div>
            ) : (
                <>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(340px, 1fr))', gap: '1rem', marginTop: '0.5rem' }}>
                        {jobs.map((j) => (
                            <Link key={j.id} href={`/dashboard/candidate/jobs/${j.id}`} style={{ textDecoration: 'none' }}>
                                <div className={styles.jobListCard} style={{ display: 'flex', flexDirection: 'column', height: '100%', padding: '1.2rem', gap: '1rem', borderRadius: 12 }}>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                                        {j.companies?.logo_url ? (
                                            <div style={{ width: 44, height: 44, borderRadius: 10, overflow: 'hidden', border: '1px solid #f1f5f9' }}>
                                                <img src={j.companies.logo_url} alt={j.companies.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                                            </div>
                                        ) : (
                                            <div className={styles.jobListIcon} style={{ background: getBrandColor(j.companies?.name || 'A') + '18', color: getBrandColor(j.companies?.name || 'A'), width: 44, height: 44, fontSize: '1rem' }}>
                                                {getInitials(j.companies?.name || 'Comp')}
                                            </div>
                                        )}
                                        {appliedIds.has(j.id) ? (
                                            <span className={styles.matchBadge} style={{ background: '#f0fdf4', color: '#10b981', display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                                                {IC.check} Applied
                                            </span>
                                        ) : (
                                            <span className={styles.matchBadge} style={{ background: '#eff6ff', color: 'var(--primary-blue)' }}>Apply Now</span>
                                        )}
                                    </div>

                                    <div className={styles.jobListBody}>
                                        <span className={styles.jobListTitle} style={{ fontSize: '1rem' }}>{j.title}</span>
                                        <span className={styles.jobListCompany} style={{ fontSize: '0.8rem', marginTop: 4 }}>
                                            {j.companies?.name} · {j.location}
                                        </span>
                                        <div className={styles.jobListMeta} style={{ marginTop: '0.8rem', gap: '0.5rem' }}>
                                            <span className={styles.jobListTag} style={{ background: '#f0fdf4', color: '#166534', padding: '0.3rem 0.6rem', fontSize: '0.65rem' }}>
                                                {IC.dollar} {formatSalary(j.salary_min, j.salary_max, j.currency)}
                                            </span>
                                            <span className={styles.jobListTag} style={{ background: '#f8fafc', padding: '0.3rem 0.6rem', fontSize: '0.65rem' }}>
                                                {IC.briefcase} {j.type}
                                            </span>
                                        </div>
                                    </div>

                                    <div style={{ marginTop: 'auto', paddingTop: '1rem', borderTop: '1px solid #f1f5f9', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <div style={{ display: 'flex', gap: '0.3rem', flexWrap: 'wrap', alignItems: 'center' }}>
                                            {Array.isArray((j as any).skills_required) && (j as any).skills_required.slice(0, 2).map((s: string) => (
                                                <span key={s} className={styles.jobListTag} style={{ background: 'transparent', border: '1px solid #e2e8f0', padding: '0.15rem 0.4rem' }}>
                                                    {s}
                                                </span>
                                            ))}
                                            <span className={styles.jobTime} style={{ marginLeft: 4, display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                                                {IC.clock} {formatDate(j.created_at)}
                                            </span>
                                        </div>
                                        <span style={{ fontSize: '0.75rem', fontWeight: 600, color: 'var(--primary-blue)', display: 'flex', alignItems: 'center', gap: '0.2rem' }}>
                                            Details <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
                                        </span>
                                    </div>
                                </div>
                            </Link>
                        ))}
                    </div>

                    {hasMore && (
                        <div style={{ display: 'flex', justifyContent: 'center', marginTop: '2rem' }}>
                            <button 
                                className={styles.applyBtn} 
                                onClick={handleLoadMore} 
                                disabled={loadingMore}
                                style={{ background: '#ffffff', color: 'var(--primary-blue)', border: '1.5px solid #e2e8f0', boxShadow: 'none' }}
                            >
                                {loadingMore ? 'Loading...' : 'Load More Jobs'}
                            </button>
                        </div>
                    )}
                </>
            )}
        </div>
    );
}

'use client';
import React, { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import { getJobById, type Job } from '@/lib/api/jobs';
import { checkAlreadyApplied, type ApplicationStatus } from '@/lib/api/applications';
import { useAuth } from '@/lib/auth/AuthContext';
import { insforge } from '@/lib/insforge';
import ApplyModal from '@/components/candidate/ApplyModal';
import styles from '../../../../browse-jobs/[id]/jobDetail.module.css';

// ─── Icons ──────────────────────────────────────────────────────────────────────
const Ico = {
    Location: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20 10c0 6-8 12-8 12s-8-6-8-12a8 8 0 0 1 16 0Z" /><circle cx="12" cy="10" r="3" /></svg>,
    Briefcase: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="2" y="7" width="20" height="14" rx="2" /><path d="M16 7V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v2" /></svg>,
    Sparkle: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="m12 3 1.912 5.885L20 10.8l-5.088 1.912L13 18.6l-1.912-5.888L6 10.8l5.088-1.915Z" /></svg>,
    Heart: ({ filled }: { filled?: boolean }) => <svg width="20" height="20" viewBox="0 0 24 24" fill={filled ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" /></svg>,
    Share: () => <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="18" cy="5" r="3" /><circle cx="6" cy="12" r="3" /><circle cx="18" cy="19" r="3" /><line x1="8.59" y1="13.51" x2="15.42" y2="17.49" /><line x1="15.41" y1="6.51" x2="8.59" y2="10.49" /></svg>,
    Clock: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><polyline points="12 6 12 12 16 14" /></svg>,
    ArrowR: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M5 12h14m-7-7 7 7-7 7" /></svg>,
    Check: () => <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>,
    Star: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z" /></svg>,
    Salary: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="12" y1="1" x2="12" y2="23" /><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6" /></svg>,
    Globe: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="10" /><line x1="2" y1="12" x2="22" y2="12" /><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z" /></svg>,
    Building: () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="4" y="2" width="16" height="20" rx="2" /><line x1="9" y1="6" x2="10" y2="6" /><line x1="14" y1="6" x2="15" y2="6" /><line x1="9" y1="10" x2="10" y2="10" /><line x1="14" y1="10" x2="15" y2="10" /><line x1="9" y1="14" x2="10" y2="14" /><line x1="14" y1="14" x2="15" y2="14" /><line x1="9" y1="18" x2="15" y2="18" /></svg>,
    Award: () => <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="8" r="7" /><polyline points="8.21 13.89 7 23 12 20 17 23 15.79 13.88" /></svg>,
};

const formatSalary = (min: number | null, max: number | null, currency: string = 'INR') => {
    if (!min && !max) return 'Competitive';
    const symbol = currency === 'USD' ? '$' : '₹';
    const kMin = min ? `${(min / 1000).toFixed(0)}K` : '';
    const kMax = max ? `${(max / 1000).toFixed(0)}K` : '';
    if (kMin && kMax) return `${symbol}${kMin}–${symbol}${kMax}`;
    return kMin ? `${symbol}${kMin}+` : `${symbol}${kMax}`;
};

const formatExperience = (min: number | null, max: number | null) => {
    if (min === null && max === null) return 'Not specified';
    if (min !== null && max !== null) return `${min}–${max} years`;
    return min !== null ? `${min}+ years` : `Up to ${max} years`;
};

export default function DashboardJobDetailPage() {
    const params = useParams();
    const router = useRouter();
    const { user } = useAuth();
    const jobId = params.id as string;

    const [job, setJob] = useState<Job | null>(null);
    const [loading, setLoading] = useState(true);
    const [appStatus, setAppStatus] = useState<ApplicationStatus | null>(null);
    const [isSaved, setIsSaved] = useState(false);
    const [isApplyModalOpen, setIsApplyModalOpen] = useState(false);

    const fetchData = async () => {
        try {
            setLoading(true);
            const [jobData, status] = await Promise.all([
                getJobById(jobId),
                checkAlreadyApplied(jobId)
            ]);
            setJob(jobData);
            setAppStatus(status);

            if (user) {
                const { data } = await insforge.database
                    .from('saved_jobs')
                    .select('id')
                    .eq('job_id', jobId)
                    .eq('candidate_id', user.id)
                    .maybeSingle();
                setIsSaved(!!data);
            }
        } catch (err) {
            console.error('Failed to fetch job data:', err);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        if (jobId) fetchData();
    }, [jobId, user]);

    const handleToggleSave = async () => {
        if (!user) return router.push('/login');
        try {
            if (isSaved) {
                await insforge.database.from('saved_jobs').delete().eq('job_id', jobId).eq('candidate_id', user.id);
                setIsSaved(false);
            } else {
                await insforge.database.from('saved_jobs').insert({ job_id: jobId, candidate_id: user.id });
                setIsSaved(true);
            }
        } catch (err) {
            console.error('Save toggle failed:', err);
        }
    };

    if (loading) {
        return <div style={{ padding: '80px 0', textAlign: 'center' }}>Loading job details...</div>;
    }

    if (!job) {
        return (
            <div style={{ padding: '80px 0', textAlign: 'center' }}>
                <h1 style={{ fontSize: '2rem', fontWeight: 800, color: '#0f172a', marginBottom: 12 }}>Job Not Found</h1>
                <p style={{ color: '#64748b', marginBottom: 24 }}>The job you&apos;re looking for doesn&apos;t exist or has been removed.</p>
                <Link href="/dashboard/candidate/jobs" style={{ color: 'var(--primary-blue)', fontWeight: 600, textDecoration: 'underline' }}>← Back to Jobs</Link>
            </div>
        );
    }

    const brandColor = '#3b82f6'; // Fallback blue

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem', marginTop: '-0.5rem' }}>
            {/* Breadcrumb */}
            <nav style={{ fontSize: '0.8rem', color: '#64748b', display: 'flex', gap: '0.4rem', alignItems: 'center' }}>
                <Link href="/dashboard/candidate" style={{ color: '#475569', textDecoration: 'none' }}>Dashboard</Link>
                <span>›</span>
                <Link href="/dashboard/candidate/jobs" style={{ color: '#475569', textDecoration: 'none' }}>Jobs</Link>
                <span>›</span>
                <span style={{ color: '#0f172a', fontWeight: 500 }}>{job.title}</span>
            </nav>

            {/* ── Hero Banner ── */}
            <div style={{
                background: 'linear-gradient(135deg, #f8fafc 0%, #ffffff 100%)',
                border: '1px solid #e2e8f0',
                borderRadius: '16px',
                padding: '2rem',
                position: 'relative',
                overflow: 'hidden',
                boxShadow: '0 4px 12px rgba(0,0,0,0.02)'
            }}>
                <div style={{
                    position: 'absolute', top: 0, right: 0, width: '400px', height: '100%',
                    background: `linear-gradient(90deg, transparent, ${brandColor}10)`,
                    clipPath: 'polygon(20% 0, 100% 0, 100% 100%, 0% 100%)'
                }} />

                <div style={{ display: 'flex', gap: '1.5rem', position: 'relative', zIndex: 2, alignItems: 'center' }}>
                    <div style={{
                        width: '80px', height: '80px', borderRadius: '16px',
                        background: brandColor + '15', color: brandColor,
                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                        fontSize: '2rem', fontWeight: 800, flexShrink: 0,
                        border: `1px solid ${brandColor}30`, overflow: 'hidden'
                    }}>
                        {job.companies?.logo_url ? (
                            <img src={job.companies.logo_url} alt={job.companies.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                        ) : (
                            job.companies?.name[0]
                        )}
                    </div>

                    <div style={{ flex: 1 }}>
                        <h1 style={{ fontSize: '1.75rem', fontWeight: 800, color: '#0f172a', margin: 0, letterSpacing: '-0.02em' }}>{job.title}</h1>
                        <div style={{ display: 'flex', gap: '1.5rem', marginTop: '0.5rem', flexWrap: 'wrap', color: '#475569', fontSize: '0.9rem', fontWeight: 500 }}>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><Ico.Building /> {job.companies?.name}</span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><Ico.Location /> {job.location}</span>
                            <span style={{ display: 'flex', alignItems: 'center', gap: '0.3rem' }}><Ico.Clock /> Posted {new Date(job.created_at).toLocaleDateString()}</span>
                        </div>
                    </div>

                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.75rem', alignItems: 'flex-end' }}>
                        <div style={{ display: 'flex', gap: '0.5rem' }}>
                            <button
                                onClick={handleToggleSave}
                                style={{
                                    background: 'white', border: '1px solid #e2e8f0', borderRadius: '12px',
                                    width: '44px', height: '44px', display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    cursor: 'pointer', color: isSaved ? '#ef4444' : '#94a3b8'
                                }}
                            >
                                <Ico.Heart filled={isSaved} />
                            </button>
                            {appStatus ? (
                                <span className={styles.matchBadge} style={{ background: '#f0fdf4', color: '#10b981', padding: '0.8rem 1.5rem', borderRadius: '12px', fontWeight: 700, display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
                                    <Ico.Check /> {appStatus.charAt(0).toUpperCase() + appStatus.slice(1)}
                                </span>
                            ) : (
                                <button
                                    onClick={() => setIsApplyModalOpen(true)}
                                    style={{
                                        background: 'var(--primary-blue)', color: 'white', border: 'none',
                                        padding: '0.8rem 2rem', borderRadius: '12px', fontSize: '1rem',
                                        fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit',
                                        boxShadow: '0 4px 14px rgba(0, 123, 255, 0.35)',
                                        transition: 'transform 0.2s, box-shadow 0.2s'
                                    }}
                                >
                                    Apply Now
                                </button>
                            )}
                        </div>
                        <span style={{ fontSize: '0.75rem', color: '#64748b', fontWeight: 500 }}>{job.applications_count || 0} people applied</span>
                    </div>
                </div>
            </div>

            {/* ── Body ── */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 340px', gap: '1.5rem' }}>
                {/* Main Content */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                    {/* Description */}
                    <div style={{ background: 'white', border: '1px solid #e2e8f0', borderRadius: '16px', padding: '1.5rem' }}>
                        <h2 style={{ fontSize: '1.2rem', fontWeight: 800, color: '#0f172a', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                            <Ico.Briefcase /> Job Description
                        </h2>
                        <div style={{ color: '#475569', lineHeight: 1.7, fontSize: '0.95rem', whiteSpace: 'pre-wrap' }}>
                            {job.description}
                        </div>
                    </div>

                    {/* Requirements */}
                    {Array.isArray(job.requirements) && job.requirements.length > 0 && (
                        <div style={{ background: 'white', border: '1px solid #e2e8f0', borderRadius: '16px', padding: '1.5rem' }}>
                            <h2 style={{ fontSize: '1.2rem', fontWeight: 800, color: '#0f172a', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                <Ico.Star /> Requirements
                            </h2>
                            <ul style={{ listStyle: 'none', padding: 0, display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                                {job.requirements.map((r, i) => (
                                    <li key={i} style={{ display: 'flex', alignItems: 'flex-start', gap: '0.75rem', color: '#475569', fontSize: '0.95rem', lineHeight: 1.6 }}>
                                        <span style={{ color: 'var(--primary-blue)', marginTop: 2, flexShrink: 0 }}><Ico.Check /></span>
                                        {r}
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )}

                    {/* Skills */}
                    {Array.isArray(job.skills_required) && job.skills_required.length > 0 && (
                        <div style={{ background: 'white', border: '1px solid #e2e8f0', borderRadius: '16px', padding: '1.5rem' }}>
                            <h2 style={{ fontSize: '1.2rem', fontWeight: 800, color: '#0f172a', marginBottom: '1rem', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
                                <Ico.Award /> Skills Required
                            </h2>
                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '0.5rem' }}>
                                {job.skills_required.map((s) => (
                                    <span key={s} style={{ background: '#f1f5f9', color: '#475569', padding: '0.4rem 0.8rem', borderRadius: '8px', fontSize: '0.85rem', fontWeight: 600 }}>
                                        {s}
                                    </span>
                                ))}
                            </div>
                        </div>
                    )}
                </div>

                {/* Sidebar */}
                <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                    {/* Match Panel (Mock Score) */}
                    <div style={{ background: '#f0fdf4', border: '1px solid #bbf7d0', borderRadius: '16px', padding: '1.5rem' }}>
                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                            <h3 style={{ fontSize: '1rem', fontWeight: 800, color: '#166534', margin: 0 }}><Ico.Sparkle /> AI Match Score</h3>
                            <span style={{ fontSize: '1.25rem', fontWeight: 800, color: '#166534' }}>85%</span>
                        </div>
                        <div style={{ width: '100%', height: '8px', background: '#dcfce7', borderRadius: '4px', overflow: 'hidden' }}>
                            <div style={{ width: `85%`, height: '100%', background: '#166534', borderRadius: '4px' }} />
                        </div>
                        <p style={{ fontSize: '0.8rem', color: '#15803d', marginTop: '1rem', lineHeight: 1.5, fontWeight: 500 }}>
