export default function ProfilePage() {
    const { user } = useAuth();
    const [profile, setProfile] = useState<UserProfile | null>(null);
    const [isEditing, setIsEditing] = useState(false);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [uploadProgress, setUploadProgress] = useState<{ [key: string]: number }>({});
    const [errors, setErrors] = useState<{ [key: string]: string }>({});

    const avatarInputRef = useRef<HTMLInputElement>(null);
    const resumeInputRef = useRef<HTMLInputElement>(null);

    useEffect(() => {
        fetchProfile();
    }, []);

    const fetchProfile = async () => {
        try {
            const data = await getMyProfile();
            setProfile(prev => {
                if (!prev || !isEditing) return data;
                // Preserve local changes while updating metadata (like strength/urls)
                return {
                    ...data,
                    name: prev.name,
                    phone: prev.phone,
                    location: prev.location,
                    bio: prev.bio,
                    candidate_profiles: data.candidate_profiles ? {
                        ...data.candidate_profiles,
                        headline: prev.candidate_profiles?.headline || data.candidate_profiles.headline,
                        skills: prev.candidate_profiles?.skills || data.candidate_profiles.skills,
                        experience_years: prev.candidate_profiles?.experience_years ?? data.candidate_profiles.experience_years,
                    } : undefined
                };
            });
        } catch (error) {
            console.error('Failed to fetch profile:', error);
        } finally {
            setIsLoading(false);
        }
    };

    const handleSave = async () => {
        if (!profile) return;
        setIsSaving(true);
        setErrors({});

        // Merge profiles and candidate_profiles for validation
        const validationData = {
            name: profile.name,
            phone: profile.phone,
            location: profile.location,
            bio: profile.bio,
            ...profile.candidate_profiles
        };

        const result = validateCandidateProfile(validationData);
        if (!result.success) {
            setErrors(result.errors || {});
            setIsSaving(false);
            return;
        }

        try {
            // Update profiles
            await updateProfile({
                name: profile.name,
                phone: profile.phone,
                location: profile.location,
                bio: profile.bio,
            });

            // Update candidate_profiles
            if (profile.candidate_profiles) {
                await updateCandidateProfile(profile.candidate_profiles);
            }

            // Refresh data
            await fetchProfile();
            setIsEditing(false);
            alert('Profile updated successfully!');
        } catch (error: any) {
            alert('Failed to save profile: ' + error.message);
        } finally {
            setIsSaving(false);
        }
    };

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>, type: 'avatar' | 'resume') => {
        const file = e.target.files?.[0];
        if (!file || !user) return;

        setUploadProgress(prev => ({ ...prev, [type]: 10 }));

        try {
            let url = '';
            if (type === 'avatar') {
                url = await uploadAvatar(file, user.id);
                setProfile(prev => prev ? { ...prev, avatar_url: url } : null);
                await updateProfile({ avatar_url: url });
            } else {
                url = await uploadResume(file, user.id);
                setProfile(prev => {
                    if (!prev) return null;
                    return {
                        ...prev,
                        candidate_profiles: prev.candidate_profiles ? { ...prev.candidate_profiles, resume_url: url } : undefined
                    };
                });
                await updateCandidateProfile({ resume_url: url });
            }
            setUploadProgress(prev => ({ ...prev, [type]: 100 }));
            await fetchProfile(); // Refresh for strength update
            setTimeout(() => setUploadProgress(prev => ({ ...prev, [type]: 0 })), 2000);
        } catch (error: any) {
            alert(error.message);
            setUploadProgress(prev => ({ ...prev, [type]: 0 }));
        }
    };

    if (isLoading) return <div className={styles.loading}>Loading profile...</div>;
    if (!profile) return <div className={styles.error}>Profile not found.</div>;

    const cp = profile.candidate_profiles;
    const strength = cp?.profile_strength || 0;

    return (
        <div className={styles.profilePage}>
            {/* Left Sidebar */}
            <div className={styles.profileSidebar}>
                <div className={styles.profileCard}>
                    <div
                        className={styles.profileAvatar}
                        style={{ cursor: 'pointer' }}
                        onClick={() => avatarInputRef.current?.click()}
                    >
                        {profile.avatar_url ? (
                            <img src={profile.avatar_url} alt={profile.name} className={styles.avatarImg} />
                        ) : (
                            profile.name.split(' ').map(n => n[0]).join('')
                        )}
                        <div className={styles.avatarOverlay}>{IC.camera}</div>
                        <span className={styles.onlineDot} />
                        <input
                            type="file"
                            ref={avatarInputRef}
                            style={{ display: 'none' }}
                            accept="image/*"
                            onChange={(e) => handleFileUpload(e, 'avatar')}
                        />
                    </div>
                    {uploadProgress.avatar > 0 && uploadProgress.avatar < 100 && (
                        <div className={styles.uploadProgressSmall}>
                            <div className={styles.progressFill} style={{ width: `${uploadProgress.avatar}%` }} />
                        </div>
                    )}
                    <span className={styles.profileName}>{profile.name}</span>
                    <span className={styles.profileRole}>{cp?.headline || 'Add a headline'}</span>
                    <span className={styles.profileLoc}>{IC.mapPin} {profile.location || 'Location not set'}</span>

                    <div className={styles.profileTags}>
                        {cp?.skills?.slice(0, 5).map(skill => (
                            <span key={skill} className={styles.tag}>{skill}</span>
                        ))}
                    </div>

                    <button
                        className={styles.editProfileBtn}
                        onClick={() => setIsEditing(!isEditing)}
                    >
                        {isEditing ? 'Cancel Edit' : <>{IC.edit} Edit Profile</>}
                    </button>
                    {isEditing && (
                        <button
                            className={styles.saveBtnFull}
                            onClick={handleSave}
                            disabled={isSaving}
                        >
                            {isSaving ? 'Saving...' : 'Save All Changes'}
                        </button>
                    )}
                </div>

                <div className={styles.scoreCard}>
                    <div className={styles.scoreHeader}>
                        <span className={styles.scoreTitle}>Profile Strength</span>
                        <span className={styles.scoreBadge}>
                            {strength < 30 ? 'Basic' : strength < 70 ? 'Intermediate' : 'Expert'}
                        </span>
                    </div>
                    <div className={styles.scoreRing}>
                        <svg className={styles.ringSvg} viewBox="0 0 100 100">
                            <circle className={styles.ringBg} cx="50" cy="50" r="45" />
                            <circle
                                className={styles.ringBar}
                                cx="50" cy="50" r="45"
                                style={{ strokeDashoffset: 283 - (283 * strength) / 100 }}
                            />
                        </svg>
                        <span className={styles.scoreNum}>{strength}%</span>
                    </div>
                    <span className={styles.scoreText}>
                        {strength < 100 ? 'Complete your profile to stand out to recruiters.' : 'Your profile is 100% complete!'}
                    </span>

                    <div className={styles.strengthMissing}>
                        {!profile.bio && <button onClick={() => setIsEditing(true)}>• Add a bio</button>}
                        {!cp?.resume_url && <button onClick={() => resumeInputRef.current?.click()}>• Upload resume</button>}
                        {(cp?.skills?.length || 0) < 3 && <button onClick={() => setIsEditing(true)}>• Add more skills</button>}
                    </div>

                    <div className={styles.openToggle}>
                        <div>
                            <span className={styles.openLabel}>Open to Work</span>
                            <span className={styles.openHint}>Visible to recruiters</span>
                        </div>
                        <button
                            className={`${styles.toggleSwitch} ${cp?.is_visible ? styles.toggleOn : ''}`}
                            onClick={async () => {
                                const newVal = !cp?.is_visible;
                                await updateCandidateProfile({ is_visible: newVal });
                                fetchProfile();
                            }}
                        >
                            <span className={styles.toggleDot} />
                        </button>
                    </div>
                </div>

                <div className={styles.contactCard}>
                    <span className={styles.contactTitle}>Contact Information</span>
                    <div className={styles.contactItem}>
                        <span className={styles.contactIcon}>{IC.mail}</span>
                        <div className={styles.contactMeta}>
                            <span className={styles.contactLabel}>Email</span>
                            <span className={styles.contactValue}>{profile.email}</span>
                        </div>
                    </div>
                    <div className={styles.contactItem}>
                        <span className={styles.contactIcon}>{IC.phone}</span>
                        <div className={styles.contactMeta}>
                            <span className={styles.contactLabel}>Phone</span>
                            {isEditing ? (
                                <input
                                    className={styles.in}
                                    value={profile.phone || ''}
                                    onChange={(e) => setProfile({ ...profile, phone: e.target.value })}
                                />
                            ) : (
                                <span className={styles.contactValue}>{profile.phone || 'Not set'}</span>
                            )}
                        </div>
                    </div>
                </div>
            </div>

            {/* Main Content */}
            <div className={styles.profileMain}>
                <div className={styles.profileActions}>
                    <div className={styles.profileActionCard} onClick={() => resumeInputRef.current?.click()}>
                        <div>
                            <div className={styles.profileActionLabel}>{IC.file} Resume</div>
                            <div className={styles.profileActionHint}>
                                {cp?.resume_url ? 'Click to update resume' : 'Not uploaded yet'}
                            </div>
                        </div>
                        {cp?.resume_url && (
                            <a
                                href={cp.resume_url}
                                target="_blank"
                                rel="noreferrer"
                                className={styles.actionIcon}
                                onClick={(e) => e.stopPropagation()}
                            >
                                {IC.extLink}
                            </a>
                        )}
                        <input
                            type="file"
                            ref={resumeInputRef}
                            style={{ display: 'none' }}
                            accept=".pdf"
                            onChange={(e) => handleFileUpload(e, 'resume')}
                        />
                    </div>
                    {uploadProgress.resume > 0 && (
                        <div className={styles.uploadProgress}>
                            <div className={styles.progressFill} style={{ width: `${uploadProgress.resume}%` }} />
                        </div>
                    )}
                </div>

                {/* Personal Info Edit Section */}
                {isEditing && (
                    <div className={styles.profileSection}>
                        <h2 className={styles.sectionTitle}>Personal Details</h2>
                        <div className={styles.editGrid}>
                            <div className={styles.field}>
                                <label>Display Name</label>
                                <input
                                    value={profile.name}
                                    onChange={(e) => setProfile({ ...profile, name: e.target.value })}
                                    className={errors.name ? styles.inputError : ''}
                                />
                                {errors.name && <span className={styles.errorText}>{errors.name}</span>}
                            </div>
                            <div className={styles.field}>
                                <label>Headline</label>
                                <input
                                    value={cp?.headline || ''}
                                    onChange={(e) => setProfile({ ...profile, candidate_profiles: { ...cp!, headline: e.target.value } })}
                                    placeholder="e.g. Senior Product Designer"
                                />
                            </div>
                            <div className={styles.field}>
                                <label>Location</label>
                                <input
                                    value={profile.location || ''}
                                    onChange={(e) => setProfile({ ...profile, location: e.target.value })}
                                    placeholder="e.g. London, UK"
                                />
                            </div>
                            <div className={styles.fieldFull}>
                                <label>Bio</label>
                                <textarea
                                    value={profile.bio || ''}
                                    onChange={(e) => setProfile({ ...profile, bio: e.target.value })}
                                    placeholder="Tell recruiters about yourself..."
                                />
                            </div>
                        </div>
                    </div>
                )}

                {/* Professional Info */}
                <div className={styles.profileSection}>
                    <div className={styles.sectionHead}>
                        <h2 className={styles.sectionTitle}>{IC.briefcase} Professional Info</h2>
                    </div>
                    {isEditing ? (
                        <div className={styles.editGrid}>
                            <div className={styles.field}>
                                <label>Years of Experience</label>
                                <input
                                    type="number"
                                    value={cp?.experience_years || 0}
                                    onChange={(e) => setProfile({ ...profile, candidate_profiles: { ...cp!, experience_years: parseInt(e.target.value) } })}
                                />
                            </div>
                        </div>
                    ) : (
                        <div className={styles.readRow}>
                            <div className={styles.readItem}>
                                <strong>{cp?.experience_years || 0}</strong>
                                <span>Years Experience</span>
                            </div>
                        </div>
                    )}
                </div>

                {/* Skills Section */}
                <div className={styles.profileSection}>
                    <div className={styles.sectionHead}>
                        <h2 className={styles.sectionTitle}>{IC.target} Skills</h2>
                    </div>
                    <div className={styles.skillsTagEditor}>
                        {cp?.skills?.map(skill => (
                            <span key={skill} className={styles.skillChip}>
                                {skill}
                                {isEditing && (
                                    <button onClick={() => {
                                        const newSkills = cp.skills?.filter(s => s !== skill);
                                        setProfile({ ...profile, candidate_profiles: { ...cp, skills: newSkills } });
                                    }}>×</button>
                                )}
                            </span>
                        ))}
                        {isEditing && (
                            <input
                                placeholder="Add a skill + press Enter"
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        const input = e.target as HTMLInputElement;
                                        const val = input.value.trim();
                                        if (val && !cp?.skills?.includes(val)) {
                                            const newSkills = [...(cp?.skills || []), val];
                                            setProfile({ ...profile, candidate_profiles: { ...cp!, skills: newSkills } });
                                            input.value = '';
                                        }
                                    }
                                }}
                            />
                        )}
                    </div>
                </div>

                {/* Job Preferences */}
                <div className={styles.profileSection}>
                    <h2 className={styles.sectionTitle}>Job Preferences</h2>
                    <div className={styles.editGrid}>
                        <div className={styles.fieldFull}>
                            <label>Preferred Locations</label>
                            <div className={styles.tagInput}>
                                {cp?.preferred_locations?.map(loc => (
                                    <span key={loc} className={styles.skillChip}>
                                        {loc}
                                        {isEditing && <button onClick={() => {
                                            const newLocs = cp.preferred_locations?.filter(l => l !== loc);
                                            setProfile({ ...profile, candidate_profiles: { ...cp, preferred_locations: newLocs } });
                                        }}>×</button>}
                                    </span>
                                ))}
                                {isEditing && <input onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        const i = e.target as HTMLInputElement;
                                        const v = i.value.trim();
                                        if (v) {
                                            const n = [...(cp?.preferred_locations || []), v];
                                            setProfile({ ...profile, candidate_profiles: { ...cp!, preferred_locations: n } });
                                            i.value = '';
                                        }
                                    }
                                }} />}
                            </div>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useEffect, useMemo, useState } from 'react';

import type { CandidateSettingsBundle } from '@/lib/candidate-profile';

import styles from '../candidate.module.css';

type ToggleItem = {
    label: string;
    desc: string;
    on: boolean;
};

const EMPTY_STATE: CandidateSettingsBundle = {
    profile: {
        id: '',
        email: '',
        name: '',
        phone: '',
        location: '',
        role_id: null,
    },
    candidateProfile: {
        headline: '',
        skills: [],
        experience_years: null,
        education: '',
        resume_url: '',
        salary_min: null,
        salary_max: null,
        preferred_locations: [],
        job_type: '',
        profile_strength: 0,
    },
};

const INITIAL_NOTIFICATIONS: ToggleItem[] = [
    { label: 'Job Recommendations', desc: 'Get notified about jobs matching your profile', on: true },
    { label: 'Application Updates', desc: 'Status changes on your applications', on: true },
    { label: 'Messages', desc: 'New messages from recruiters', on: true },
    { label: 'Weekly Digest', desc: 'Summary of new opportunities every week', on: false },
    { label: 'Marketing Emails', desc: 'Product updates and tips', on: false },
];

const INITIAL_PRIVACY: ToggleItem[] = [
    { label: 'Profile Visibility', desc: 'Make your profile visible to recruiters', on: true },
    { label: 'Show Match Score', desc: 'Allow companies to see your AI match score', on: true },
    { label: 'Resume Download', desc: 'Let recruiters download your resume', on: false },
];

function formatSalaryRange(min: number | null, max: number | null): string {
    const formatter = new Intl.NumberFormat('en-US', {
        style: 'currency',
        currency: 'USD',
        maximumFractionDigits: 0,
    });

    if (min && max) {
        return `${formatter.format(min)} - ${formatter.format(max)}`;
    }

    if (min) {
        return formatter.format(min);
    }

    if (max) {
        return formatter.format(max);
    }

    return '';
}

function parseSalaryRange(value: string): { salary_min: number | null; salary_max: number | null } {
    const matches = value.match(/\d[\d,]*/g) ?? [];
    const numbers = matches.map((item) => Number(item.replace(/,/g, ''))).filter((item) => Number.isFinite(item));

    return {
        salary_min: numbers[0] ?? null,
        salary_max: numbers[1] ?? null,
    };
}

function splitCommaList(value: string): string[] {
    return value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean);
}

export default function CandidateSettingsPage() {
    const [form, setForm] = useState<CandidateSettingsBundle>(EMPTY_STATE);
    const [expectedSalary, setExpectedSalary] = useState('');
    const [preferredLocationsInput, setPreferredLocationsInput] = useState('');
    const [security, setSecurity] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: '',
    });
    const [notifications, setNotifications] = useState(INITIAL_NOTIFICATIONS);
    const [privacy, setPrivacy] = useState(INITIAL_PRIVACY);
    const [isLoading, setIsLoading] = useState(true);
    const [isSavingProfile, setIsSavingProfile] = useState(false);
    const [isSavingPreferences, setIsSavingPreferences] = useState(false);
    const [message, setMessage] = useState('');
    const [error, setError] = useState('');

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await fetch('/api/candidate-profile', { cache: 'no-store' });
                const payload = await response.json();

                if (!response.ok) {
                    throw new Error(payload.error || 'Failed to load settings');
                }

                setForm(payload);
                setExpectedSalary(formatSalaryRange(payload.candidateProfile.salary_min, payload.candidateProfile.salary_max));
                setPreferredLocationsInput(payload.candidateProfile.preferred_locations.join(', '));
            } catch (err) {
                const messageText = err instanceof Error ? err.message : 'Failed to load settings';
                setError(messageText);
            } finally {
                setIsLoading(false);
            }
        };

        fetchData();
    }, []);

    const save = async (nextForm: CandidateSettingsBundle, mode: 'profile' | 'preferences') => {
        setError('');
        setMessage('');

        if (mode === 'profile') {
            setIsSavingProfile(true);
        } else {
            setIsSavingPreferences(true);
        }

        try {
            const response = await fetch('/api/candidate-profile', {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(nextForm),
            });

            const payload = await response.json();
            if (!response.ok) {
                throw new Error(payload.error || 'Failed to save settings');
            }

            setForm(payload);
            setExpectedSalary(formatSalaryRange(payload.candidateProfile.salary_min, payload.candidateProfile.salary_max));
            setPreferredLocationsInput(payload.candidateProfile.preferred_locations.join(', '));
            setMessage(mode === 'profile' ? 'Profile information updated.' : 'Job preferences updated.');
        } catch (err) {
            const messageText = err instanceof Error ? err.message : 'Failed to save settings';
            setError(messageText);
        } finally {
            if (mode === 'profile') {
                setIsSavingProfile(false);
            } else {
                setIsSavingPreferences(false);
            }
        }
    };

    const profileCompletion = useMemo(() => `${form.candidateProfile.profile_strength}% complete`, [form.candidateProfile.profile_strength]);

    if (isLoading) {
        return <div className={styles.loading}>Loading settings...</div>;
    }

    return (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
            <div>
                <h1 style={{ fontSize: '1.25rem', fontWeight: 800, color: '#0f172a' }}>Settings</h1>
                <p style={{ fontSize: '0.8rem', color: '#94a3b8', marginTop: 2 }}>
                    Manage your account, preferences, and privacy. Profile strength: {profileCompletion}
                </p>
            </div>

            {(message || error) && (
                <div
                    style={{
                        padding: '0.75rem 0.9rem',
                        borderRadius: 12,
                        border: `1px solid ${error ? '#fecaca' : '#bfdbfe'}`,
                        background: error ? '#fef2f2' : '#eff6ff',
                        color: error ? '#b91c1c' : '#1d4ed8',
                        fontSize: '0.8rem',
                        fontWeight: 600,
                    }}
                >
                    {error || message}
                </div>
            )}

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem' }}>
                <div style={{ background: '#fff', border: '1px solid #eef0f2', borderRadius: 14, padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#0f172a', margin: 0 }}>Profile Information</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Full Name</label>
                            <input value={form.profile.name} onChange={(event) => setForm((prev) => ({ ...prev, profile: { ...prev.profile, name: event.target.value } }))} style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Email</label>
                            <input value={form.profile.email} readOnly style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none', background: '#f8fafc', color: '#64748b' }} />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Phone</label>
                            <input value={form.profile.phone} onChange={(event) => setForm((prev) => ({ ...prev, profile: { ...prev.profile, phone: event.target.value } }))} style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Location</label>
                            <input value={form.profile.location} onChange={(event) => setForm((prev) => ({ ...prev, profile: { ...prev.profile, location: event.target.value } }))} style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                    </div>
                    <button onClick={() => save(form, 'profile')} disabled={isSavingProfile} style={{ alignSelf: 'flex-start', padding: '0.5rem 1.2rem', background: 'linear-gradient(135deg, var(--primary-blue), #2563eb)', color: 'white', border: 'none', borderRadius: 10, fontSize: '0.82rem', fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit', boxShadow: '0 3px 10px rgba(37,99,235,0.25)', opacity: isSavingProfile ? 0.7 : 1 }}>
                        {isSavingProfile ? 'Saving...' : 'Save Changes'}
                    </button>
                </div>

                <div style={{ background: '#fff', border: '1px solid #eef0f2', borderRadius: 14, padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#0f172a', margin: 0 }}>Job Preferences</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Desired Role</label>
                            <input value={form.candidateProfile.headline} onChange={(event) => setForm((prev) => ({ ...prev, candidateProfile: { ...prev.candidateProfile, headline: event.target.value } }))} style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Expected Salary</label>
                            <input
                                value={expectedSalary}
                                onChange={(event) => {
                                    setExpectedSalary(event.target.value);
                                    const parsed = parseSalaryRange(event.target.value);
                                    setForm((prev) => ({
                                        ...prev,
                                        candidateProfile: {
                                            ...prev.candidateProfile,
                                            salary_min: parsed.salary_min,
                                            salary_max: parsed.salary_max,
                                        },
                                    }));
                                }}
                                style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }}
                            />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Work Type</label>
                            <select value={form.candidateProfile.job_type} onChange={(event) => setForm((prev) => ({ ...prev, candidateProfile: { ...prev.candidateProfile, job_type: event.target.value } }))} style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }}>
                                <option value="">Select</option>
                                <option value="Remote">Remote</option>
                                <option value="Onsite">Onsite</option>
                                <option value="Hybrid">Hybrid</option>
                            </select>
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Preferred Locations</label>
                            <input
                                value={preferredLocationsInput}
                                onChange={(event) => {
                                    setPreferredLocationsInput(event.target.value);
                                    setForm((prev) => ({
                                        ...prev,
                                        candidateProfile: {
                                            ...prev.candidateProfile,
                                            preferred_locations: splitCommaList(event.target.value),
                                        },
                                    }));
                                }}
                                style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }}
                            />
                        </div>
                    </div>
                    <button onClick={() => save(form, 'preferences')} disabled={isSavingPreferences} style={{ alignSelf: 'flex-start', padding: '0.5rem 1.2rem', background: 'linear-gradient(135deg, var(--primary-blue), #2563eb)', color: 'white', border: 'none', borderRadius: 10, fontSize: '0.82rem', fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit', boxShadow: '0 3px 10px rgba(37,99,235,0.25)', opacity: isSavingPreferences ? 0.7 : 1 }}>
                        {isSavingPreferences ? 'Saving...' : 'Update Preferences'}
                    </button>
                </div>

                <div style={{ background: '#fff', border: '1px solid #eef0f2', borderRadius: 14, padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#0f172a', margin: 0 }}>Notifications</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        {notifications.map((item, index) => (
                            <div key={item.label} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0.4rem 0', borderBottom: index < notifications.length - 1 ? '1px solid #f1f5f9' : 'none' }}>
                                <div>
                                    <div style={{ fontSize: '0.85rem', fontWeight: 600, color: '#0f172a' }}>{item.label}</div>
                                    <div style={{ fontSize: '0.7rem', color: '#94a3b8' }}>{item.desc}</div>
                                </div>
                                <button type="button" onClick={() => setNotifications((prev) => prev.map((entry, entryIndex) => entryIndex === index ? { ...entry, on: !entry.on } : entry))} style={{ width: 44, height: 24, borderRadius: 12, cursor: 'pointer', background: item.on ? 'var(--primary-blue)' : '#e2e8f0', position: 'relative', transition: 'all 0.2s', border: 'none' }}>
                                    <div style={{ width: 18, height: 18, borderRadius: '50%', background: 'white', position: 'absolute', top: 3, left: item.on ? 23 : 3, transition: 'all 0.2s', boxShadow: '0 1px 3px rgba(0,0,0,0.15)' }} />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>

                <div style={{ background: '#fff', border: '1px solid #eef0f2', borderRadius: 14, padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#0f172a', margin: 0 }}>Security</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Current Password</label>
                            <input type="password" value={security.currentPassword} onChange={(event) => setSecurity((prev) => ({ ...prev, currentPassword: event.target.value }))} placeholder="••••••••" style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>New Password</label>
                            <input type="password" value={security.newPassword} onChange={(event) => setSecurity((prev) => ({ ...prev, newPassword: event.target.value }))} placeholder="••••••••" style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.25rem' }}>
                            <label style={{ fontSize: '0.75rem', fontWeight: 600, color: '#475569' }}>Confirm Password</label>
                            <input type="password" value={security.confirmPassword} onChange={(event) => setSecurity((prev) => ({ ...prev, confirmPassword: event.target.value }))} placeholder="••••••••" style={{ padding: '0.5rem 0.75rem', border: '1px solid #e2e8f0', borderRadius: 8, fontSize: '0.85rem', fontFamily: 'inherit', outline: 'none' }} />
                        </div>
                    </div>
                    <button type="button" onClick={() => setMessage('Password update UI is ready, but auth password syncing is not wired in this change set.')} style={{ alignSelf: 'flex-start', padding: '0.5rem 1.2rem', background: 'linear-gradient(135deg, var(--primary-blue), #2563eb)', color: 'white', border: 'none', borderRadius: 10, fontSize: '0.82rem', fontWeight: 700, cursor: 'pointer', fontFamily: 'inherit', boxShadow: '0 3px 10px rgba(37,99,235,0.25)' }}>
                        Update Password
                    </button>
                </div>

                <div style={{ background: '#fff', border: '1px solid #eef0f2', borderRadius: 14, padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#0f172a', margin: 0 }}>Privacy</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        {privacy.map((item, index) => (
                            <div key={item.label} style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0.4rem 0', borderBottom: index < privacy.length - 1 ? '1px solid #f1f5f9' : 'none' }}>
                                <div>
                                    <div style={{ fontSize: '0.85rem', fontWeight: 600, color: '#0f172a' }}>{item.label}</div>
                                    <div style={{ fontSize: '0.7rem', color: '#94a3b8' }}>{item.desc}</div>
                                </div>
                                <button type="button" onClick={() => setPrivacy((prev) => prev.map((entry, entryIndex) => entryIndex === index ? { ...entry, on: !entry.on } : entry))} style={{ width: 44, height: 24, borderRadius: 12, cursor: 'pointer', background: item.on ? 'var(--primary-blue)' : '#e2e8f0', position: 'relative', transition: 'all 0.2s', border: 'none' }}>
                                    <div style={{ width: 18, height: 18, borderRadius: '50%', background: 'white', position: 'absolute', top: 3, left: item.on ? 23 : 3, transition: 'all 0.2s', boxShadow: '0 1px 3px rgba(0,0,0,0.15)' }} />
                                </button>
                            </div>
                        ))}
                    </div>
                </div>

                <div style={{ background: '#fff', border: '1px solid #fecaca', borderRadius: 14, padding: '1.25rem', display: 'flex', flexDirection: 'column', gap: '0.75rem' }}>
                    <h3 style={{ fontSize: '0.95rem', fontWeight: 700, color: '#dc2626', margin: 0 }}>Danger Zone</h3>
                    <div style={{ display: 'flex', flexDirection: 'column', gap: '0.6rem' }}>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                            <div>
                                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: '#0f172a' }}>Deactivate Account</div>
                                <div style={{ fontSize: '0.7rem', color: '#94a3b8' }}>Temporarily hide your profile from recruiters</div>
                            </div>
                            <button style={{ padding: '0.4rem 0.8rem', background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 8, fontSize: '0.78rem', fontWeight: 600, color: '#dc2626', cursor: 'pointer', fontFamily: 'inherit' }}>Deactivate</button>
                        </div>
                        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                            <div>
                                <div style={{ fontSize: '0.85rem', fontWeight: 600, color: '#0f172a' }}>Delete Account</div>
                                <div style={{ fontSize: '0.7rem', color: '#94a3b8' }}>Permanently delete your account and all data</div>
                            </div>
                            <button style={{ padding: '0.4rem 0.8rem', background: '#dc2626', border: 'none', borderRadius: 8, fontSize: '0.78rem', fontWeight: 600, color: 'white', cursor: 'pointer', fontFamily: 'inherit' }}>Delete</button>
                        </div>
                    </div>
                </div>
            </div>
        </div>
    );
}

/* ============================
   DASHBOARD LAYOUT — Premium
   ============================ */

.shell {
    display: flex;
    min-height: 100vh;
    background: #f8fafc;
    font-family: var(--font-inter), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

/* ── Sidebar ── */
.sidebar {
    width: 248px;
    background: #ffffff;
    border-right: 1px solid #e8ecf0;
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    position: sticky;
    top: 0;
    height: 100vh;
    overflow-y: auto;
    z-index: 50;
    transition: width 0.28s cubic-bezier(0.4, 0, 0.2, 1);
}

.sidebarCollapsed {
    width: 68px;
}

.sidebarHead {
    padding: 1.15rem 1rem;
    border-bottom: 1px solid #f0f2f5;
}

.brand {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    text-decoration: none;
}

.brandIcon {
    width: 34px;
    height: 34px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.brandName {
    font-size: 0.98rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    white-space: nowrap;
}

.brandTag {
    font-size: 0.52rem;
    font-weight: 700;
    color: var(--primary-blue);
    background: #eff6ff;
    padding: 1px 6px;
    border-radius: 4px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

/* Nav */
.nav {
    flex: 1;
    display: flex;
    flex-direction: column;
    gap: 2px;
    padding: 0.85rem 0.6rem;
}

.navLink {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    padding: 0.58rem 0.75rem;
    border-radius: 10px;
    text-decoration: none;
    color: #64748b;
    font-size: 0.82rem;
    font-weight: 500;
    transition: all 0.18s ease;
    position: relative;
    white-space: nowrap;
}

.navLink:hover {
    background: transparent;
    color: #334155;
}

.navLink:hover .navIcon {
    color: var(--primary-blue);
    filter: drop-shadow(0 0 6px rgba(0, 123, 255, 0.5));
}

.navLinkActive {
    background: transparent;
    color: var(--primary-blue);
    font-weight: 600;
}

.navLinkActive .navIcon {
    color: var(--primary-blue);
    filter: drop-shadow(0 0 8px rgba(0, 123, 255, 0.6));
}

.navIcon {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    flex-shrink: 0;
    transition: filter 0.2s ease, color 0.2s ease;
}

.navLabel {
    flex: 1;
    overflow: hidden;
}

.navBadge {
    font-size: 0.6rem;
    font-weight: 700;
    background: var(--primary-blue);
    color: white;
    border-radius: 10px;
    padding: 0.1rem 0.45rem;
    min-width: 19px;
    text-align: center;
    line-height: 1.3;
}

.navBadgeDot {
    position: absolute;
    top: 8px;
    right: 8px;
    width: 7px;
    height: 7px;
    background: #ef4444;
    border-radius: 50%;
}

/* Sidebar bottom */
.sidebarFoot {
    padding: 0.6rem;
    border-top: 1px solid #f0f2f5;
    margin-top: auto;
}

.userCard {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.6rem 0.7rem;
    border-radius: 10px;
    margin-top: 0.25rem;
    transition: background 0.15s ease;
    cursor: pointer;
}

.userCard:hover {
    background: #f8fafc;
}

.userAvatar {
    width: 34px;
    height: 34px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--primary-blue), #60a5fa);
    color: white;
    font-size: 0.62rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.userMeta {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
    overflow: hidden;
}

.userName {
    font-size: 0.76rem;
    font-weight: 700;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.userEmail {
    font-size: 0.62rem;
    color: #94a3b8;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

/* Overlay */
.overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0.2);
    backdrop-filter: blur(2px);
    z-index: 40;
}

/* ── Main area ── */
.main {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-width: 0;
}

.topbar {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.7rem 1.5rem;
    background: #ffffff;
    border-bottom: 1px solid #e8ecf0;
    position: sticky;
    top: 0;
    z-index: 30;
    min-height: 54px;
}

.hamburger {
    background: none;
    border: none;
    color: #475569;
    cursor: pointer;
    padding: 6px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    transition: all 0.15s ease;
}

.hamburger:hover {
    background: #f1f5f9;
    color: #0f172a;
}

.pageTitle {
    font-size: 0.98rem;
    font-weight: 700;
    color: #0f172a;
    margin: 0;
    letter-spacing: -0.01em;
}

.topRight {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    margin-left: auto;
}

.searchBox {
    display: flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.42rem 0.7rem;
    background: #f8fafc;
    border: 1px solid #e8ecf0;
    border-radius: 10px;
    color: #94a3b8;
    transition: all 0.2s ease;
    max-width: 250px;
}

.searchBox:focus-within {
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
    background: #ffffff;
}

.searchInput {
    border: none;
    background: transparent;
    outline: none;
    font-size: 0.78rem;
    color: #0f172a;
    font-family: inherit;
    width: 170px;
}

.searchInput::placeholder {
    color: #b0b8c4;
}

.notifBtn {
    position: relative;
    background: none;
    border: 1px solid #e8ecf0;
    border-radius: 10px;
    padding: 0.42rem;
    color: #64748b;
    cursor: pointer;
    display: flex;
    align-items: center;
    transition: all 0.15s ease;
}

.notifBtn:hover {
    background: #f8fafc;
    color: #1e293b;
    border-color: #d1d5db;
}

.notifDot {
    position: absolute;
    top: 5px;
    right: 5px;
    width: 7px;
    height: 7px;
    background: #ef4444;
    border-radius: 50%;
    border: 1.5px solid white;
}

.topAvatar {
    width: 32px;
    height: 32px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--primary-blue), #60a5fa);
    color: white;
    font-size: 0.62rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.15s ease;
}

.topAvatar:hover {
    transform: scale(1.05);
}

.content {
    flex: 1;
    padding: 1.5rem;
    overflow-y: auto;
}

/* ── Responsive ── */
@media (max-width: 768px) {
    .sidebar {
        position: fixed;
        left: -260px;
        top: 0;
        width: 248px;
        box-shadow: none;
        transition: left 0.3s ease;
    }

    .sidebarCollapsed {
        width: 248px;
        left: -260px;
    }

    .sidebarMobileOpen {
        left: 0;
        box-shadow: 4px 0 24px rgba(0, 0, 0, 0.1);
    }

    .overlay {
        display: block;
    }

    .searchBox {
        display: none;
    }

    .content {
        padding: 1rem;
    }

    .pageTitle {
        font-size: 0.9rem;
    }

    .topbar {
        padding: 0.6rem 1rem;
    }
}

@media (max-width: 480px) {
    .topbar {
        padding: 0.5rem 0.75rem;
    }

    .content {
        padding: 0.75rem;
    }
}

/* ── Admin Theme Enhancements ── */
.adminAccent {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: #f59e0b;
    z-index: 100;
}

.adminBadge {
    font-size: 0.55rem;
    font-weight: 800;
    background: #f59e0b;
    color: white;
    padding: 2px 6px;
    border-radius: 4px;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    display: inline-flex;
    align-items: center;
    box-shadow: 0 2px 5px rgba(245, 158, 11, 0.25);
    vertical-align: middle;
}

.adminAvatar {
    background: linear-gradient(135deg, #f59e0b, #fbbf24) !important;
    border: 1px solid rgba(245, 158, 11, 0.2) !important;
}

.topSignOut {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 0.45rem 0.85rem;
    border-radius: 8px;
    background: #fff;
    border: 1px solid #e8ecf0;
    color: #64748b;
    font-size: 0.74rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.topSignOut:hover:not(:disabled) {
    background: #f1f5f9;
    color: #0f172a;
    border-color: #cbd5e1;
}

.topSignOutAdmin:hover:not(:disabled) {
    background: rgba(245, 158, 11, 0.08);
    color: #92400e;
    border-color: rgba(245, 158, 11, 0.3);
}

.topSignOut:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.adminMiniCard {
    background: rgba(245, 158, 11, 0.06);
    border: 1px solid rgba(245, 158, 11, 0.15);
    border-radius: 12px;
    padding: 10px;
    margin-top: 12px;
}

.adminMiniCardInner {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 8px;
}

.adminSignOutBtn {
    width: 100%;
    padding: 6px;
    border-radius: 6px;
    border: none;
    background: rgba(245, 158, 11, 0.1);
    color: #92400e;
    font-size: 0.7rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s ease;
}

.adminSignOutBtn:hover {
    background: #f59e0b;
    color: white;
}

.lockIcon {
    color: #f59e0b;
    margin-left: auto;
}

.adminPortalHeader {
    display: flex;
    align-items: center;
    gap: 8px;
    color: #f59e0b;
    font-weight: 700;
    font-size: 0.85rem;
}

.spinnerSmall {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(0, 0, 0, 0.1);
    border-top-color: currentColor;
    border-radius: 50%;
    animation: spin 0.8s linear infinite;
}

@keyframes spin {
    to { transform: rotate(360deg); }
}

"use client";
import React, { useState, useCallback } from 'react';
import Link from 'next/link';
import Image from 'next/image';
import { usePathname, useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import styles from './dashboard-layout.module.css';

/* ─── SVG Icon Components ─── */
const Icons = {
