"use client";
import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import styles from '../recruiter.module.css';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';

const IC = {
    plus: <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" /></svg>,
    mapPin: <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" /><circle cx="12" cy="10" r="3" /></svg>,
};

export default function RecruiterJobsPage() {
    const { user } = useAuth();
    const [jobs, setJobs] = useState<any[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function fetchJobs() {
            if (!user?.company_id) {
                setLoading(false);
                return;
            }
            try {
                const { data } = await insforge.database
                    .from('jobs')
                    .select('*, applications(count)')
                    .eq('company_id', user.company_id);

                setJobs(data || []);
            } catch (err) {
                console.error(err);
            } finally {
                setLoading(false);
            }
        }
        fetchJobs();
    }, [user]);

    if (loading) return <div className={styles.loading}>Loading your postings...</div>;

    return (
        <div className={styles.jobsPage}>
            <div className={styles.pageHead}>
                <h1 className={styles.pageTitle}>Job Postings</h1>
                <Link href="/dashboard/recruiter/jobs/post-job" className={styles.createBtn}>
                    {IC.plus} Post a New Job
                </Link>
            </div>
            {jobs.length === 0 ? (
                <div className={styles.emptyState}>
                    <p>You haven't posted any jobs yet.</p>
                </div>
            ) : (
                jobs.map((j, i) => (
                    <div key={i} className={styles.jobPostCard}>
                        <div className={styles.jobPostBody}>
                            <span className={styles.jobPostTitle}>{j.title}</span>
                            <span className={styles.jobPostMeta}>{IC.mapPin} {j.location || 'Remote'} · Posted {new Date(j.created_at).toLocaleDateString()}</span>
                            <div className={styles.jobPostStats}>
                                <span className={styles.jobPostStat}>{(j.applications?.[0]?.count || 0)} applicants</span>
                                <span className={styles.jobPostStat}>0 new</span>
                                <span className={styles.jobPostStat} style={{ color: j.status === 'active' ? '#10b981' : '#f59e0b' }}>● {j.status || 'Active'}</span>
                            </div>
                        </div>
                        <div className={styles.jobPostActions}>
                            <button className={styles.editBtn}>Edit</button>
                            <button className={styles.editBtn}>View Applicants</button>
                        </div>
                    </div>
                ))
            )}
        </div>
    );
}

"use client";
import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import styles from '../../recruiter.module.css';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';

export default function PostJobPage() {
    const router = useRouter();
    const { user } = useAuth();
    const [isLoading, setIsLoading] = useState(false);
    const [formData, setFormData] = useState({
        title: '',
        location: '',
        type: 'Full-time',
        salary: '',
        industry: '',
        description: '',
        requirements: '',
        responsibilities: ''
    });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if (!user?.company_id) {
            alert('Please complete your company profile onboarding first.');
            return;
        }
        setIsLoading(true);

        try {
            const { error } = await insforge.database
                .from('jobs')
                .insert([{
                    title: formData.title,
                    location: formData.location,
                    type: formData.type,
                    salary: formData.salary,
                    industry: formData.industry,
                    description: formData.description,
                    requirements: formData.requirements.split('\n').filter((r: string) => r.trim()),
                    responsibilities: formData.responsibilities.split('\n').filter((r: string) => r.trim()),
                    company_id: user.company_id,
                    logo: 'https://logo.clearbit.com/talentmesh.ai', 
                    color: '#0D47A1',
                    status: 'active'
                }]);

            if (error) throw error;

            // Log activity
            await insforge.database.from('activity').insert([{
                user_id: user.id || '',
                description: `Posted a new job: ${formData.title}`,
                type: 'job_post'
            }]);

            router.push('/dashboard/recruiter/jobs');
        } catch (err) {
            console.error(err);
            alert('Failed to post job');
        } finally {
            setIsLoading(false);
        }
    };

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>) => {
        setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    return (
        <div className={styles.postJobPage}>
            <div className={styles.pageHead}>
                <h1 className={styles.pageTitle}>Post a New Job</h1>
                <p className={styles.pageSub}>Reach the best talent with TalentMesh AI matching.</p>
            </div>

            <form onSubmit={handleSubmit} className={styles.jobForm}>
                <div className={styles.formGrid}>
                    <div className={styles.formGroup}>
                        <label>Job Title</label>
                        <input name="title" value={formData.title} onChange={handleChange} placeholder="e.g. Senior Product Designer" required />
                    </div>
                    <div className={styles.formGroup}>
                        <label>Location</label>
                        <input name="location" value={formData.location} onChange={handleChange} placeholder="e.g. New York or Remote" required />
                    </div>
                </div>

                <div className={styles.formRow}>
                    <div className={styles.formGroup}>
                        <label>Job Type</label>
                        <select name="type" value={formData.type} onChange={handleChange}>
                            <option>Full-time</option>
                            <option>Part-time</option>
                            <option>Contract</option>
                            <option>Internship</option>
                        </select>
                    </div>
                    <div className={styles.formGroup}>
                        <label>Industry</label>
                        <input name="industry" value={formData.industry} onChange={handleChange} placeholder="e.g. Technology" required />
                    </div>
                </div>

                <div className={styles.formGroup}>
                    <label>Job Description</label>
                    <textarea name="description" value={formData.description} onChange={handleChange} rows={5} placeholder="Describe the role and the team..." required />
                </div>

                <div className={styles.formGroup}>
                    <label>Requirements (one per line)</label>
                    <textarea name="requirements" value={formData.requirements} onChange={handleChange} rows={4} placeholder="e.g. 5+ years of experience in..." required />
                </div>

                <div className={styles.formGroup}>
                    <label>Responsibilities (one per line)</label>
                    <textarea name="responsibilities" value={formData.responsibilities} onChange={handleChange} rows={4} placeholder="e.g. Leading the design team..." required />
                </div>

                <div className={styles.formActions}>
                    <button type="button" className={styles.cancelBtn} onClick={() => router.back()}>Cancel</button>
                    <button type="submit" className={styles.submitBtn} disabled={isLoading}>
                        {isLoading ? 'Posting...' : 'Post Job'}
                    </button>
                </div>
            </form>
        </div>
    );
}

import React from 'react';
import { insforgeAdmin } from '@/lib/insforge-admin';
import RecruiterLayoutClient from './RecruiterLayoutClient';

export default async function RecruiterDashboardLayout({ children }: { children: React.ReactNode }) {
    // 1. Get Session User (In a real app, use headers/cookies to get current user ID)
    // For this demonstration, we'll assume the client component handles the auth state
    // but the server can pre-fetch permissions if we have the ID.
    // However, since we're in a shared layout, let's pass it to a client component 
    // that fetches permissions based on the active user.

    return (
        <RecruiterLayoutClient>
            {children}
        </RecruiterLayoutClient>
    );
}

.container {
    display: grid;
    grid-template-columns: 320px 1fr;
    height: calc(100vh - 160px);
    background: white;
    border: 1px solid #eef0f2;
    border-radius: 12px;
    overflow: hidden;
}

/* Sidebar */
.sidebar {
    border-right: 1px solid #f1f5f9;
    display: flex;
    flex-direction: column;
    background: #fafbfc;
}

.sidebarHeader {
    padding: 1.25rem;
    border-bottom: 1px solid #f1f5f9;
}

.sidebarHeader h2 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 800;
    color: #0f172a;
}

.convoList {
    flex: 1;
    overflow-y: auto;
}

.convoItem {
    padding: 1rem;
    display: flex;
    gap: 0.75rem;
    cursor: pointer;
    transition: background 0.2s;
    border-bottom: 1px solid #f8fafc;
}

.convoItem:hover {
    background: #f1f5f9;
}

.convoItemActive {
    background: #eff6ff;
    border-left: 3px solid #3b82f6;
}

.avatar {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: #3b82f6;
    color: white;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    flex-shrink: 0;
    overflow: hidden;
}

.avatar img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.convoInfo {
    flex: 1;
    min-width: 0;
}

.convoTop {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 2px;
}

.convoName {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.convoTime {
    font-size: 0.65rem;
    color: #94a3b8;
}

.convoPreview {
    font-size: 0.75rem;
    color: #64748b;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unreadBadge {
    background: #3b82f6;
    color: white;
    font-size: 0.6rem;
    font-weight: 700;
    padding: 2px 6px;
    border-radius: 10px;
    margin-left: 4px;
}

/* Chat Thread */
.chatArea {
    display: flex;
    flex-direction: column;
    background: white;
}

.chatHeader {
    padding: 1rem 1.25rem;
    border-bottom: 1px solid #f1f5f9;
    display: flex;
    align-items: center;
    gap: 0.75rem;
}

.chatPartnerName {
    font-size: 1rem;
    font-weight: 700;
    color: #0f172a;
}

.messagesList {
    flex: 1;
    padding: 1.5rem;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 1rem;
    background: #fcfdfe;
}

.messageRow {
    display: flex;
    width: 100%;
}

.messageRowOwn {
    justify-content: flex-end;
}

.bubble {
    max-width: 70%;
    padding: 0.75rem 1rem;
    border-radius: 16px;
    font-size: 0.85rem;
    line-height: 1.5;
    position: relative;
}

.bubbleTheirs {
    background: #f1f5f9;
    color: #1e293b;
    border-bottom-left-radius: 4px;
}

.bubbleOwn {
    background: #3b82f6;
    color: white;
    border-bottom-right-radius: 4px;
}

.messageTime {
    font-size: 0.62rem;
    color: #94a3b8;
    margin-top: 4px;
    display: block;
}

.messageTimeOwn {
    color: rgba(255, 255, 255, 0.7);
    text-align: right;
}

/* Input Area */
.inputArea {
    padding: 1.25rem;
    border-top: 1px solid #f1f5f9;
    background: white;
}

.inputWrapper {
    display: flex;
    gap: 0.75rem;
    align-items: flex-end;
    background: #f8fafc;
    border: 1px solid #e2e8f0;
    border-radius: 12px;
    padding: 0.5rem 0.75rem;
    transition: border-color 0.2s;
}

.inputWrapper:focus-within {
    border-color: #3b82f6;
}

.textarea {
    flex: 1;
    border: none;
    background: none;
    outline: none;
    resize: none;
    font-family: inherit;
    font-size: 0.88rem;
    color: #0f172a;
    padding: 0.35rem 0;
    max-height: 120px;
    min-height: 24px;
}

.sendBtn {
    background: #3b82f6;
    color: white;
    border: none;
    width: 32px;
    height: 32px;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    transition: transform 0.2s, opacity 0.2s;
}

.sendBtn:hover {
    transform: scale(1.05);
}

.sendBtn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.emptyState {
    flex: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    color: #94a3b8;
    text-align: center;
    padding: 2rem;
}

.emptyIcon {
    font-size: 3rem;
    margin-bottom: 1rem;
    opacity: 0.5;
}

"use client";

import React, { useState, useEffect, useRef, useMemo } from 'react';
import styles from './messages.module.css';
import { useAuth } from '@/lib/auth/AuthContext';
import { useMessages } from '@/lib/hooks/useMessages';
import { getConversations, type Conversation } from '@/lib/api/messages';
import { formatDistanceToNow } from 'date-fns';

export default function MessagesPage() {
    const { user } = useAuth();
    const [conversations, setConversations] = useState<Conversation[]>([]);
    const [selectedConvoId, setSelectedConvoId] = useState<string | null>(null);
    const [loadingConvos, setLoadingConvos] = useState(true);
    const [messageText, setMessageText] = useState('');
    const [isSending, setIsSending] = useState(false);

    const { messages, loading: loadingMessages, sendMessage } = useMessages(selectedConvoId);
    const scrollRef = useRef<HTMLDivElement>(null);

    const loadConversations = async () => {
        if (!user) return;
        try {
            const data = await getConversations(user.id);
            setConversations(data);
        } catch (err) {
            console.error('Error loading conversations:', err);
        } finally {
            setLoadingConvos(false);
        }
    };

    useEffect(() => {
        if (user) {
            loadConversations();
        }
    }, [user]);

    // Auto scroll to bottom
    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    const handleSend = async (e?: React.FormEvent) => {
        if (e) e.preventDefault();
        if (!messageText.trim() || isSending || !selectedConvoId) return;

        setIsSending(true);
        try {
            await sendMessage(messageText);
            setMessageText('');
            // Refresh conversation list to show new last message
            loadConversations();
        } catch (err) {
            console.error('Failed to send message:', err);
        } finally {
            setIsSending(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            handleSend();
        }
    };

    const selectedConvo = useMemo(() => 
        conversations.find(c => c.partner_id === selectedConvoId),
    [conversations, selectedConvoId]);

    if (!user) return <div className={styles.emptyState}>Please log in to view messages.</div>;

    return (
        <div className={styles.container}>
            {/* Sidebar */}
            <div className={styles.sidebar}>
                <div className={styles.sidebarHeader}>
                    <h2>Messages</h2>
                </div>
                <div className={styles.convoList}>
                    {loadingConvos ? (
                        <div style={{ padding: '2rem', textAlign: 'center', color: '#94a3b8' }}>Loading...</div>
                    ) : conversations.length === 0 ? (
                        <div className={styles.emptyState}>
                            <p>No conversations yet.</p>
                        </div>
                    ) : (
                        conversations.map(convo => (
                            <div 
                                key={convo.partner_id} 
                                className={`${styles.convoItem} ${selectedConvoId === convo.partner_id ? styles.convoItemActive : ''}`}
                                onClick={() => setSelectedConvoId(convo.partner_id)}
                            >
                                <div className={styles.avatar}>
                                    {convo.partner_avatar ? (
                                        <img src={convo.partner_avatar} alt={convo.partner_name} />
                                    ) : (
                                        convo.partner_name[0].toUpperCase()
                                    )}
                                </div>
                                <div className={styles.convoInfo}>
                                    <div className={styles.convoTop}>
                                        <span className={styles.convoName}>{convo.partner_name}</span>
                                        <span className={styles.convoTime}>
                                            {formatDistanceToNow(new Date(convo.last_message_time), { addSuffix: true })}
                                        </span>
                                    </div>
                                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                        <span className={styles.convoPreview}>{convo.last_message}</span>
                                        {convo.unread_count > 0 && (
                                            <span className={styles.unreadBadge}>{convo.unread_count}</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </div>

            {/* Chat Area */}
            <div className={styles.chatArea}>
                {selectedConvoId ? (
                    <>
                        <div className={styles.chatHeader}>
                            <div className={styles.avatar}>
                                {selectedConvo?.partner_avatar ? (
                                    <img src={selectedConvo.partner_avatar} alt={selectedConvo.partner_name} />
                                ) : (
                                    selectedConvo?.partner_name?.[0]?.toUpperCase() || '?'
                                )}
                            </div>
                            <span className={styles.chatPartnerName}>{selectedConvo?.partner_name}</span>
                        </div>

                        <div className={styles.messagesList} ref={scrollRef}>
                            {loadingMessages ? (
                                <div style={{ textAlign: 'center', padding: '2rem', color: '#94a3b8' }}>Loading messages...</div>
                            ) : messages.length === 0 ? (
                                <div className={styles.emptyState}>
                                    <p>Start a conversation with {selectedConvo?.partner_name}</p>
                                </div>
                            ) : (
                                messages.map(msg => {
                                    const isOwn = msg.sender_id === user.id;
                                    return (
                                        <div key={msg.id} className={`${styles.messageRow} ${isOwn ? styles.messageRowOwn : ''}`}>
                                            <div className={`${styles.bubble} ${isOwn ? styles.bubbleOwn : styles.bubbleTheirs}`}>
                                                {msg.content}
                                                <span className={`${styles.messageTime} ${isOwn ? styles.messageTimeOwn : ''}`}>
                                                    {new Date(msg.created_at).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                                </span>
                                            </div>
                                        </div>
                                    );
                                })
                            )}
                        </div>

                        <div className={styles.inputArea}>
                            <form onSubmit={handleSend} className={styles.inputWrapper}>
                                <textarea 
                                    className={styles.textarea}
                                    placeholder="Type a message..."
                                    value={messageText}
                                    onChange={(e) => setMessageText(e.target.value)}
                                    onKeyDown={handleKeyDown}
                                    rows={1}
                                    disabled={isSending}
                                />
                                <button type="submit" className={styles.sendBtn} disabled={!messageText.trim() || isSending}>
                                    {isSending ? (
                                        <div style={{ width: 12, height: 12, border: '2px solid white', borderTopColor: 'transparent', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
                                    ) : (
                                        <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="22" y1="2" x2="11" y2="13"></line><polygon points="22 2 15 22 11 13 2 9 22 2"></polygon></svg>
                                    )}
                                </button>
                            </form>
                        </div>
                    </>
                ) : (
                    <div className={styles.emptyState}>
                        <div className={styles.emptyIcon}>💬</div>
                        <h3>Your Messages</h3>
                        <p>Select a conversation to start chatting.</p>
                    </div>
                )}
            </div>
            <style jsx>{`
                @keyframes spin {
                    to { transform: rotate(360deg); }
                }
            `}</style>
        </div>
    );
}

"use client";
import React, { useEffect, useState } from 'react';
import styles from './recruiter.module.css';
import AnimateOnScroll from '@/components/AnimateOnScroll';
import { insforge } from '@/lib/insforge';
