                        </div>

                        <div className={styles.card}>
                            <h2 className={styles.cardTitle}>Hiring Pipeline</h2>
                            <div className={styles.pipelineBar}>
                                {[
                                    { label: 'Screening', count: 48, width: '35%', color: '#3b82f6' },
                                    { label: 'Interview', count: 22, width: '25%', color: '#7c3aed' },
