}

.candFullHead {
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.candFullAvatar {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--primary-blue), #60a5fa);
    color: white;
    font-size: 0.75rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
}

.candFullName {
    font-size: 0.88rem;
    font-weight: 700;
    color: #0f172a;
}

.candFullRole {
    font-size: 0.72rem;
    color: #64748b;
}

.candFullTags {
    display: flex;
    flex-wrap: wrap;
    gap: 0.25rem;
    margin-top: 0.1rem;
}

.candFullTag {
    font-size: 0.62rem;
    color: #475569;
    background: #f5f7fa;
    padding: 0.1rem 0.4rem;
