    border: 1px solid #eef0f2;
}

.candFullFoot {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.2rem;
}

.candFullLoc {
    font-size: 0.68rem;
    color: #94a3b8;
}

.candFullMatch {
    font-size: 0.68rem;
    font-weight: 700;
    color: var(--primary-blue);
}

.candFullActions {
    display: flex;
    gap: 0.3rem;
}

.candViewBtn {
    font-size: 0.75rem;
    font-weight: 700;
    padding: 0.4rem 0.85rem;
    background: linear-gradient(135deg, var(--primary-blue), #2563eb);
    color: white;
    border: none;
    border-radius: 8px;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
