}

.actionLink {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--primary-blue);
    font-weight: 800;
    text-decoration: none;
    font-size: 0.95rem;
}

/* CTA */
.ctaSection {
    padding: 10rem 0;
}

.ctaBox {
    background: linear-gradient(135deg, var(--deep-navy) 0%, #001f3f 100%);
    border-radius: 48px;
    padding: 10rem 4rem;
    text-align: center;
    color: white;
    position: relative;
    overflow: hidden;
}

.ctaBox::before {
    content: '';
    position: absolute;
    inset: 0;
    background-image: radial-gradient(circle at center, rgba(0, 123, 255, 0.2) 0%, transparent 70%);
}

.ctaTitle {
    font-size: 4rem;
    font-weight: 900;
    margin-bottom: 2rem;
    position: relative;
