}

.ctaBtn {
    background: var(--primary-blue);
    color: white;
    padding: 1.5rem 4rem;
    border-radius: 18px;
    font-weight: 900;
    text-decoration: none;
    display: inline-block;
    transition: var(--transition-smooth);
    box-shadow: 0 20px 40px rgba(0, 123, 255, 0.3);
}

@media (max-width: 1100px) {
    .commandGrid {
        grid-template-columns: 1fr;
        gap: 5rem;
    }

    .solutionGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .dashboardMockup {
        grid-template-columns: 1fr;
        gap: 2rem;
    }
}

@media (max-width: 768px) {
    .heroTitle {
        font-size: 3rem;
    }

    .solutionGrid {
        grid-template-columns: 1fr;
    }

    .ctaTitle {
        font-size: 2.5rem;
    }

    .commandTitle {
        font-size: 2.5rem;
    }
}

'use client';
import React, { useState } from 'react';
import styles from './post-job.module.css';

const SparkleIco = () => <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><path d="m12 3 1.912 5.885L20 10.8l-5.088 1.912L13 18.6l-1.912-5.888L6 10.8l5.088-1.915Z" /></svg>;
const CheckIco = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>;

const JOB_TYPES = ['Full-Time', 'Part-Time', 'Remote', 'Hybrid', 'Contract'];
const INDUSTRIES = ['Technology', 'Product', 'Design', 'Finance', 'Sales & Marketing', 'HR & People', 'Operations', 'Customer Success'];
const EXP_LEVELS = ['Entry Level', 'Mid Level', 'Senior', 'Lead / Manager', 'Director+'];
const VALUE_PROPS = [
    { icon: '🎯', stat: '10,000+', label: 'Active Candidates', desc: 'Reach pre-qualified talent instantly' },
    { icon: '🤖', stat: 'AI', label: 'Smart Matching', desc: 'AI matches jobs to the most relevant talent' },
    { icon: '✅', stat: 'Free', label: 'Free to Post', desc: 'Premium boosting available when needed' },
    { icon: '📋', stat: 'All-in-1', label: 'Application Dashboard', desc: 'Manage all applicants in one place' },
];

const PREVIEW_DEFAULTS = {
    title: 'Your Job Title', company: 'Your Company', location: 'Remote', type: 'Full-Time',
    salary: '$80k–$120k', skills: [] as string[], exp: 'Mid Level',
};

export default function PostJobPage() {
    const [step, setStep] = useState(0);
    const [remote, setRemote] = useState(true);
    const [skills, setSkills] = useState<string[]>([]);
    const [skillInput, setSkillInput] = useState('');
    const [aiLoading, setAiLoading] = useState(false);
    const [aiGenerated, setAiGenerated] = useState(false);
    const [submitted, setSubmitted] = useState(false);
    const [form, setForm] = useState({
        title: '', company: '', industry: '', location: '', salary: '', exp: '', description: '', deadline: ''
    });

    const set = (k: string, v: string) => setForm(p => ({ ...p, [k]: v }));

    const addSkill = () => {
        const s = skillInput.trim();
        if (s && !skills.includes(s)) setSkills(p => [...p, s]);
        setSkillInput('');
    };

    const handleAiGenerate = () => {
        setAiLoading(true);
        setTimeout(() => {
            setForm(p => ({
                ...p, description:
                    `We are looking for a talented ${form.title || 'professional'} to join our growing team at ${form.company || 'our company'}.\n\nResponsibilities:\n• Design, develop and maintain robust solutions\n• Collaborate cross-functionally with product and design teams\n• Champion best practices and mentor junior team members\n• Drive outcomes through data-informed decision making\n\nRequirements:\n${skills.length ? skills.map(s => `• ${s}`).join('\n') : '• Relevant skills and experience'}\n• Strong communication and problem-solving skills\n• Passion for building impactful products\n\nWhat we offer:\n• Competitive compensation ${form.salary ? `(${form.salary})` : ''}\n• Flexible remote-first culture\n• Professional growth budget\n• Collaborative and inclusive team`
            }));
            setAiLoading(false); setAiGenerated(true);
        }, 1800);
    };

    const preview = {
        title: form.title || PREVIEW_DEFAULTS.title,
        company: form.company || PREVIEW_DEFAULTS.company,
        location: remote ? 'Remote' : form.location || PREVIEW_DEFAULTS.location,
        type: form.exp || JOB_TYPES[0],
        salary: form.salary || PREVIEW_DEFAULTS.salary,
        skills,
        exp: form.exp || PREVIEW_DEFAULTS.exp,
    };

    const STEPS = ['Details', 'Description', 'Preview'];

    return (
        <main className={styles.page}>
            {/* ── HERO ── */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <div className={styles.heroLayout}>
                        <div className={styles.heroLeft}>
                            <div className={styles.heroBadge}><SparkleIco /> AI-Powered</div>
                            <h1 className={styles.heroTitle}>Post a Job.<br />Let AI Find Your Perfect Hire.</h1>
                            <p className={styles.heroSub}>Create a high-quality job listing in under 2 minutes. Our AI generates the description — you just fill in the basics.</p>
                            <button className={styles.heroCta} onClick={() => document.getElementById('post-form')?.scrollIntoView({ behavior: 'smooth' })}>
                                Post a Job for Free <span className={styles.freeBadge}>FREE</span>
                            </button>
                        </div>
                        {/* Live preview card */}
                        <div className={`${styles.previewCard} glass-card`}>
                            <div className={styles.previewHead}>
                                <div className={styles.previewLogo}>{preview.company.slice(0, 2).toUpperCase()}</div>
                                <div>
                                    <div className={styles.previewTitle}>{preview.title}</div>
                                    <div className={styles.previewCompany}>{preview.company}</div>
                                </div>
                            </div>
                            <div className={styles.previewMeta}>
                                <span>📍 {preview.location}</span>
                                <span>💼 {preview.exp}</span>
                            </div>
                            <div className={styles.previewTags}>
                                <span className={styles.previewTag}>{preview.salary}</span>
                                {skills.slice(0, 3).map(s => <span key={s} className={styles.previewSkill}>{s}</span>)}
                            </div>
                            <div className={styles.previewLabel}>Live Preview</div>
                        </div>
                    </div>
                </div>
            </section>

            {/* ── FORM ── */}
            <section className={styles.formSection} id="post-form">
                <div className="premium-container">
                    <div className={styles.formWrap}>

                        {/* Progress */}
                        <div className={styles.progressBar}>
                            {STEPS.map((s, i) => (
                                <React.Fragment key={s}>
                                    <div className={`${styles.progressStep} ${i <= step ? styles.progressStepActive : ''}`} onClick={() => i < step && setStep(i)}>
                                        <div className={styles.progressDot}>{i < step ? <CheckIco /> : i + 1}</div>
                                        <span className={styles.progressLabel}>{s}</span>
                                    </div>
                                    {i < STEPS.length - 1 && <div className={`${styles.progressLine} ${i < step ? styles.progressLineFill : ''}`} />}
                                </React.Fragment>
                            ))}
                        </div>

                        {submitted ? (
                            <div className={styles.success}>
                                <div className={styles.successIco}><CheckIco /></div>
                                <h2 className={styles.successTitle}>Job Posted Successfully!</h2>
                                <p className={styles.successDesc}>Your listing is now live. Our AI is already matching candidates to your role.</p>
                                <button className={styles.successBtn} onClick={() => { setSubmitted(false); setStep(0); }}>Post Another Job</button>
                            </div>
                        ) : (
                            <>
                                {/* STEP 0 — Details */}
                                {step === 0 && (
                                    <div className={styles.formStep}>
                                        <h2 className={styles.stepHdr}>Job Details</h2>
                                        <div className={styles.fieldRow}>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Job Title *</label>
                                                <input className={styles.input} placeholder="e.g. Senior Product Designer" value={form.title} onChange={e => set('title', e.target.value)} />
                                            </div>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Company Name *</label>
                                                <input className={styles.input} placeholder="Your Company" value={form.company} onChange={e => set('company', e.target.value)} />
                                            </div>
                                        </div>
                                        <div className={styles.fieldRow}>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Industry / Department</label>
                                                <select className={styles.select} value={form.industry} onChange={e => set('industry', e.target.value)}>
                                                    <option value="">Select industry</option>
                                                    {INDUSTRIES.map(i => <option key={i}>{i}</option>)}
                                                </select>
                                            </div>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Experience Level</label>
                                                <select className={styles.select} value={form.exp} onChange={e => set('exp', e.target.value)}>
                                                    <option value="">Select level</option>
                                                    {EXP_LEVELS.map(e => <option key={e}>{e}</option>)}
                                                </select>
                                            </div>
                                        </div>

                                        {/* Location toggle */}
                                        <div className={styles.field}>
                                            <label className={styles.lbl}>Location</label>
                                            <div className={styles.locationToggle}>
                                                <button className={`${styles.toggleBtn} ${remote ? styles.toggleActive : ''}`} onClick={() => setRemote(true)}>Remote</button>
                                                <button className={`${styles.toggleBtn} ${!remote ? styles.toggleActive : ''}`} onClick={() => setRemote(false)}>Specific City</button>
                                            </div>
                                            {!remote && <input className={`${styles.input} ${styles.mt8}`} placeholder="e.g. San Francisco, CA" value={form.location} onChange={e => set('location', e.target.value)} />}
                                        </div>

                                        <div className={styles.fieldRow}>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Salary Range <em className={styles.opt}>(optional)</em></label>
                                                <input className={styles.input} placeholder="e.g. $80k–$120k" value={form.salary} onChange={e => set('salary', e.target.value)} />
                                            </div>
                                            <div className={styles.field}>
                                                <label className={styles.lbl}>Application Deadline</label>
                                                <input className={styles.input} type="date" value={form.deadline} onChange={e => set('deadline', e.target.value)} />
                                            </div>
                                        </div>

                                        {/* Skills tag input */}
                                        <div className={styles.field}>
                                            <label className={styles.lbl}>Required Skills</label>
                                            <div className={styles.skillsWrap}>
                                                {skills.map(s => (
                                                    <span key={s} className={styles.skillTag}>{s}<button onClick={() => setSkills(p => p.filter(x => x !== s))}>×</button></span>
                                                ))}
                                                <input className={styles.skillInput} placeholder="Type skill + Enter"
                                                    value={skillInput} onChange={e => setSkillInput(e.target.value)}
                                                    onKeyDown={e => { if (e.key === 'Enter') { e.preventDefault(); addSkill(); } }} />
                                            </div>
                                        </div>

                                        <button className={styles.nextBtn} onClick={() => setStep(1)}>Continue to Description →</button>
                                    </div>
                                )}

                                {/* STEP 1 — Description */}
                                {step === 1 && (
                                    <div className={styles.formStep}>
                                        <h2 className={styles.stepHdr}>Job Description</h2>
                                        <div className={styles.aiRow}>
                                            <p className={styles.aiHint}>Let AI write your job description based on the details you filled in.</p>
                                            <button className={styles.aiBtn} onClick={handleAiGenerate} disabled={aiLoading}>
                                                {aiLoading ? <span className={styles.aiSpinner} /> : <SparkleIco />}
                                                {aiLoading ? 'Generating...' : '✦ AI Generate Description'}
                                            </button>
                                        </div>
                                        <textarea className={`${styles.textarea} ${aiGenerated ? styles.textareaAi : ''}`}
                                            rows={14} placeholder="Or write your job description here..."
                                            value={form.description} onChange={e => set('description', e.target.value)} />
                                        {aiGenerated && <div className={styles.aiNote}><SparkleIco /> AI-generated — review and edit before posting</div>}
                                        <div className={styles.stepBtns}>
                                            <button className={styles.backBtn} onClick={() => setStep(0)}>← Back</button>
                                            <button className={styles.nextBtn} onClick={() => setStep(2)}>Preview Job →</button>
                                        </div>
                                    </div>
                                )}

                                {/* STEP 2 — Preview */}
                                {step === 2 && (
                                    <div className={styles.formStep}>
                                        <h2 className={styles.stepHdr}>Preview Your Listing</h2>
                                        <div className={styles.finalPreview}>
                                            <div className={styles.fpHead}>
                                                <div className={styles.fpLogo}>{preview.company.slice(0, 2).toUpperCase()}</div>
                                                <div>
                                                    <div className={styles.fpTitle}>{preview.title}</div>
                                                    <div className={styles.fpMeta}>{preview.company} · {preview.location}</div>
                                                </div>
                                            </div>
                                            <div className={styles.fpBadges}>
                                                <span className={styles.fpBadge}>{preview.exp}</span>
                                                {preview.salary && <span className={styles.fpBadge}>{preview.salary}</span>}
                                                {skills.slice(0, 4).map(s => <span key={s} className={styles.fpSkill}>{s}</span>)}
                                            </div>
                                            <div className={styles.fpDesc}>{form.description || 'No description yet.'}</div>
                                        </div>
                                        <div className={styles.stepBtns}>
                                            <button className={styles.backBtn} onClick={() => setStep(1)}>← Edit</button>
                                            <button className={styles.postBtn} onClick={() => setSubmitted(true)}>🚀 Post This Job</button>
                                        </div>
                                    </div>
                                )}
                            </>
                        )}
                    </div>
                </div>
            </section>

            {/* ── VALUE PROPS ── */}
            <section className={styles.valueSection}>
                <div className="premium-container">
                    <h2 className={styles.valueSectionTitle}>Why Post on TalentMesh?</h2>
                    <div className={styles.valueGrid}>
                        {VALUE_PROPS.map(vp => (
                            <div key={vp.label} className={styles.valueProp}>
                                <div className={styles.valuePropIcoBg}><span className={styles.valuePropIco}>{vp.icon}</span></div>
                                <div className={styles.valueStat}>{vp.stat}</div>
                                <div className={styles.valueLabel}>{vp.label}</div>
                                <div className={styles.valueDesc}>{vp.desc}</div>
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </main>
    );
}

/* ─── Page ──────────────────────────────────────────────────────────────────── */
.page {
    padding-top: 68px;
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ──────────────────────────────────────────────────────────────────── */
.hero {
    background: linear-gradient(135deg, #0d1b3e 0%, #1e293b 100%);
    padding: 64px 0;
    overflow: hidden;
}

.heroLayout {
    display: grid;
    grid-template-columns: 1fr 360px;
    gap: 48px;
    align-items: center;
}

.heroLeft {
    color: white;
}

.heroBadge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: rgba(33, 150, 243, 0.18);
    border: 1px solid rgba(33, 150, 243, 0.35);
    color: var(--cool-sky-2, #42A5F5);
    font-size: 0.78rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    padding: 5px 14px;
    border-radius: 999px;
    margin-bottom: 18px;
    text-transform: uppercase;
}

.heroTitle {
    font-size: clamp(1.9rem, 4vw, 3rem);
    font-weight: 800;
    color: white;
    margin: 0 0 16px;
    line-height: 1.15;
    letter-spacing: -0.02em;
}

.heroSub {
    font-size: 1.05rem;
    color: #BBDEFB;
    margin: 0 0 32px;
    line-height: 1.65;
}

.heroCta {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    background: var(--primary-blue, #007BFF);
    color: white;
    border: none;
    padding: 14px 28px;
    border-radius: 12px;
    font-size: 1rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.heroCta:hover {
    background: #0069d9;
    box-shadow: 0 8px 24px rgba(0, 123, 255, 0.5);
    transform: translateY(-2px);
}

.freeBadge {
    background: var(--cool-sky-2, #42A5F5);
    color: white;
    font-size: 0.68rem;
    font-weight: 800;
    padding: 2px 8px;
    border-radius: 999px;
    letter-spacing: 0.04em;
}

/* Live preview card */
.previewCard {
    background: rgba(255, 255, 255, 0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.15);
    border-radius: 16px;
    padding: 24px;
    color: white;
    position: relative;
}

.previewHead {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 14px;
}

.previewLogo {
    width: 44px;
    height: 44px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.85rem;
    color: white;
    flex-shrink: 0;
}

.previewTitle {
    font-weight: 700;
    font-size: 1rem;
    color: white;
}

.previewCompany {
    font-size: 0.82rem;
    color: #BBDEFB;
    margin-top: 2px;
}

.previewMeta {
    display: flex;
    gap: 14px;
    font-size: 0.8rem;
    color: #90CAF9;
    margin-bottom: 12px;
}

.previewTags {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.previewTag {
    background: rgba(0, 123, 255, 0.2);
    border: 1px solid rgba(0, 123, 255, 0.35);
    color: #90CAF9;
    font-size: 0.72rem;
    font-weight: 600;
    padding: 3px 10px;
    border-radius: 999px;
}

.previewSkill {
    background: rgba(33, 150, 243, 0.15);
    border: 1px solid rgba(33, 150, 243, 0.3);
    color: #BBDEFB;
    font-size: 0.72rem;
    font-weight: 600;
    padding: 3px 10px;
    border-radius: 999px;
}

.previewLabel {
    position: absolute;
    top: -10px;
    right: 16px;
    background: var(--cool-sky-2);
    color: white;
    font-size: 0.65rem;
    font-weight: 700;
    padding: 2px 10px;
    border-radius: 999px;
    letter-spacing: 0.05em;
    text-transform: uppercase;
}

/* ─── Form Section ──────────────────────────────────────────────────────────── */
.formSection {
    padding: 52px 0;
}

.formWrap {
    max-width: 720px;
    margin: 0 auto;
    background: white;
    border-radius: 24px;
    box-shadow: 0 8px 40px rgba(0, 0, 0, 0.10);
    overflow: hidden;
}

/* Progress */
.progressBar {
    display: flex;
    align-items: center;
    padding: 24px 32px;
    background: var(--light-ice-blue);
    border-bottom: 1px solid var(--sky-blue);
}

.progressStep {
    display: flex;
    align-items: center;
    gap: 8px;
}

.progressStep:not(:last-child) {
    flex: 1;
}

.progressDot {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: var(--alice-blue);
    border: 2px solid var(--sky-blue);
    color: var(--medium-grey);
    font-size: 0.8rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
    transition: all 0.25s ease;
}

.progressStepActive .progressDot {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
    color: white;
}

.progressLabel {
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--medium-grey);
    white-space: nowrap;
}

.progressStepActive .progressLabel {
    color: var(--cobalt-blue);
}

.progressLine {
    flex: 1;
    height: 2px;
    background: var(--sky-blue);
    margin: 0 8px;
    border-radius: 2px;
}

.progressLineFill {
    background: var(--primary-blue);
}

/* Form steps */
.formStep {
    padding: 36px;
}

.stepHdr {
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 24px;
}

.fieldRow {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}

.field {
    display: flex;
    flex-direction: column;
    gap: 6px;
    margin-bottom: 16px;
}

.lbl {
    font-size: 0.85rem;
    font-weight: 600;
    color: var(--cobalt-blue);
}

.opt {
    font-style: italic;
    font-weight: 400;
    color: var(--medium-grey);
    font-size: 0.8rem;
}

.input,
.select {
    border: 1px solid var(--sky-blue);
    border-radius: 8px;
    padding: 11px 14px;
    font-size: 0.9rem;
    font-family: inherit;
    color: var(--deep-navy, #0d2137);
    background: white;
    outline: none;
    appearance: none;
    transition: border-color 0.2s, box-shadow 0.2s;
}

.input:focus,
.select:focus {
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.12);
}

.input::placeholder {
    color: rgba(71, 85, 105, 0.5);
}

.mt8 {
    margin-top: 8px;
}

/* Location toggle */
.locationToggle {
    display: flex;
    border-radius: 8px;
    overflow: hidden;
    border: 1px solid var(--sky-blue);
    width: fit-content;
}

.toggleBtn {
    padding: 9px 20px;
    background: var(--light-ice-blue);
    color: var(--medium-grey);
    border: none;
    font-size: 0.88rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.toggleActive {
    background: var(--primary-blue) !important;
    color: white !important;
}

/* Skills tag input */
.skillsWrap {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    border: 1px solid var(--sky-blue);
    border-radius: 8px;
    padding: 8px 12px;
    min-height: 46px;
    transition: border-color 0.2s;
}

.skillsWrap:focus-within {
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.12);
}

.skillTag {
    display: flex;
    align-items: center;
    gap: 4px;
    background: var(--cool-sky-2, #42A5F5);
    color: white;
    font-size: 0.78rem;
    font-weight: 600;
    padding: 3px 10px;
    border-radius: 999px;
}

.skillTag button {
    background: none;
    border: none;
    color: white;
    cursor: pointer;
    font-size: 0.9rem;
    padding: 0;
    line-height: 1;
}

.skillInput {
    border: none;
    outline: none;
    font-family: inherit;
    font-size: 0.88rem;
    color: var(--deep-navy);
    min-width: 120px;
    flex: 1;
}

.skillInput::placeholder {
    color: rgba(71, 85, 105, 0.5);
}

/* AI row */
.aiRow {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
    flex-wrap: wrap;
    gap: 12px;
}

.aiHint {
    font-size: 0.85rem;
    color: var(--medium-grey);
    margin: 0;
}

.aiBtn {
    display: flex;
    align-items: center;
    gap: 7px;
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    color: white;
    border: none;
    padding: 9px 18px;
    border-radius: 8px;
    font-size: 0.85rem;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
}

.aiBtn:hover {
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
    transform: translateY(-1px);
}

.aiBtn:disabled {
    opacity: 0.7;
    cursor: not-allowed;
    transform: none;
}

.aiSpinner {
    width: 14px;
    height: 14px;
    border: 2px solid rgba(255, 255, 255, 0.4);
    border-top-color: white;
    border-radius: 50%;
    animation: spin 0.7s linear infinite;
    display: inline-block;
}

@keyframes spin {
    to {
        transform: rotate(360deg);
    }
}

.textarea {
    width: 100%;
    box-sizing: border-box;
    border: 1px solid var(--sky-blue);
    border-radius: 8px;
    padding: 12px 14px;
    font-size: 0.9rem;
    font-family: inherit;
    color: var(--deep-navy);
    background: white;
    outline: none;
    resize: vertical;
    transition: border-color 0.2s, box-shadow 0.2s;
}

.textareaAi {
    background: var(--alice-blue, #E3F2FD);
    border-color: var(--dodger-blue);
}

.textarea:focus {
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.12);
}

.aiNote {
    display: flex;
    align-items: center;
    gap: 5px;
    font-size: 0.78rem;
    color: var(--dodger-blue);
    font-weight: 600;
    margin-top: 6px;
}

/* Navigation btns */
.stepBtns {
    display: flex;
    gap: 12px;
    margin-top: 24px;
    justify-content: flex-end;
}

.nextBtn {
    background: var(--primary-blue);
    color: white;
    border: none;
    padding: 12px 24px;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 700;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.nextBtn:hover {
    background: #0069d9;
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.backBtn {
    background: var(--light-ice-blue);
    color: var(--medium-grey);
    border: 1px solid var(--sky-blue);
    padding: 12px 20px;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    font-family: inherit;
}

.postBtn {
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    color: white;
    border: none;
    padding: 14px 28px;
    border-radius: 10px;
    font-size: 1rem;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
}

.postBtn:hover {
    box-shadow: 0 6px 20px rgba(0, 123, 255, 0.45);
    transform: translateY(-1px);
}

/* Final preview */
.finalPreview {
    background: var(--light-ice-blue);
    border-radius: 12px;
    padding: 24px;
    border: 1px solid var(--sky-blue);
    margin-bottom: 0;
}

.fpHead {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 12px;
}

.fpLogo {
    width: 48px;
    height: 48px;
    border-radius: 10px;
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    color: white;
    font-size: 0.9rem;
}

.fpTitle {
    font-size: 1.1rem;
    font-weight: 700;
    color: var(--cobalt-blue);
}

.fpMeta {
    font-size: 0.83rem;
    color: var(--medium-grey);
    margin-top: 2px;
}

.fpBadges {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
    margin-bottom: 14px;
}

.fpBadge {
    background: var(--alice-blue);
    color: var(--ocean-deep);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 4px 12px;
    border-radius: 999px;
}

.fpSkill {
    background: var(--dodger-blue);
    color: white;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 4px 12px;
    border-radius: 999px;
}

.fpDesc {
    font-size: 0.88rem;
    color: var(--medium-grey);
    line-height: 1.65;
    white-space: pre-line;
}

/* Success */
.success {
    text-align: center;
    padding: 52px 32px;
}

.successIco {
    width: 56px;
    height: 56px;
    border-radius: 50%;
    background: #DCFCE7;
    color: #16A34A;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 16px;
}

.successTitle {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    margin: 0 0 10px;
}

.successDesc {
    font-size: 0.95rem;
    color: var(--medium-grey);
    margin: 0 0 24px;
}

.successBtn {
    background: var(--primary-blue);
    color: white;
    border: none;
    padding: 12px 28px;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
}

/* ─── Value Props ────────────────────────────────────────────────────────────── */
.valueSection {
    background: var(--light-ice-blue);
    padding: 64px 0;
}

.valueSectionTitle {
    font-size: 1.7rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: center;
    margin: 0 0 40px;
}

.valueGrid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 24px;
}

.valueProp {
    text-align: center;
    padding: 24px 16px;
}

.valuePropIcoBg {
    width: 60px;
    height: 60px;
    border-radius: 50%;
    background: var(--alice-blue);
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 14px;
}

.valuePropIco {
    font-size: 1.5rem;
}

.valueStat {
    font-size: 1.3rem;
    font-weight: 800;
    color: var(--cobalt-blue);
}

.valueLabel {
    font-size: 0.88rem;
    font-weight: 700;
    color: var(--ocean-deep);
    margin: 2px 0 4px;
}

.valueDesc {
    font-size: 0.8rem;
    color: var(--medium-grey);
}

/* ─── Responsive ─────────────────────────────────────────────────────────────── */
@media (max-width: 1024px) {
    .heroLayout {
        grid-template-columns: 1fr;
    }

    .previewCard {
        display: none;
    }

    .valueGrid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 640px) {
    .formStep {
        padding: 24px 20px;
    }

    .fieldRow {
        grid-template-columns: 1fr;
    }

    .progressLabel {
        display: none;
    }

    .valueGrid {
        grid-template-columns: 1fr 1fr;
    }

    .stepBtns {
        flex-direction: column-reverse;
    }
}

'use client';
import React, { useState } from 'react';
import styles from './products.module.css';

const CheckIco = () => <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>;
const ChevIco = () => <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><polyline points="6 9 12 15 18 9" /></svg>;

const PLANS = [
    {
        name: 'Starter', tag: null, price: { monthly: 0, annual: 0 }, period: 'Free forever',
        desc: 'Perfect for small businesses hiring their first role.',
        features: ['1 active job post', 'Basic candidate matching', 'Email support', 'Candidate profile views', 'Standard listing'],
        ctaLabel: 'Get Started Free', ctaStyle: 'outline',
    },
    {
        name: 'Growth', tag: 'Most Popular ★', price: { monthly: 99, annual: 79 }, period: 'per month',
        desc: 'For growing teams that hire regularly.',
        features: ['Up to 5 active job posts', 'AI-powered screening', 'Applicant dashboard', 'Direct messaging', 'Calendar integration', 'Priority support', 'Analytics'],
        ctaLabel: 'Start Free Trial', ctaStyle: 'filled',
    },
    {
        name: 'Enterprise', tag: null, price: { monthly: null, annual: null }, period: 'Custom pricing',
        desc: 'For large teams, agencies, and high-volume hiring.',
        features: ['Unlimited posts + RPO options', 'Dedicated account manager', 'Custom integrations', 'Advanced analytics', 'SLA-backed support', 'Onboarding support'],
        ctaLabel: 'Book a Demo', ctaStyle: 'dark',
    },
];

const TABLE_ROWS = [
    { feature: 'Active Job Posts', starter: '1', growth: 'Up to 5', enterprise: 'Unlimited' },
    { feature: 'AI Candidate Matching', starter: 'Basic', growth: 'Advanced', enterprise: 'Custom' },
    { feature: 'Applicant Dashboard', starter: false, growth: true, enterprise: true },
    { feature: 'Direct Messaging', starter: false, growth: true, enterprise: true },
    { feature: 'Calendar Scheduling', starter: false, growth: true, enterprise: true },
    { feature: 'Analytics & Reporting', starter: false, growth: 'Standard', enterprise: 'Advanced' },
    { feature: 'Support Level', starter: 'Email', growth: 'Priority', enterprise: 'Dedicated SLA' },
    { feature: 'Custom Integrations', starter: false, growth: false, enterprise: true },
];

const FAQS = [
    { q: 'Can I cancel my plan anytime?', a: 'Yes. You can cancel at any time from your account settings with no lock-in period.' },
    { q: 'Do you charge per hire or per post?', a: 'We charge per job post, not per hire. The Growth plan allows up to 5 concurrent posts.' },
    { q: 'Is there a free trial available?', a: 'Yes — the Growth plan comes with a 14-day free trial, no credit card required.' },
    { q: 'What payment methods do you accept?', a: 'We accept all major credit cards (Visa, Mastercard, Amex) and bank transfers for Enterprise plans.' },
    { q: 'How do I upgrade or downgrade my plan?', a: 'You can change plans at any time from your billing settings. Changes take effect at the next billing cycle.' },
    { q: 'Can I try before I buy?', a: 'Absolutely — start with our free Starter plan or activate the Growth free trial to explore all features.' },
];

export default function ProductsPage() {
    const [annual, setAnnual] = useState(false);
    const [openFaq, setOpenFaq] = useState<number | null>(null);

    const displayPrice = (plan: typeof PLANS[0]) => {
        if (plan.price.monthly === null) return 'Custom';
        const p = annual ? plan.price.annual : plan.price.monthly;
        return p === 0 ? 'Free' : `$${p}`;
    };

    return (
        <main className={styles.page}>
            {/* ── HERO ── */}
            <section className={styles.hero}>
                <div className="premium-container">
                    <h1 className={styles.heroTitle}>Simple Pricing. Powerful Hiring.</h1>
                    <p className={styles.heroSub}>Whether you&apos;re hiring one person or scaling a team, we have a plan that fits.</p>

                    {/* Billing toggle */}
                    <div className={styles.toggleWrap}>
                        <span className={`${styles.toggleLabel} ${!annual ? styles.toggleLabelActive : ''}`}>Monthly</span>
                        <button
                            className={`${styles.togglePill} ${annual ? styles.togglePillOn : ''}`}
                            onClick={() => setAnnual(a => !a)} aria-label="Switch billing period"
                        >
                            <span className={styles.toggleThumb} />
                        </button>
                        <span className={`${styles.toggleLabel} ${annual ? styles.toggleLabelActive : ''}`}>
                            Annual {annual && <span className={styles.saveBadge}>Save 20%</span>}
                        </span>
                    </div>
                </div>
            </section>

            {/* ── PRICING CARDS ── */}
            <section className={styles.pricingSection}>
                <div className="premium-container">
                    <div className={styles.pricingGrid}>
                        {PLANS.map(plan => (
                            <div key={plan.name} className={`${styles.planCard} ${plan.tag ? styles.planCardFeatured : ''}`}>
                                {plan.tag && <div className={styles.popularRibbon}>{plan.tag}</div>}
                                <div className={styles.planName}>{plan.name}</div>
                                <div className={styles.planPrice}>
                                    <span className={styles.priceNum}>{displayPrice(plan)}</span>
                                    {plan.price.monthly !== null && plan.price.monthly > 0 && (
                                        <span className={styles.pricePer}>/{annual ? 'mo (billed annually)' : 'month'}</span>
                                    )}
                                </div>
                                <div className={styles.planPeriod}>{plan.period}</div>
                                <p className={styles.planDesc}>{plan.desc}</p>
                                <ul className={styles.featureList}>
                                    {plan.features.map(f => (
                                        <li key={f} className={styles.featureItem}><span className={styles.featureCheck}><CheckIco /></span>{f}</li>
                                    ))}
                                </ul>
                                <button className={`${styles.planCta} ${styles[`cta_${plan.ctaStyle}`]}`}>{plan.ctaLabel}</button>
                            </div>
                        ))}
                    </div>
                </div>
            </section>

            {/* ── COMPARISON TABLE ── */}
            <section className={styles.tableSection}>
                <div className="premium-container">
                    <h2 className={styles.sectionTitle}>Feature Comparison</h2>
                    <div className={styles.tableWrap}>
                        <table className={styles.table}>
                            <thead>
                                <tr className={styles.tableHead}>
                                    <th className={styles.thFeature}>Feature</th>
                                    <th>Starter</th>
                                    <th className={styles.thGrowth}>Growth ★</th>
                                    <th>Enterprise</th>
                                </tr>
                            </thead>
                            <tbody>
                                {TABLE_ROWS.map((row, i) => (
                                    <tr key={row.feature} className={i % 2 === 0 ? styles.rowEven : styles.rowOdd}>
                                        <td className={styles.tdFeature}>{row.feature}</td>
                                        {([row.starter, row.growth, row.enterprise] as (boolean | string)[]).map((val, ci) => (
                                            <td key={ci} className={`${styles.tdVal} ${ci === 1 ? styles.tdGrowth : ''}`}>
                                                {val === true ? <span className={styles.check}>✓</span> :
                                                    val === false ? <span className={styles.dash}>—</span> : val}
                                            </td>
                                        ))}
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </section>

            {/* ── FAQ ── */}
            <section className={styles.faqSection}>
                <div className="premium-container">
                    <h2 className={styles.sectionTitle}>Frequently Asked Questions</h2>
                    <div className={styles.faqList}>
                        {FAQS.map((faq, i) => (
                            <div key={i} className={styles.faqItem}>
                                <button className={styles.faqQ} onClick={() => setOpenFaq(openFaq === i ? null : i)}>
                                    <span>{faq.q}</span>
                                    <span className={`${styles.faqChev} ${openFaq === i ? styles.faqChevOpen : ''}`}><ChevIco /></span>
                                </button>
                                {openFaq === i && <div className={styles.faqA}>{faq.a}</div>}
                            </div>
                        ))}
                    </div>
                </div>
            </section>
        </main>
    );
}

.page {
    padding-top: 68px;
    min-height: 100vh;
    background: var(--light-ice-blue, #F0F7FF);
}

/* ─── Hero ── */
.hero {
    background: white;
    padding: 60px 0 48px;
    text-align: center;
    border-bottom: 1px solid var(--sky-blue);
}

.heroTitle {
    font-size: clamp(2rem, 4.5vw, 2.8rem);
    font-weight: 800;
    color: var(--cobalt-blue);
    margin: 0 0 14px;
}

.heroSub {
    font-size: 1.05rem;
    color: var(--medium-grey);
    margin: 0 0 32px;
}

/* Toggle */
.toggleWrap {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 12px;
}

.toggleLabel {
    font-size: 0.92rem;
    font-weight: 600;
    color: var(--medium-grey);
    display: flex;
    align-items: center;
    gap: 8px;
    transition: color 0.2s;
}

.toggleLabelActive {
    color: var(--cobalt-blue);
}

.togglePill {
    width: 48px;
    height: 26px;
    border-radius: 999px;
    background: var(--alice-blue);
    border: 1px solid var(--sky-blue);
    cursor: pointer;
    position: relative;
    transition: background 0.25s ease;
}

.togglePillOn {
    background: var(--primary-blue);
    border-color: var(--primary-blue);
}

.toggleThumb {
    position: absolute;
    top: 3px;
    left: 3px;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: white;
    box-shadow: 0 1px 4px rgba(0, 0, 0, 0.25);
    transition: left 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}

.togglePillOn .toggleThumb {
    left: 25px;
}

.saveBadge {
    background: var(--dodger-blue);
    color: white;
    font-size: 0.68rem;
    font-weight: 800;
    padding: 2px 8px;
    border-radius: 999px;
    letter-spacing: 0.04em;
}

/* ─── Pricing Section ── */
.pricingSection {
    padding: 52px 0 64px;
}

.pricingGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 24px;
    align-items: stretch;
}

.planCard {
    background: white;
    border-radius: 18px;
    padding: 32px 28px;
    border: 1px solid var(--sky-blue);
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.planCard:hover {
    transform: translateY(-4px);
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.1);
}

.planCardFeatured {
    background: var(--alice-blue, #E3F2FD);
    border-color: var(--primary-blue);
    border-top: 4px solid var(--primary-blue);
}

.popularRibbon {
    position: absolute;
    top: 16px;
    right: 16px;
    background: var(--dodger-blue, #2196F3);
    color: white;
    font-size: 0.7rem;
    font-weight: 700;
    padding: 3px 12px;
    border-radius: 999px;
}

.planName {
    font-size: 1rem;
    font-weight: 700;
    color: var(--medium-grey, #475569);
    text-transform: uppercase;
    letter-spacing: 0.07em;
    margin-bottom: 16px;
}

.planPrice {
    display: flex;
    align-items: baseline;
    gap: 4px;
    margin-bottom: 2px;
}

.priceNum {
    font-size: 2.8rem;
    font-weight: 800;
    color: var(--cobalt-blue);
    line-height: 1;
    transition: all 0.3s ease;
}

.pricePer {
    font-size: 0.82rem;
    color: var(--medium-grey);
}

.planPeriod {
    font-size: 0.8rem;
    color: var(--medium-grey);
    margin-bottom: 12px;
}

.planDesc {
    font-size: 0.88rem;
    color: var(--medium-grey);
    margin: 0 0 24px;
    line-height: 1.55;
    border-bottom: 1px solid var(--sky-blue);
    padding-bottom: 20px;
}

.featureList {
    list-style: none;
    margin: 0 0 28px;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 10px;
    flex: 1;
}

.featureItem {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    font-size: 0.88rem;
    color: var(--medium-grey);
}

.featureCheck {
    color: var(--primary-blue);
    flex-shrink: 0;
    margin-top: 1px;
}

.planCta {
    width: 100%;
    padding: 13px 20px;
    border-radius: 10px;
    font-size: 0.95rem;
    font-weight: 700;
    cursor: pointer;
    font-family: inherit;
    transition: all 0.2s ease;
    border: none;
    margin-top: auto;
}

.cta_outline {
    background: white;
    color: var(--primary-blue);
    border: 2px solid var(--primary-blue);
}

.cta_outline:hover {
    background: var(--alice-blue);
}

.cta_filled {
    background: linear-gradient(135deg, var(--primary-blue), var(--dodger-blue));
    color: white;
}

.cta_filled:hover {
    box-shadow: 0 6px 20px rgba(0, 123, 255, 0.4);
    transform: translateY(-1px);
}

.cta_dark {
    background: var(--ocean-deep, #1565C0);
    color: white;
}

.cta_dark:hover {
    background: var(--cobalt-blue);
}

/* ─── Table Section ── */
.tableSection {
    background: white;
    padding: 64px 0;
}

.sectionTitle {
    font-size: clamp(1.5rem, 3vw, 2rem);
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: center;
    margin: 0 0 36px;
}

.tableWrap {
    overflow-x: auto;
    border-radius: 14px;
    border: 1px solid var(--sky-blue);
}

.table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.88rem;
}

.tableHead {
    background: var(--cobalt-blue, #0D47A1);
    color: white;
}

.tableHead th {
    padding: 14px 20px;
    text-align: center;
    font-weight: 700;
    font-size: 0.9rem;
}

.thFeature {
    text-align: left !important;
    width: 35%;
}

.thGrowth {
    background: rgba(30, 136, 229, 0.3);
    color: var(--cool-sky-2, #42A5F5);
}

.rowEven {
    background: white;
}

.rowOdd {
    background: var(--light-ice-blue, #F0F7FF);
}

.tdFeature {
    padding: 13px 20px;
    font-weight: 600;
    color: var(--medium-grey);
}

.tdVal {
    text-align: center;
    padding: 13px 20px;
    color: var(--medium-grey);
}

.tdGrowth {
    background: rgba(227, 242, 253, 0.5);
}

.check {
    color: var(--dodger-blue);
    font-size: 1rem;
    font-weight: 700;
}

.dash {
    color: rgba(71, 85, 105, 0.45);
    font-size: 1rem;
}

/* ─── FAQ Section ── */
.faqSection {
    background: var(--light-ice-blue);
    padding: 64px 0;
}

.faqList {
    max-width: 720px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
}

.faqItem {
    border-bottom: 1px solid #BBDEFB;
}

.faqItem:last-child {
    border-bottom: none;
}

.faqQ {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    padding: 20px 0;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 0.97rem;
    font-weight: 700;
    color: var(--cobalt-blue);
    text-align: left;
    font-family: inherit;
    gap: 12px;
}

.faqChev {
    color: var(--primary-blue);
    flex-shrink: 0;
    transition: transform 0.25s ease;
    line-height: 0;
}

.faqChevOpen {
    transform: rotate(180deg);
}

.faqA {
    padding: 0 0 20px 0;
    font-size: 0.9rem;
    color: var(--medium-grey);
    line-height: 1.65;
    background: var(--light-ice-blue);
    border-radius: 8px;
    padding: 14px 16px;
    margin-bottom: 4px;
}

/* ─── Responsive ── */
@media (max-width: 1024px) {
    .pricingGrid {
        grid-template-columns: 1fr;
        max-width: 480px;
        margin: 0 auto;
    }
}

@media (max-width: 640px) {
    .tableSection {
        padding: 40px 0;
    }

    .pricingSection {
        padding: 32px 0 40px;
    }
}

