"use client";
import React, { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import { insforge } from '@/lib/insforge';
import { uploadResume } from '@/lib/api/storage';
import { calculateProfileStrength } from '@/lib/utils/profile-utils';
import { OnboardingStepper } from '@/components/onboarding/OnboardingStepper';
import styles from '../../onboarding.module.css';

export default function CandidateDocuments() {
    const { user } = useAuth();
    const [resume, setResume] = useState<File | null>(null);
    const [resumeUrl, setResumeUrl] = useState('');
    const [linkedin, setLinkedin] = useState('');
    const [github, setGithub] = useState('');
    const [portfolio, setPortfolio] = useState('');
    const [headline, setHeadline] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [uploadProgress, setUploadProgress] = useState(0);
    const fileRef = useRef<HTMLInputElement>(null);
    const router = useRouter();

    useEffect(() => {
        const fetchInitialData = async () => {
            if (!user) return;
            const { data, error } = await insforge.database
                .from('candidate_profiles')
                .select('resume_url, linkedin_url, github_url, portfolio_url, headline')
                .eq('id', user.id)
                .single();

            if (data) {
                setResumeUrl(data.resume_url || '');
                setLinkedin(data.linkedin_url || '');
                setGithub(data.github_url || '');
                setPortfolio(data.portfolio_url || '');
                setHeadline(data.headline || '');
            }
        };
        fetchInitialData();
    }, [user]);

    const handleFile = (e: React.ChangeEvent<HTMLInputElement>) => {
        if (e.target.files && e.target.files[0]) {
            setResume(e.target.files[0]);
        }
    };

    const handleFinish = async () => {
        if (!user) return;

        setIsLoading(true);
        setUploadProgress(10);
        try {
            let finalResumeUrl = resumeUrl;

            // 1. Upload resume if a new one is selected
            if (resume) {
                setUploadProgress(30);
                finalResumeUrl = await uploadResume(resume, user.id);
                setUploadProgress(70);
            }

            // 2. Save all document & social info
            const updatePayload = {
                id: user.id,
                resume_url: finalResumeUrl,
                linkedin_url: linkedin,
                github_url: github,
                portfolio_url: portfolio,
                headline: headline,
            };

            const { error: updateError } = await insforge.database
                .from('candidate_profiles')
                .upsert(updatePayload);

            if (updateError) throw updateError;
            setUploadProgress(85);

            // 3. Fetch full profile and candidate_profile for strength calculation
            const [{ data: profile }, { data: candProfile }] = await Promise.all([
                insforge.database.from('profiles').select('*').eq('id', user.id).single(),
                insforge.database.from('candidate_profiles').select('*').eq('id', user.id).single(),
            ]);

            const strength = calculateProfileStrength(profile, candProfile);

            // 4. Update profile strength
            await insforge.database
                .from('candidate_profiles')
                .update({ profile_strength: strength })
                .eq('id', user.id);

            setUploadProgress(100);
            router.push(`/dashboard/candidate/${user.role_id || ''}`);
        } catch (err: any) {
            console.error('Error finishing onboarding:', err);
            alert(`Failed to complete onboarding: ${err.message}`);
        } finally {
            setIsLoading(false);
            setUploadProgress(0);
        }
    };

    return (
        <div className={styles.card}>
            <OnboardingStepper currentStep={3} />

            <div className={styles.header}>
                <h1 className={styles.title}>Professional links</h1>
                <p className={styles.subtitle}>Upload your resume and add your professional profiles</p>
            </div>

            <div className={styles.section}>
                <h3 className={styles.sectionTitle}>Resume</h3>
                <input type="file" ref={fileRef} onChange={handleFile} accept=".pdf" hidden />
                <div
                    className={`${styles.uploadArea} ${resume || resumeUrl ? styles.uploadAreaActive : ''}`}
                    onClick={() => fileRef.current?.click()}
                >
                    {(resume || resumeUrl) ? (
                        <>
                            <svg className={styles.uploadIcon} width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="var(--primary-blue)" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" /><polyline points="22 4 12 14.01 9 11.01" />
                            </svg>
                            <span className={styles.uploadText}>{resume ? resume.name : 'Resume uploaded'}</span>
                            <span className={styles.uploadHint}>Click to replace</span>
                        </>
                    ) : (
                        <>
                            <svg className={styles.uploadIcon} width="28" height="28" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                                <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" /><polyline points="17 8 12 3 7 8" /><line x1="12" y1="3" x2="12" y2="15" />
                            </svg>
                            <span className={styles.uploadText}>Upload your resume (PDF only)</span>
                            <span className={styles.uploadHint}>Max 5MB</span>
                        </>
                    )}
                </div>
                {uploadProgress > 0 && uploadProgress < 100 && (
                    <div className={styles.progressBar}>
                        <div className={styles.progressFill} style={{ width: `${uploadProgress}%` }} />
                    </div>
                )}
            </div>

            <div className={styles.section}>
                <h3 className={styles.sectionTitle}>Online presence</h3>
                <div className={styles.fieldGroup}>
                    <label className={styles.label}>Professional Headline / Bio</label>
                    <input
                        type="text"
                        className={styles.optionalInput}
                        placeholder="e.g. Senior Software Engineer with 5+ years experience"
                        value={headline}
                        onChange={e => setHeadline(e.target.value)}
                    />
                </div>
                <div className={styles.fieldGroup}>
                    <label className={styles.label}>LinkedIn URL</label>
                    <input
                        type="url"
                        className={styles.optionalInput}
                        placeholder="https://linkedin.com/in/username"
                        value={linkedin}
                        onChange={e => setLinkedin(e.target.value)}
                    />
                </div>
                <div className={styles.fieldGroup}>
                    <label className={styles.label}>GitHub URL</label>
                    <input
                        type="url"
                        className={styles.optionalInput}
                        placeholder="https://github.com/username"
                        value={github}
                        onChange={e => setGithub(e.target.value)}
                    />
                </div>
                <div className={styles.fieldGroup}>
                    <label className={styles.label}>Portfolio URL</label>
                    <input
                        type="url"
                        className={styles.optionalInput}
                        placeholder="https://yourportfolio.com"
                        value={portfolio}
                        onChange={e => setPortfolio(e.target.value)}
                    />
                </div>
            </div>

            <div className={styles.actions}>
                <button className={styles.backBtn} onClick={() => router.push('/onboarding/candidate/interests')}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" /></svg>
                    Back
                </button>
                <button className={styles.nextBtn} onClick={handleFinish} disabled={isLoading}>
                    {isLoading ? 'Completing...' : 'Finish Setup'}
                    {!isLoading && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>}
                </button>
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import { insforge } from '@/lib/insforge';
import { OnboardingStepper } from '@/components/onboarding/OnboardingStepper';
import styles from '../../onboarding.module.css';

const JOB_TYPES = [
    'Full-time', 'Part-time', 'Contract', 'Freelance', 'Internship', 'Hybrid'
];

export default function CandidateInterests() {
    const { user } = useAuth();
    const [jobTypes, setJobTypes] = useState<string[]>([]);
    const [locations, setLocations] = useState<string[]>([]);
    const [newLocation, setNewLocation] = useState('');
    const [experienceYears, setExperienceYears] = useState<number>(0);
    const [salaryMin, setSalaryMin] = useState<number>(0);
    const [salaryMax, setSalaryMax] = useState<number>(0);
    const [openToRemote, setOpenToRemote] = useState(true);
    const [isLoading, setIsLoading] = useState(false);
    const router = useRouter();

    useEffect(() => {
        const fetchInitialData = async () => {
            if (!user) return;
            const { data, error } = await insforge.database
                .from('candidate_profiles')
                .select('job_types, preferred_locations, salary_min, salary_max, open_to_remote, experience_years')
                .eq('id', user.id)
                .single();

            if (data) {
                setJobTypes(data.job_types || []);
                setLocations(data.preferred_locations || []);
                setExperienceYears(data.experience_years || 0);
                setSalaryMin(Number(data.salary_min) || 0);
                setSalaryMax(Number(data.salary_max) || 0);
                setOpenToRemote(data.open_to_remote ?? true);
            }
        };
        fetchInitialData();
    }, [user]);

    const toggleJobType = (type: string) => {
        setJobTypes(prev =>
            prev.includes(type) ? prev.filter(x => x !== type) : [...prev, type]
        );
    };

    const addLocation = (e: React.FormEvent) => {
        e.preventDefault();
        if (newLocation.trim() && !locations.includes(newLocation.trim())) {
            setLocations(prev => [...prev, newLocation.trim()]);
            setNewLocation('');
        }
    };

    const removeLocation = (loc: string) => {
        setLocations(prev => prev.filter(x => x !== loc));
    };

    const handleContinue = async () => {
        if (!user) return;

        setIsLoading(true);
        try {
            const { error } = await insforge.database
                .from('candidate_profiles')
                .upsert({
                    id: user.id,
                    job_types: jobTypes,
                    preferred_locations: locations,
                    experience_years: experienceYears,
                    salary_min: salaryMin,
                    salary_max: salaryMax,
                    open_to_remote: openToRemote,
                });

            if (error) throw error;
            router.push('/onboarding/candidate/documents');
        } catch (err) {
            console.error('Error saving interests:', err);
            alert('Failed to save interests. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.card}>
            <OnboardingStepper currentStep={2} />

            <div className={styles.header}>
                <h1 className={styles.title}>Your preferences</h1>
                <p className={styles.subtitle}>Tell us about your ideal job</p>
            </div>

            <div className={styles.section}>
                <h3 className={styles.sectionTitle}>Job types</h3>
                <div className={styles.tagWrap}>
                    {JOB_TYPES.map(type => (
                        <button
                            key={type}
                            type="button"
                            className={`${styles.tag} ${jobTypes.includes(type) ? styles.tagSelected : ''}`}
                            onClick={() => toggleJobType(type)}
                        >
                            {type}
                        </button>
                    ))}
                </div>
            </div>

            <div className={styles.section}>
                <h3 className={styles.sectionTitle}>Preferred locations</h3>
                <div className={styles.tagWrap}>
                    {locations.map(loc => (
                        <span key={loc} className={`${styles.tag} ${styles.tagSelected}`}>
                            {loc}
                            <button className={styles.removeTag} onClick={() => removeLocation(loc)}>×</button>
                        </span>
                    ))}
                </div>
                <form onSubmit={addLocation} className={styles.customField}>
                    <input
                        type="text"
                        className={styles.optionalInput}
                        placeholder="Add city or country..."
                        value={newLocation}
                        onChange={e => setNewLocation(e.target.value)}
                    />
                    <button type="submit" className={styles.addBtn} disabled={!newLocation.trim()}>Add</button>
                </form>
            </div>

            <div className={styles.section}>
                <h3 className={styles.sectionTitle}>Professional details</h3>
                <div className={styles.fieldGroup}>
                    <label className={styles.label}>Years of Experience</label>
                    <input
                        type="number"
                        className={styles.optionalInput}
                        value={experienceYears}
                        onChange={e => setExperienceYears(Number(e.target.value))}
                        placeholder="e.g. 5"
                    />
                </div>
            </div>

            <div className={styles.section}>
                <h3 className={styles.sectionTitle}>Salary expectations (Annual)</h3>
                <div className={styles.salaryGrid}>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Minimum</label>
                        <input
                            type="number"
                            className={styles.optionalInput}
                            value={salaryMin}
                            onChange={e => setSalaryMin(Number(e.target.value))}
                            placeholder="e.g. 50000"
                        />
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Maximum</label>
                        <input
                            type="number"
                            className={styles.optionalInput}
                            value={salaryMax}
                            onChange={e => setSalaryMax(Number(e.target.value))}
                            placeholder="e.g. 100000"
                        />
                    </div>
                </div>
            </div>

            <div className={styles.remoteToggle}>
                <label className={styles.toggleLabel}>
                    <input
                        type="checkbox"
                        checked={openToRemote}
                        onChange={e => setOpenToRemote(e.target.checked)}
                    />
                    <span>Open to remote work</span>
                </label>
            </div>

            <div className={styles.actions}>
                <button className={styles.backBtn} onClick={() => router.push('/onboarding/candidate/skills')}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" /></svg>
                    Back
                </button>
                <button 
                    className={styles.nextBtn} 
                    onClick={handleContinue} 
                    disabled={isLoading}
                >
                    {isLoading ? 'Saving...' : 'Continue'}
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>
                </button>
            </div>
        </div>
    );
}

"use client";

import React, { useEffect, useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';

import { OnboardingStepper } from '@/components/onboarding/OnboardingStepper';
import { useAuth } from '@/lib/auth/AuthContext';
import type { CandidateSettingsBundle } from '@/lib/candidate-profile';

import styles from '../onboarding.module.css';

type Step = 1 | 2 | 3;

const STEP_LABELS: [string, string, string] = ['Basic Info', 'Professional', 'Preferences'];
const JOB_TYPES = ['Remote', 'Hybrid', 'Onsite'];

const EMPTY_STATE: CandidateSettingsBundle = {
    profile: {
        id: '',
        email: '',
        name: '',
        phone: '',
        location: '',
        role_id: null,
    },
    candidateProfile: {
        headline: '',
        skills: [],
        experience_years: null,
        education: '',
        resume_url: '',
        salary_min: null,
        salary_max: null,
        preferred_locations: [],
        job_type: '',
        profile_strength: 0,
    },
};

function getFirstIncompleteStep(data: CandidateSettingsBundle): Step {
    if (!data.profile.name || !data.profile.phone || !data.profile.location) {
        return 1;
    }

    if (!data.candidateProfile.headline || data.candidateProfile.skills.length === 0 || !data.candidateProfile.education) {
        return 2;
    }

    return 3;
}

export default function CandidateOnboardingPage() {
    const router = useRouter();
    const { user } = useAuth();

    const [step, setStep] = useState<Step>(1);
    const [form, setForm] = useState<CandidateSettingsBundle>(EMPTY_STATE);
    const [isLoading, setIsLoading] = useState(true);
    const [isSaving, setIsSaving] = useState(false);
    const [error, setError] = useState('');
    const [skillInput, setSkillInput] = useState('');
    const [locationInput, setLocationInput] = useState('');

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const response = await fetch('/api/candidate-profile', { cache: 'no-store' });
                const payload = await response.json();

                if (!response.ok) {
                    throw new Error(payload.error || 'Failed to load onboarding data');
                }

                setForm(payload);
                setStep(getFirstIncompleteStep(payload));
            } catch (err) {
                const message = err instanceof Error ? err.message : 'Failed to load onboarding data';
                setError(message);
            } finally {
                setIsLoading(false);
            }
        };

        fetchProfile();
    }, []);

    const canContinue = useMemo(() => {
        if (step === 1) {
            return Boolean(form.profile.name.trim() && form.profile.phone.trim() && form.profile.location.trim());
        }

        if (step === 2) {
            return Boolean(
                form.candidateProfile.headline.trim() &&
                form.candidateProfile.skills.length > 0 &&
                form.candidateProfile.education.trim()
            );
        }

        return Boolean(
            form.candidateProfile.salary_min !== null &&
            form.candidateProfile.salary_max !== null &&
            form.candidateProfile.preferred_locations.length > 0 &&
            form.candidateProfile.job_type
        );
    }, [form, step]);

    const updateProfile = (field: 'name' | 'phone' | 'location', value: string) => {
        setForm((prev) => ({
            ...prev,
            profile: {
                ...prev.profile,
                [field]: value,
            },
        }));
    };

    const updateCandidate = (field: keyof CandidateSettingsBundle['candidateProfile'], value: unknown) => {
        setForm((prev) => ({
            ...prev,
            candidateProfile: {
                ...prev.candidateProfile,
                [field]: value,
            },
        }));
    };

    const addSkill = (event: React.FormEvent) => {
        event.preventDefault();
        const nextSkill = skillInput.trim();
        if (!nextSkill || form.candidateProfile.skills.includes(nextSkill)) {
            return;
        }

        updateCandidate('skills', [...form.candidateProfile.skills, nextSkill]);
        setSkillInput('');
    };

    const removeSkill = (skill: string) => {
        updateCandidate('skills', form.candidateProfile.skills.filter((item) => item !== skill));
    };

    const addLocation = (event: React.FormEvent) => {
        event.preventDefault();
        const nextLocation = locationInput.trim();
        if (!nextLocation || form.candidateProfile.preferred_locations.includes(nextLocation)) {
            return;
        }

        updateCandidate('preferred_locations', [...form.candidateProfile.preferred_locations, nextLocation]);
        setLocationInput('');
    };

    const removeLocation = (location: string) => {
        updateCandidate(
            'preferred_locations',
            form.candidateProfile.preferred_locations.filter((item) => item !== location),
        );
    };

    const handleContinue = async () => {
        if (!user?.id) {
            setError('You must be logged in before finishing setup.');
            return;
        }

        if (step < 3) {
            setStep((prev) => (prev + 1) as Step);
            return;
        }

        setIsSaving(true);
        setError('');

        try {
            const response = await fetch('/api/candidate-profile', {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                },
                body: JSON.stringify(form),
            });

            const payload = await response.json();
            if (!response.ok) {
                throw new Error(payload.error || 'Failed to save onboarding');
            }

            const roleId = payload.profile?.role_id || form.profile.role_id || user?.role_id || 'candidate';
            router.push(`/dashboard/candidate/${roleId}`);
        } catch (err) {
            const message = err instanceof Error ? err.message : 'Failed to save onboarding';
            setError(message);
        } finally {
            setIsSaving(false);
        }
    };

    if (isLoading) {
        return <div className={styles.card}>Loading onboarding...</div>;
    }

    return (
        <div className={styles.card}>
            <OnboardingStepper currentStep={step} steps={STEP_LABELS} />

            <div className={styles.header}>
                <h1 className={styles.title}>Complete your candidate profile</h1>
                <p className={styles.subtitle}>We&apos;ll save this to your TalentMesh profile so settings and onboarding stay in sync.</p>
            </div>

            {error && (
                <div style={{ color: '#b91c1c', fontSize: '0.8rem', background: '#fef2f2', border: '1px solid #fecaca', borderRadius: 10, padding: '0.75rem 0.85rem' }}>
                    {error}
                </div>
            )}

            {step === 1 && (
                <div className={styles.section}>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Name</label>
                        <input className={styles.optionalInput} value={form.profile.name} onChange={(event) => updateProfile('name', event.target.value)} placeholder="Your full name" />
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Phone</label>
                        <input className={styles.optionalInput} value={form.profile.phone} onChange={(event) => updateProfile('phone', event.target.value)} placeholder="+1 555 123 4567" />
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Location</label>
                        <input className={styles.optionalInput} value={form.profile.location} onChange={(event) => updateProfile('location', event.target.value)} placeholder="City, Country" />
                    </div>
                </div>
            )}

            {step === 2 && (
                <div className={styles.section}>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Headline</label>
                        <input className={styles.optionalInput} value={form.candidateProfile.headline} onChange={(event) => updateCandidate('headline', event.target.value)} placeholder="Frontend Developer" />
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Skills</label>
                        <div className={styles.tagWrap}>
                            {form.candidateProfile.skills.map((skill) => (
                                <span key={skill} className={`${styles.tag} ${styles.tagSelected}`}>
                                    {skill}
                                    <button type="button" className={styles.removeTag} onClick={() => removeSkill(skill)}>x</button>
                                </span>
                            ))}
                        </div>
                        <form onSubmit={addSkill} className={styles.customField}>
                            <input className={styles.optionalInput} value={skillInput} onChange={(event) => setSkillInput(event.target.value)} placeholder="Add a skill" />
                            <button type="submit" className={styles.addBtn} disabled={!skillInput.trim()}>Add</button>
                        </form>
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Experience (years)</label>
                        <input type="number" className={styles.optionalInput} value={form.candidateProfile.experience_years ?? ''} onChange={(event) => updateCandidate('experience_years', event.target.value === '' ? null : Number(event.target.value))} placeholder="3" />
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Education</label>
                        <textarea className={styles.optionalInput} value={form.candidateProfile.education} onChange={(event) => updateCandidate('education', event.target.value)} placeholder="B.Tech in Computer Science" rows={4} style={{ resize: 'vertical' }} />
                    </div>
                </div>
            )}

            {step === 3 && (
                <div className={styles.section}>
                    {form.candidateProfile.resume_url && (
                        <div style={{ background: '#eff6ff', border: '1px solid #bfdbfe', borderRadius: 10, padding: '0.75rem 0.85rem', fontSize: '0.78rem', color: '#1d4ed8' }}>
                            Resume detected on your profile. If headline or skills were empty, we auto-filled lightweight suggestions from it.
                        </div>
                    )}
                    <div className={styles.salaryGrid}>
                        <div className={styles.fieldGroup}>
                            <label className={styles.label}>Salary Min</label>
                            <input type="number" className={styles.optionalInput} value={form.candidateProfile.salary_min ?? ''} onChange={(event) => updateCandidate('salary_min', event.target.value === '' ? null : Number(event.target.value))} placeholder="50000" />
                        </div>
                        <div className={styles.fieldGroup}>
                            <label className={styles.label}>Salary Max</label>
                            <input type="number" className={styles.optionalInput} value={form.candidateProfile.salary_max ?? ''} onChange={(event) => updateCandidate('salary_max', event.target.value === '' ? null : Number(event.target.value))} placeholder="90000" />
                        </div>
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Preferred Locations</label>
                        <div className={styles.tagWrap}>
                            {form.candidateProfile.preferred_locations.map((location) => (
                                <span key={location} className={`${styles.tag} ${styles.tagSelected}`}>
                                    {location}
                                    <button type="button" className={styles.removeTag} onClick={() => removeLocation(location)}>x</button>
                                </span>
                            ))}
                        </div>
                        <form onSubmit={addLocation} className={styles.customField}>
                            <input className={styles.optionalInput} value={locationInput} onChange={(event) => setLocationInput(event.target.value)} placeholder="Add a preferred location" />
                            <button type="submit" className={styles.addBtn} disabled={!locationInput.trim()}>Add</button>
                        </form>
                    </div>
                    <div className={styles.fieldGroup}>
                        <label className={styles.label}>Job Type</label>
                        <select className={styles.optionalInput} value={form.candidateProfile.job_type} onChange={(event) => updateCandidate('job_type', event.target.value)}>
                            <option value="">Select job type</option>
                            {JOB_TYPES.map((jobType) => (
                                <option key={jobType} value={jobType}>{jobType}</option>
                            ))}
                        </select>
                    </div>
                </div>
            )}

            <div className={styles.actions}>
                <button className={styles.backBtn} onClick={() => setStep((prev) => (prev - 1) as Step)} disabled={step === 1 || isSaving} type="button">
                    Back
                </button>
                <button className={styles.nextBtn} onClick={handleContinue} disabled={!canContinue || isSaving} type="button">
                    {step === 3 ? (isSaving ? 'Saving...' : 'Finish Setup') : 'Continue'}
                </button>
            </div>
        </div>
    );
}

"use client";
import React, { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import { insforge } from '@/lib/insforge';
import { OnboardingStepper } from '@/components/onboarding/OnboardingStepper';
import styles from '../../onboarding.module.css';

const SKILLS = [
    'JavaScript', 'TypeScript', 'React', 'Next.js', 'Node.js', 'Python',
    'Java', 'C++', 'Go', 'Rust', 'SQL', 'MongoDB',
    'AWS', 'Docker', 'Kubernetes', 'GraphQL', 'REST APIs', 'Git',
    'Figma', 'Adobe XD', 'UI/UX', 'HTML/CSS', 'Tailwind',
    'Machine Learning', 'Data Analysis', 'Excel', 'Tableau', 'Power BI',
    'SEO', 'Content Writing', 'Social Media', 'Google Ads', 'Salesforce',
    'Agile', 'Communication', 'Leadership',
];

export default function CandidateSkills() {
    const { user } = useAuth();
    const [selected, setSelected] = useState<string[]>([]);
    const [customSkill, setCustomSkill] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const router = useRouter();

    useEffect(() => {
        const fetchInitialData = async () => {
            if (!user) return;
            const { data, error } = await insforge.database
                .from('candidate_profiles')
                .select('skills')
                .eq('id', user.id)
                .single();

            if (data?.skills) {
                setSelected(data.skills);
            }
        };
        fetchInitialData();
    }, [user]);

    const toggle = (skill: string) => {
        setSelected(prev =>
            prev.includes(skill) ? prev.filter(x => x !== skill) : [...prev, skill]
        );
    };

    const addCustomSkill = (e: React.FormEvent) => {
        e.preventDefault();
        if (customSkill.trim() && !selected.includes(customSkill.trim())) {
            setSelected(prev => [...prev, customSkill.trim()]);
            setCustomSkill('');
        }
    };

    const handleContinue = async () => {
        if (!user) return;
        if (selected.length < 3) return;

        setIsLoading(true);
        try {
            const { error } = await insforge.database
                .from('candidate_profiles')
                .upsert({
                    id: user.id,
                    skills: selected,
                });

            if (error) throw error;
            router.push('/onboarding/candidate/interests');
        } catch (err) {
            console.error('Error saving skills:', err);
            alert('Failed to save skills. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.card}>
            <OnboardingStepper currentStep={1} />

            <div className={styles.header}>
                <h1 className={styles.title}>Your skills</h1>
                <p className={styles.subtitle}>Select at least 3 skills that match your expertise</p>
            </div>

            <div className={styles.tagWrap}>
                {SKILLS.map(skill => (
                    <button
                        key={skill}
                        type="button"
                        className={`${styles.tag} ${selected.includes(skill) ? styles.tagSelected : ''}`}
                        onClick={() => toggle(skill)}
                    >
                        {skill}
                    </button>
                ))}
                {/* Dynamically added custom skills */}
                {selected.filter(s => !SKILLS.includes(s)).map(skill => (
                    <button
                        key={skill}
                        type="button"
                        className={`${styles.tag} ${styles.tagSelected}`}
                        onClick={() => toggle(skill)}
                    >
                        {skill} (custom)
                    </button>
                ))}
            </div>

            <form onSubmit={addCustomSkill} className={styles.customField}>
                <input
                    type="text"
                    className={styles.optionalInput}
                    placeholder="Add a custom skill..."
                    value={customSkill}
                    onChange={e => setCustomSkill(e.target.value)}
                />
                <button type="submit" className={styles.addBtn} disabled={!customSkill.trim()}>Add</button>
            </form>

            <p className={styles.counter}>{selected.length} skills selected (min. 3)</p>

            <div className={styles.actions}>
                <button className={styles.backBtn} onClick={() => router.push('/signup')}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" /></svg>
                    Back
                </button>
                <button 
                    className={styles.nextBtn} 
                    onClick={handleContinue} 
                    disabled={selected.length < 3 || isLoading}
                >
                    {isLoading ? 'Saving...' : 'Continue'}
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>
                </button>
            </div>
        </div>
    );
}

"use client";
import React from 'react';
import styles from './onboarding.module.css';

export default function OnboardingLayout({ children }: { children: React.ReactNode }) {
    return (
        <div className={styles.page}>
            <div className={styles.bgGlow1} />
            <div className={styles.bgGlow2} />
            <div className={styles.gridOverlay} />
            {children}
        </div>
    );
}

/* ============================
   ONBOARDING — Shared Styles
   ============================ */

.page {
    width: 100vw;
    height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    background: #f8fafc;
    position: relative;
    overflow: hidden;
    font-family: var(--font-inter), -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.bgGlow1 {
    position: absolute;
    top: -12%;
    right: -8%;
    width: 480px;
    height: 480px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.07) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 20s ease-in-out infinite alternate;
}

.bgGlow2 {
    position: absolute;
    bottom: -12%;
    left: -8%;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.05) 0%, transparent 65%);
    border-radius: 50%;
    pointer-events: none;
    animation: glowPulse 16s ease-in-out infinite alternate-reverse;
}

@keyframes glowPulse {
    0% {
        transform: scale(1);
        opacity: 0.7;
    }

    100% {
        transform: scale(1.15);
        opacity: 1;
    }
}

.gridOverlay {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(0, 0, 0, 0.02) 1px, transparent 1px),
        linear-gradient(90deg, rgba(0, 0, 0, 0.02) 1px, transparent 1px);
    background-size: 40px 40px;
    pointer-events: none;
}

/* Card */
.card {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 520px;
    background: #ffffff;
    border: 1px solid #e5e7eb;
    border-radius: 20px;
    padding: 2rem 2.25rem;
    box-shadow:
        0 4px 6px -1px rgba(0, 0, 0, 0.03),
        0 10px 30px -5px rgba(0, 0, 0, 0.06);
    display: flex;
    flex-direction: column;
    gap: 1.25rem;
    animation: cardEnter 0.5s ease-out;
}

@keyframes cardEnter {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.98);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

/* Stepper */
.stepper {
    display: flex;
    align-items: center;
    gap: 0;
}

.stepDot {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 700;
    border: 2px solid #e2e8f0;
    background: #f1f5f9;
    color: #94a3b8;
    transition: all 0.3s ease;
    flex-shrink: 0;
}

.stepDotActive {
    border-color: var(--primary-blue);
    background: var(--primary-blue);
    color: white;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.stepDotDone {
    border-color: #10b981;
    background: #10b981;
    color: white;
}

.stepLine {
    flex: 1;
    height: 2px;
    background: #e2e8f0;
    margin: 0 0.35rem;
    transition: background 0.3s ease;
}

.stepLineActive {
    background: var(--primary-blue);
}

.stepLineDone {
    background: #10b981;
}

/* Header */
.header {
    text-align: center;
}

.title {
    font-size: 1.4rem;
    font-weight: 800;
    color: #0f172a;
    letter-spacing: -0.02em;
    margin-bottom: 0.25rem;
}

.subtitle {
    font-size: 0.82rem;
    color: #94a3b8;
}

/* Category / Chip Grid */
.chipGrid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 0.5rem;
}

.chip {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.6rem 0.5rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 10px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #374151;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
    text-align: center;
}

.chip:hover {
    border-color: #66b3ff;
    background: #f0f7ff;
}

.chipSelected {
    border-color: var(--primary-blue);
    background: #e6f2ff;
    color: var(--primary-blue);
    box-shadow: 0 0 0 2px rgba(0, 123, 255, 0.1);
}

.chipIcon {
    font-size: 1rem;
}

/* Skill Tags */
.tagWrap {
    display: flex;
    flex-wrap: wrap;
    gap: 0.4rem;
}

.tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.4rem 0.75rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 20px;
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
    cursor: pointer;
    transition: all 0.2s ease;
    font-family: inherit;
}

.tag:hover {
    border-color: #66b3ff;
    color: #374151;
}

.tagSelected {
    border-color: var(--primary-blue);
    background: var(--primary-blue);
    color: white;
}

/* Upload Area */
.uploadArea {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 0.6rem;
    padding: 2rem;
    border: 2px dashed #d1d5db;
    border-radius: 14px;
    background: #fafafa;
    cursor: pointer;
    transition: all 0.25s ease;
    text-align: center;
}

.uploadArea:hover {
    border-color: var(--primary-blue);
    background: #f0f7ff;
}

.uploadAreaActive {
    border-color: #10b981;
    background: #f0fdf4;
}

.uploadIcon {
    color: #94a3b8;
    transition: color 0.2s;
}

.uploadArea:hover .uploadIcon {
    color: var(--primary-blue);
}

.uploadAreaActive .uploadIcon {
    color: #10b981;
}

.uploadText {
    font-size: 0.82rem;
    color: #64748b;
    font-weight: 500;
}

.uploadHint {
    font-size: 0.7rem;
    color: #94a3b8;
}

.uploadedFile {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.55rem 0.85rem;
    background: #f0fdf4;
    border: 1px solid #bbf7d0;
    border-radius: 8px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #166534;
}

/* Optional field */
.optionalField {
    display: flex;
    flex-direction: column;
    gap: 0.3rem;
}

.optionalLabel {
    font-size: 0.75rem;
    font-weight: 600;
    color: #374151;
}

.optionalInput {
    width: 100%;
    padding: 0.6rem 0.85rem;
    background: #f9fafb;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #0f172a;
    font-size: 0.84rem;
    font-family: inherit;
    outline: none;
    transition: all 0.2s ease;
}

.optionalInput::placeholder {
    color: #b0b8c4;
}

.optionalInput:focus {
    background: #ffffff;
    border-color: var(--primary-blue);
    box-shadow: 0 0 0 3px rgba(0, 123, 255, 0.08);
}

/* Sections & Grids */
.section {
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
    margin-bottom: 0.5rem;
}

.sectionTitle {
    font-size: 0.9rem;
    font-weight: 700;
    color: #475569;
    letter-spacing: -0.01em;
}

.salaryGrid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.fieldGroup {
    display: flex;
    flex-direction: column;
    gap: 0.35rem;
}

.label {
    font-size: 0.75rem;
    font-weight: 600;
    color: #64748b;
}

/* Custom Add Field */
.customField {
    display: flex;
    gap: 0.5rem;
    margin-top: 0.5rem;
}

.addBtn {
    padding: 0.6rem 1rem;
    background: #f1f5f9;
    border: 1.5px solid #e2e8f0;
    border-radius: 9px;
    color: #475569;
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
}

.addBtn:hover:not(:disabled) {
    background: #e2e8f0;
    border-color: #cbd5e1;
}

.addBtn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.removeTag {
    background: none;
    border: none;
    color: currentColor;
    opacity: 0.7;
    margin-left: 0.2rem;
    font-size: 1.1rem;
    cursor: pointer;
    line-height: 1;
    display: flex;
    align-items: center;
}

.removeTag:hover {
    opacity: 1;
}

/* Toggles & Progress */
.remoteToggle {
    margin: 0.5rem 0;
}

.toggleLabel {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    font-size: 0.84rem;
    font-weight: 600;
    color: #334155;
    cursor: pointer;
}

.toggleLabel input[type="checkbox"] {
    width: 18px;
    height: 18px;
    cursor: pointer;
    accent-color: var(--primary-blue);
}

.progressBar {
    width: 100%;
    height: 6px;
    background: #f1f5f9;
    border-radius: 10px;
    overflow: hidden;
    margin-top: 0.5rem;
}

.progressFill {
    height: 100%;
    background: var(--primary-blue);
    transition: width 0.3s ease;
}

/* Actions */
.actions {
    display: flex;
    gap: 0.55rem;
    align-items: center;
}

.backBtn {
    display: flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.65rem 0.95rem;
    background: #ffffff;
    border: 1.5px solid #e5e7eb;
    border-radius: 9px;
    color: #64748b;
    font-size: 0.82rem;
    font-weight: 600;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.2s ease;
    white-space: nowrap;
    flex-shrink: 0;
}

.backBtn:hover {
    background: #f9fafb;
    border-color: #d1d5db;
    color: #374151;
}

.nextBtn {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    flex: 1;
    padding: 0.7rem 1rem;
    background: var(--primary-blue);
    color: white;
    border: none;
    border-radius: 9px;
    font-size: 0.88rem;
    font-weight: 700;
    font-family: inherit;
    cursor: pointer;
    transition: all 0.25s ease;
    box-shadow: 0 2px 8px rgba(0, 123, 255, 0.3);
}

.nextBtn:hover:not(:disabled) {
    background: #0056d6;
    transform: translateY(-1px);
    box-shadow: 0 4px 16px rgba(0, 123, 255, 0.4);
}

.nextBtn:disabled {
    opacity: 0.4;
    cursor: not-allowed;
    box-shadow: none;
}

/* Skip link */
.skipLink {
    text-align: center;
    font-size: 0.72rem;
    color: #94a3b8;
}

.skipBtn {
    background: none;
    border: none;
    color: #94a3b8;
    font-size: 0.72rem;
    font-weight: 600;
    cursor: pointer;
    text-decoration: underline;
    text-underline-offset: 2px;
    font-family: inherit;
    transition: color 0.2s;
}

.skipBtn:hover {
    color: var(--primary-blue);
}

/* Selection counter */
.counter {
    font-size: 0.72rem;
    color: #94a3b8;
    text-align: right;
    font-weight: 500;
}

/* Responsive */
@media (max-width: 560px) {
    .card {
        max-width: 100%;
        margin: 0 0.75rem;
        padding: 1.5rem 1.25rem;
        border-radius: 16px;
    }

    .chipGrid {
        grid-template-columns: repeat(2, 1fr);
    }

    .title {
        font-size: 1.25rem;
    }
}

@media (max-height: 750px) {
    .card {
        gap: 1rem;
        padding: 1.5rem 1.75rem;
    }

    .chipGrid {
        gap: 0.4rem;
    }

    .chip {
        padding: 0.5rem 0.4rem;
        font-size: 0.74rem;
    }

    .uploadArea {
        padding: 1.25rem;
    }
}

"use client";
import React, { useState, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';
import styles from '../../onboarding.module.css';

export default function RecruiterDocuments() {
    const { user } = useAuth();
    const [logo, setLogo] = useState<File | null>(null);
    const [doc, setDoc] = useState<File | null>(null);
    const [website, setWebsite] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const logoRef = useRef<HTMLInputElement>(null);
    const docRef = useRef<HTMLInputElement>(null);
    const router = useRouter();

    const handleFinish = () => {
        setIsLoading(true);
        setTimeout(() => {
            setIsLoading(false);
            router.push(`/dashboard/recruiter/${user?.role_id || ''}`);
        }, 1500);
    };

    return (
        <div className={styles.card}>
            <div className={styles.stepper}>
                <span className={`${styles.stepDot} ${styles.stepDotDone}`}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
                </span>
                <span className={`${styles.stepLine} ${styles.stepLineDone}`} />
                <span className={`${styles.stepDot} ${styles.stepDotDone}`}>
                    <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><polyline points="20 6 9 17 4 12" /></svg>
                </span>
                <span className={`${styles.stepLine} ${styles.stepLineActive}`} />
                <span className={`${styles.stepDot} ${styles.stepDotActive}`}>3</span>
            </div>

            <div className={styles.header}>
                <h1 className={styles.title}>Company documents</h1>
                <p className={styles.subtitle}>Upload your company logo and verification docs</p>
            </div>

            <input type="file" ref={logoRef} onChange={e => e.target.files?.[0] && setLogo(e.target.files[0])} accept="image/*" hidden />
            <input type="file" ref={docRef} onChange={e => e.target.files?.[0] && setDoc(e.target.files[0])} accept=".pdf,.doc,.docx,.jpg,.png" hidden />

            {/* Company Logo */}
            <div
                className={`${styles.uploadArea} ${logo ? styles.uploadAreaActive : ''}`}
                onClick={() => logoRef.current?.click()}
                style={{ padding: '1.25rem' }}
            >
                {logo ? (
                    <>
                        <svg className={styles.uploadIcon} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" /><polyline points="22 4 12 14.01 9 11.01" /></svg>
                        <span className={styles.uploadText}>{logo.name}</span>
                    </>
                ) : (
                    <>
                        <svg className={styles.uploadIcon} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><rect x="3" y="3" width="18" height="18" rx="2" /><circle cx="8.5" cy="8.5" r="1.5" /><polyline points="21 15 16 10 5 21" /></svg>
                        <span className={styles.uploadText}>Upload company logo</span>
                        <span className={styles.uploadHint}>PNG, JPG — recommended 200×200px</span>
                    </>
                )}
            </div>

            {/* Verification Doc */}
            <div
                className={`${styles.uploadArea} ${doc ? styles.uploadAreaActive : ''}`}
                onClick={() => docRef.current?.click()}
                style={{ padding: '1.25rem' }}
            >
                {doc ? (
                    <>
                        <svg className={styles.uploadIcon} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14" /><polyline points="22 4 12 14.01 9 11.01" /></svg>
                        <span className={styles.uploadText}>{doc.name}</span>
                    </>
                ) : (
                    <>
                        <svg className={styles.uploadIcon} width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" /><polyline points="14 2 14 8 20 8" /></svg>
                        <span className={styles.uploadText}>Upload verification document</span>
                        <span className={styles.uploadHint}>Business license, registration — PDF, DOC</span>
                    </>
                )}
            </div>

            <div className={styles.optionalField}>
                <label className={styles.optionalLabel}>Company website (optional)</label>
                <input
                    type="url"
                    className={styles.optionalInput}
                    placeholder="https://yourcompany.com"
                    value={website}
                    onChange={e => setWebsite(e.target.value)}
                />
            </div>

            <div className={styles.actions}>
                <button className={styles.backBtn} onClick={() => router.push('/onboarding/recruiter/skills')}>
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="19" y1="12" x2="5" y2="12" /><polyline points="12 19 5 12 12 5" /></svg>
                    Back
                </button>
                <button className={styles.nextBtn} onClick={handleFinish} disabled={isLoading}>
                    {isLoading ? 'Setting up...' : 'Finish Setup'}
                    {!isLoading && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>}
                </button>
            </div>

            <p className={styles.skipLink}>
                <button className={styles.skipBtn} onClick={() => router.push(`/dashboard/recruiter/${user?.role_id || ''}`)}>Skip for now</button>
            </p>
        </div>
    );
}

"use client";
import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import styles from '../../onboarding.module.css';

const HIRING_CATEGORIES = [
    { id: 'engineering', label: 'Engineering', icon: '💻' },
    { id: 'design', label: 'Design', icon: '🎨' },
    { id: 'marketing', label: 'Marketing', icon: '📣' },
    { id: 'sales', label: 'Sales', icon: '📈' },
    { id: 'finance', label: 'Finance', icon: '💰' },
    { id: 'healthcare', label: 'Healthcare', icon: '🏥' },
    { id: 'customer_support', label: 'Support', icon: '🎧' },
    { id: 'operations', label: 'Operations', icon: '⚙️' },
    { id: 'hr', label: 'HR & People', icon: '🤝' },
    { id: 'data', label: 'Data & AI', icon: '📊' },
    { id: 'product', label: 'Product', icon: '🚀' },
    { id: 'legal', label: 'Legal', icon: '⚖️' },
];

export default function RecruiterInterests() {
    const [selected, setSelected] = useState<string[]>([]);
    const router = useRouter();

    const toggle = (id: string) => {
        setSelected(prev =>
            prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
        );
    };

    return (
        <div className={styles.card}>
            <div className={styles.stepper}>
                <span className={`${styles.stepDot} ${styles.stepDotActive}`}>1</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>2</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>3</span>
            </div>

            <div className={styles.header}>
                <h1 className={styles.title}>Who are you hiring?</h1>
                <p className={styles.subtitle}>Select the roles your company is hiring for</p>
            </div>

            <div className={styles.chipGrid}>
                {HIRING_CATEGORIES.map(cat => (
                    <button
                        key={cat.id}
                        type="button"
                        className={`${styles.chip} ${selected.includes(cat.id) ? styles.chipSelected : ''}`}
                        onClick={() => toggle(cat.id)}
                    >
                        <span className={styles.chipIcon}>{cat.icon}</span>
                        {cat.label}
                    </button>
                ))}
            </div>

            <p className={styles.counter}>{selected.length} selected</p>

            <div className={styles.actions}>
                <button className={styles.nextBtn} onClick={() => router.push('/onboarding/recruiter/skills')} disabled={selected.length === 0}>
                    Continue
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>
                </button>
            </div>
        </div>
    );
}

"use client";
import React, { useState } from 'react';
import { useRouter } from 'next/navigation';
import { completeRecruiterSetup } from '@/lib/api/recruiter';
import styles from '../../onboarding.module.css';

export default function RecruiterSetup() {
    const [formData, setFormData] = useState({
        companyName: '',
        jobTitle: '',
        department: ''
    });
    const [isLoading, setIsLoading] = useState(false);
    const [error, setError] = useState('');
    const router = useRouter();

    const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
        setFormData(prev => ({ ...prev, [e.target.name]: e.target.value }));
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsLoading(true);
        setError('');

        try {
            await completeRecruiterSetup(formData);
            router.push('/onboarding/recruiter/interests');
        } catch (err: any) {
            setError(err.message || 'Failed to save profile. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className={styles.card}>
            <div className={styles.stepper}>
                <span className={`${styles.stepDot} ${styles.stepDotActive}`}>0</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>1</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>2</span>
                <span className={styles.stepLine} />
                <span className={styles.stepDot}>3</span>
            </div>

            <div className={styles.header}>
                <h1 className={styles.title}>Welcome, Recruiter!</h1>
                <p className={styles.subtitle}>Let's set up your professional profile</p>
            </div>

            <form onSubmit={handleSubmit} className={styles.form} style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
                {error && <div style={{ color: '#ef4444', fontSize: '0.85rem', textAlign: 'center', padding: '0.5rem', background: '#fef2f2', borderRadius: '8px' }}>{error}</div>}

                <div className={styles.fieldGroup}>
                    <label className={styles.label}>Company name</label>
                    <div className={styles.inputWrap}>
                        <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><rect x="2" y="7" width="20" height="14" rx="2" /><path d="M16 21V5a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16" /></svg>
                        <input
                            name="companyName"
                            type="text"
                            className={styles.input}
                            placeholder="e.g. Acme Corp"
                            value={formData.companyName}
                            onChange={handleChange}
                            required
                        />
                    </div>
                </div>

                <div className={styles.fieldGroup}>
                    <label className={styles.label}>Your job title</label>
                    <div className={styles.inputWrap}>
                        <svg className={styles.inputIcon} width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2" /><circle cx="12" cy="7" r="4" /></svg>
                        <input
                            name="jobTitle"
                            type="text"
                            className={styles.input}
                            placeholder="e.g. Senior Technical Recruiter"
                            value={formData.jobTitle}
                            onChange={handleChange}
                            required
                        />
                    </div>
                </div>

                <div className={styles.fieldGroup}>
                    <label className={styles.label}>Department</label>
                    <select
                        name="department"
                        className={styles.input}
                        value={formData.department}
                        onChange={handleChange as any}
                        required
                        style={{ appearance: 'none' }}
                    >
                        <option value="">Select Department</option>
                        <option value="hr">Human Resources</option>
                        <option value="engineering">Engineering</option>
                        <option value="operations">Operations</option>
                        <option value="executive">Executive</option>
                        <option value="other">Other</option>
                    </select>
                </div>

                <div className={styles.actions} style={{ marginTop: '1rem' }}>
                    <button className={styles.nextBtn} disabled={isLoading} style={{ width: '100%', justifyContent: 'center' }}>
                        {isLoading ? 'Saving...' : 'Continue to Onboarding'}
                        {!isLoading && <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><line x1="5" y1="12" x2="19" y2="12" /><polyline points="12 5 19 12 12 19" /></svg>}
                    </button>
                </div>
            </form>
        </div>
    );
}

.main {
  min-height: 100vh;
  padding-top: 80px; /* Space for fixed navbar */
  background: var(--white);
  overflow-x: hidden;
}

/* Removed Hero styles as they are now in components/landing/landing.module.css */

.features {
  padding: 8rem 2rem;
  background: var(--white);
}

.sectionHeader {
  text-align: center;
  margin-bottom: 5rem;
}

.sectionTitle {
  font-size: 2.5rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--ink-black);
}

.subtitle {
  font-size: 1.25rem;
  color: var(--deep-space-blue);
  opacity: 0.7;
  max-width: 700px;
  margin-left: auto;
  margin-right: auto;
  line-height: 1.6;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2.5rem;
  max-width: 1200px;
  margin: 0 auto;
}

.featureCard {
  background: var(--white);
  padding: 2.5rem;
  border-radius: 1.5rem;
  border: 1px solid rgba(0, 52, 89, 0.05); /* very light deep space blue */
