  position: relative;
  overflow: hidden;
}

.featureCard:hover {
  transform: translateY(-5px);
  box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.05), 0 10px 10px -5px rgba(0, 0, 0, 0.01);
  border-color: rgba(0, 52, 89, 0.1);
}

.icon {
  width: 3rem;
  height: 3rem;
  background: rgba(0, 168, 232, 0.1);
  color: var(--cerulean);
  border-radius: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
