  margin-bottom: 1.5rem;
}

.cardTitle {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--ink-black);
}

.cardDesc {
  color: var(--deep-space-blue);
  opacity: 0.7;
  line-height: 1.6;
}

.primaryBtn {
  text-decoration: none;
  background: linear-gradient(135deg, var(--cerulean) 0%, var(--fresh-sky) 100%);
