  padding: 1rem 2.5rem;
  border-radius: 0.75rem;
  font-weight: 600;
  font-size: 1.125rem;
  transition: all 0.3s ease;
  box-shadow: 0 10px 15px -3px rgba(0, 126, 167, 0.2), 0 4px 6px -2px rgba(0, 126, 167, 0.1);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.primaryBtn:hover {
  transform: translateY(-2px);
  box-shadow: 0 20px 25px -5px rgba(0, 126, 167, 0.3), 0 10px 10px -5px rgba(0, 126, 167, 0.2);
}

.secondaryBtn {
  text-decoration: none;
