  color: var(--deep-space-blue);
  padding: 1rem 2.5rem;
  border-radius: 0.75rem;
  font-weight: 600;
  font-size: 1.125rem;
  transition: all 0.3s ease;
  border: 1px solid rgba(0, 52, 89, 0.1);
