}

.newsletterBtn:hover {
  background: #0069d9;
  transform: translateY(-1px);
}

.column {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.column h4 {
  color: var(--white);
  font-size: 1.125rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  font-family: var(--font-jakarta);
