}

.column a {
  color: #94a3b8;
  text-decoration: none;
  transition: color 0.2s ease;
  font-size: 0.95rem;
  width: fit-content;
}

.column a:hover {
  color: var(--primary-blue);
  transform: translateX(4px);
}

.bottom {
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding-top: 2rem;
  text-align: center;
  font-size: 0.875rem;
  color: #64748b;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 1rem;
}

.socials {
  display: flex;
  gap: 1rem;
}

.socialIcon {
  width: 2rem;
  height: 2rem;
  background: rgba(255, 255, 255, 0.05);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #cbd5e1;
