}

/* Floating orb 1 */
.decor1 {
    position: absolute;
    top: -15%;
    right: -8%;
    width: 500px;
    height: 500px;
    background: radial-gradient(circle, rgba(0, 123, 255, 0.18) 0%, rgba(0, 123, 255, 0.05) 40%, transparent 70%);
    border-radius: 50%;
    z-index: 3;
    animation: floatOrb1 8s ease-in-out infinite;
    filter: blur(20px);
}

/* Floating orb 2 */
.decor2 {
    position: absolute;
    bottom: -20%;
    left: -8%;
    width: 400px;
    height: 400px;
    background: radial-gradient(circle, rgba(129, 140, 248, 0.15) 0%, rgba(129, 140, 248, 0.04) 40%, transparent 70%);
    border-radius: 50%;
    z-index: 3;
    animation: floatOrb2 10s ease-in-out infinite;
    filter: blur(20px);
}

@keyframes floatOrb1 {

    0%,
    100% {
        transform: translate(0, 0) scale(1);
    }

    50% {
        transform: translate(-30px, 20px) scale(1.05);
    }
}

@keyframes floatOrb2 {

    0%,
    100% {
        transform: translate(0, 0) scale(1);
    }

    50% {
        transform: translate(20px, -30px) scale(1.08);
    }
}

@media (max-width: 768px) {
    .header {
        padding: 8rem 1.5rem 5rem;
    }

    .decor1,
    .decor2 {
        width: 250px;
        height: 250px;
    }
}

