-- ============================================================
-- Fix: Infinite Recursion in Jobs & Applications RLS Policies
-- Run the ENTIRE script at once in InsForge SQL Editor
-- ============================================================

-- Step 1: Drop ALL policies on jobs and applications tables
DO $$
DECLARE
    pol record;
BEGIN
    FOR pol IN 
        SELECT policyname, tablename 
        FROM pg_policies 
        WHERE schemaname = 'public' AND tablename IN ('jobs', 'applications')
    LOOP
        EXECUTE format('DROP POLICY IF EXISTS %I ON public.%I', pol.policyname, pol.tablename);
        RAISE NOTICE 'Dropped policy: % on %', pol.policyname, pol.tablename;
    END LOOP;
END $$;

-- Step 2: Re-enable RLS on both tables
ALTER TABLE public.jobs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.applications ENABLE ROW LEVEL SECURITY;

-- Step 3: Jobs policies (simple, no cross-table references)
CREATE POLICY "jobs_select_approved" ON public.jobs
    FOR SELECT USING (status = 'active' AND is_approved = true);

CREATE POLICY "jobs_select_own" ON public.jobs
    FOR SELECT USING (auth.uid() = recruiter_id);

CREATE POLICY "jobs_insert_own" ON public.jobs
    FOR INSERT WITH CHECK (auth.uid() = recruiter_id);

CREATE POLICY "jobs_update_own" ON public.jobs
    FOR UPDATE USING (auth.uid() = recruiter_id);

CREATE POLICY "jobs_delete_own" ON public.jobs
    FOR DELETE USING (auth.uid() = recruiter_id);

-- Step 4: Applications policies (safe - candidate checks only)
CREATE POLICY "apps_select_own" ON public.applications
    FOR SELECT USING (auth.uid() = candidate_id);

CREATE POLICY "apps_insert_own" ON public.applications
    FOR INSERT WITH CHECK (auth.uid() = candidate_id);

CREATE POLICY "apps_update_own" ON public.applications
    FOR UPDATE USING (auth.uid() = candidate_id);

-- Step 5: Employers can view applications for their posted jobs
-- Uses a direct subquery on jobs.recruiter_id - no circular reference
CREATE POLICY "apps_recruiter_view" ON public.applications
    FOR SELECT USING (
        EXISTS (
            SELECT 1 FROM public.jobs j
            WHERE j.id = applications.job_id
            AND j.recruiter_id = auth.uid()
        )
    );

CREATE POLICY "apps_recruiter_update" ON public.applications
    FOR UPDATE USING (
        EXISTS (
            SELECT 1 FROM public.jobs j
            WHERE j.id = applications.job_id
            AND j.recruiter_id = auth.uid()
        )
    );

"use server";

import { headers } from 'next/headers';
import { insforgeAdmin } from '@/lib/insforge-admin';

export async function logAction(params: {
  adminId: string;
  action: string;
  tableName?: string;
  recordId?: string;
  oldData?: object;
  newData?: object;
  status?: 'success' | 'failure';
}) {
    if (!insforgeAdmin) return;

    const headersList = await headers();
    const ip = headersList.get('x-forwarded-for') ?? headersList.get('x-real-ip') ?? 'unknown';
    const userAgent = headersList.get('user-agent') ?? 'unknown';

    try {
        await insforgeAdmin.database.from('audit_logs').insert({
            actor_id: params.adminId,
            action: params.action,
            table_name: params.tableName,
            record_id: params.recordId,
            old_data: params.oldData ? params.oldData : null,
            new_data: params.newData ? params.newData : null,
            ip_address: ip,
            user_agent: userAgent,
            status: params.status || 'success'
        });
    } catch (error) {
        console.error('Failed to log admin action:', error);
    }
}

import { insforgeAdmin } from '../insforge-admin';

/**
 * Server-side function to invite a new administrator.
 * Requires INSFORGE_SERVICE_KEY to be set in environment variables.
 */
export async function inviteAdmin(email: string, invitedByAdminId: string): Promise<{ success: boolean, error?: string }> {
  if (!insforgeAdmin) {
    return { success: false, error: 'Internal Error: Admin client not initialized (Missing SERVICE_KEY)' };
  }

  try {
    // 1. Check if email is already registered in profiles
    const { data: existing } = await insforgeAdmin.database
      .from('profiles')
      .select('id')
      .eq('email', email)
      .maybeSingle();

    if (existing) {
      return { success: false, error: 'An account with this email already exists' };
    }

    // 2. Create the user account with a secure temporary password
    // Since InsForge SDK doesn't expose an admin.inviteUserByEmail API,
    // we sign them up and trigger a password reset email which serves as the invite.
    const tempPassword = crypto.randomUUID() + crypto.randomUUID().toUpperCase() + 'aA1!@';

    const { data, error } = await insforgeAdmin.auth.signUp({
      email,
      password: tempPassword,
      name: email.split('@')[0],
    });

    if (error) {
      return { success: false, error: error.message };
    }

    const user = data?.user;
    if (!user) {
      return { success: false, error: 'Failed to retrieve user data after invitation.' };
    }

    // Trigger a password reset email so the user can set their own password 
    // and log in (acting as an invite email)
    await insforgeAdmin.auth.sendResetPasswordEmail({ email });

    // 3. Record the invite in admin_invites table
    const { error: insertError } = await insforgeAdmin.database
      .from('admin_invites')
      .upsert({
        email,
        role: 'super_admin',
        invited_by: invitedByAdminId,
        token: user.id, // using user ID as token reference
        expires_at: new Date(Date.now() + 48 * 60 * 60 * 1000).toISOString()
      }, { onConflict: 'email' });

    if (insertError) {
      console.error('Error recording admin invite:', insertError.message);
      // We don't fail the whole operation if the log insert fails, but it's good to know
    }

    // 4. Update ADMIN_EMAILS env var note
    console.log('ACTION REQUIRED: Add ' + email + ' to ADMIN_EMAILS env var in Vercel/Production environment.');

    return { success: true };

  } catch (err: any) {
    console.error('Unexpected error in inviteAdmin:', err);
    return { success: false, error: err.message || 'An unexpected error occurred' };
  }
}

import crypto from 'crypto';

/**
 * Validates the admin invite token against the environment variable.
 * Only runs on the server.
 */
export function validateAdminToken(token: string): boolean {
  if (typeof window !== 'undefined') {
    throw new Error('validateAdminToken must only be called on the server');
  }

  const secret = process.env.ADMIN_INVITE_TOKEN;
  if (!secret) return false;

  return token === secret;
}

/**
 * Checks if the provided email is in the admin whitelist.
 */
export function isAdminEmail(email: string): boolean {
  const adminEmails = (process.env.NEXT_PUBLIC_ADMIN_EMAILS || process.env.ADMIN_EMAILS || '')
    .split(',')
    .map(e => e.trim().toLowerCase());

  return adminEmails.includes(email.toLowerCase());
}

/**
 * Generates a new random admin token for setup.
 * Used only in dev/seed scripts.
 */
export function generateAdminToken(): string {
  const token = crypto.randomUUID();
  console.log('Generated ADMIN_INVITE_TOKEN:', token);
  return token;
}

import { insforgeAdmin } from '@/lib/insforge-admin';

/**
 * lib/api/admin.ts
 * CRITICAL: This file MUST only be imported in Server Components or API Routes.
 * It uses the service role key via insforgeAdmin.
 */

if (typeof window !== 'undefined') {
  throw new Error('lib/api/admin.ts can only be used on the server.');
}

export interface AdminFilters {
  page?: number;
  status?: 'all' | 'active' | 'draft' | 'pending' | 'closed' | 'paused';
  search?: string;
  is_approved?: boolean;
}

/**
 * Fetches all applications with detailed job and candidate joins.
 */
export async function getAllApplications(filters: AdminFilters = {}) {
  if (!insforgeAdmin) throw new Error('Admin client not initialized');
  const { page = 0, status, search } = filters;
  const start = page * 50; // Increased limit for admin review
  const end = (page + 1) * 50 - 1;

  let query = insforgeAdmin.database
    .from('applications')
    .select(`
      *,
      jobs (
        id,
        title,
        companies (
          name
        )
      ),
      profiles!applications_candidate_id_fkey (
        id,
        name,
        email,
        avatar_url,
        candidate_profiles (
          headline,
          skills,
          experience_years
        )
      )
    `)
    .order('applied_at', { ascending: false });

  if (status && status !== 'all') {
    query = query.eq('status', status);
  }

  const { data, error } = await query.range(start, end);

  if (error) throw new Error(`Admin fetch failed: ${error.message}`);
  return data;
}

/**
 * Gets aggregated application statistics.
 */
export async function getApplicationStats() {
  if (!insforgeAdmin) throw new Error('Admin client not initialized');

  const { data, error } = await insforgeAdmin.database
    .from('applications')
    .select('status');

  if (error) throw new Error(`Stats fetch failed: ${error.message}`);

  const stats = {
    total: data.length,
    applied: 0,
    reviewing: 0,
    shortlisted: 0,
    interview: 0,
    offer: 0,
    rejected: 0
  };

  data.forEach((app: any) => {
    const s = app.status?.toLowerCase();
    if (s && s in stats) {
      (stats as any)[s]++;
    }
  });

  return stats;
}

/**
 * Fetches all jobs regardless of status or approval.
 */
export async function getAllJobs(filters: AdminFilters = {}) {
  if (!insforgeAdmin) throw new Error('Admin client not initialized');
  const { page = 0, status, search, is_approved } = filters;
  const start = page * 20;
  const end = (page + 1) * 20 - 1;

  let query = insforgeAdmin.database
    .from('jobs')
    .select('*, companies(name), profiles:recruiter_id(name)')
    .order('created_at', { ascending: false });

  if (status && status !== 'all') {
    if (status === 'pending') {
      query = query.eq('is_approved', false);
    } else {
      query = query.eq('status', status);
    }
  }

  if (is_approved !== undefined) {
    query = query.eq('is_approved', is_approved);
  }

  if (search) {
    query = query.ilike('title', `%${search}%`);
  }

  const { data, error } = await query.range(start, end);

  if (error) throw new Error(`Admin fetch failed: ${error.message}`);
  return data;
}

/**
 * Fetches all candidate profiles.
 */
export async function getAllCandidates(filters: AdminFilters = {}) {
  if (!insforgeAdmin) throw new Error('Admin client not initialized');
  const { page = 0 } = filters;
  const start = page * 20;
  const end = (page + 1) * 20 - 1;

  const { data, error } = await insforgeAdmin.database
    .from('profiles')
    .select('*, candidate_profiles(*)')
    .eq('role', 'candidate')
