export type JobStatus = 'draft' | 'active' | 'closed';

export interface JobFilters {
  search?: string;
  type?: string;
  location?: string;
  page?: number;
}

export interface CreateJobInput {
  company_id: string;
  recruiter_id: string;
  title: string;
  description: string;
  requirements?: string[];
  skills_required?: string[];
  type?: string;
  location?: string;
  salary_min?: number;
  salary_max?: number;
  currency?: string;
  experience_min?: number;
  experience_max?: number;
  department?: string;
}

export interface Job {
  id: string;
  title: string;
  description: string;
  requirements: string[] | null;
  skills_required: string[] | null;
  type: string;
  location: string;
  salary_min: number;
  salary_max: number;
  currency: string;
  experience_min: number | null;
  experience_max: number | null;
  department: string | null;
  status: JobStatus;
  is_approved: boolean;
  views_count: number;
  applications_count: number;
  created_at: string;
  companies: {
    name: string;
    logo_url: string;
    industry: string;
  };
}

/**
 * Fetches approved and active jobs with pagination and filters.
 */
export async function getApprovedJobs(filters: JobFilters = {}): Promise<Job[]> {
  const { search, type, location, page = 0 } = filters;
  const start = page * 20;
  const end = (page + 1) * 20 - 1;

  let query = insforge.database
    .from('jobs')
    .select('*, companies(name, logo_url, industry)')
    .eq('is_approved', true)
    .eq('status', 'active');

  if (search) {
    query = query.filter('fts', '@@', `plainto_tsquery('${search}')`);
  }

  if (type) {
    query = query.eq('type', type);
  }

  if (location) {
    query = query.eq('location', location);
  }

  const { data, error } = await query
    .order('created_at', { ascending: false })
    .range(start, end);

  if (error) {
    throw new Error(`Failed to fetch jobs: ${error.message}`);
  }

  return data as unknown as Job[];
}

/**
 * Fetches a single job by ID and increments its views count.
 */
export async function getJobById(id: string): Promise<Job> {
  const { data, error } = await insforge.database
    .from('jobs')
    .select('*, companies(*)')
    .eq('id', id)
    .single();

  if (error || !data) {
    throw new Error(`Job not found: ${error?.message || 'Unknown error'}`);
  }

  // Fire and forget increment view count
  insforge.database.from('jobs')
    .update({ views_count: (data.views_count || 0) + 1 })
    .eq('id', id)
    .then(({ error: incError }) => {
      if (incError) console.error('Failed to increment view count:', incError.message);
    });

  return data as unknown as Job;
}

/**
 * Creates a new job in draft status.
 */
export async function createJob(data: CreateJobInput): Promise<Job> {
  const { data: newJob, error } = await insforge.database
    .from('jobs')
    .insert({
      ...data,
      status: 'draft',
      is_approved: false
    })
    .select()
    .single();

  if (error) {
    throw new Error(`Failed to create job: ${error.message}`);
  }

  return newJob as unknown as Job;
}

/**
 * Updates an existing job.
 */
export async function updateJob(id: string, data: Partial<CreateJobInput>): Promise<Job> {
  const { data: updatedJob, error } = await insforge.database
    .from('jobs')
    .update(data)
    .eq('id', id)
    .select()
    .single();

  if (error) {
    throw new Error(`Failed to update job: ${error.message}`);
  }

  return updatedJob as unknown as Job;
}

/**
 * Updates the status of a job.
 */
export async function updateJobStatus(id: string, status: JobStatus): Promise<void> {
  const { error } = await insforge.database
    .from('jobs')
    .update({ status })
    .eq('id', id);

  if (error) {
    throw new Error(`Failed to update job status: ${error.message}`);
  }
}

/**
 * Soft deletes a job by setting its status to closed.
 */
export async function deleteJob(id: string): Promise<void> {
  return updateJobStatus(id, 'closed');
}

import { insforge } from '@/lib/insforge';

export interface Message {
  id: string;
  sender_id: string;
  receiver_id: string;
  content: string;
  is_read: boolean;
  job_id: string | null;
  created_at: string;
}

export interface Conversation {
  partner_id: string;
  partner_name: string;
  partner_avatar: string | null;
  last_message: string;
  last_message_time: string;
  unread_count: number;
  last_message_sender_id: string;
}

export const getConversations = async (userId: string): Promise<Conversation[]> => {
  // We'll fetch the latest messages and manually group them for simplicity and performance on typical data sizes
  const { data, error } = await insforge.database
    .from('messages')
    .select(`
      *,
      sender:sender_id(id, name, avatar_url),
      receiver:receiver_id(id, name, avatar_url)
    `)
    .or(`sender_id.eq.${userId},receiver_id.eq.${userId}`)
    .order('created_at', { ascending: false });

  if (error || !data) return [];

  const conversationMap = new Map<string, Conversation>();

  data.forEach((msg: any) => {
    const partner = msg.sender_id === userId ? msg.receiver : msg.sender;
    if (!partner) return;

    if (!conversationMap.has(partner.id)) {
      conversationMap.set(partner.id, {
        partner_id: partner.id,
        partner_name: partner.name || 'Unknown',
        partner_avatar: partner.avatar_url || null,
        last_message: msg.content,
        last_message_time: msg.created_at,
        unread_count: 0,
        last_message_sender_id: msg.sender_id
      });
    }

    if (!msg.is_read && msg.receiver_id === userId) {
      const convo = conversationMap.get(partner.id)!;
      convo.unread_count++;
    }
  });

  return Array.from(conversationMap.values());
};

export const getMessages = async (currentUserId: string, otherUserId: string): Promise<Message[]> => {
  const { data, error } = await insforge.database
    .from('messages')
    .select('*')
    .or(`and(sender_id.eq.${currentUserId},receiver_id.eq.${otherUserId}),and(sender_id.eq.${otherUserId},receiver_id.eq.${currentUserId})`)
    .order('created_at', { ascending: true });

  if (error) throw error;
  return data || [];
};

export const sendMessage = async (senderId: string, receiverId: string, content: string, jobId?: string) => {
  const { data, error } = await insforge.database
    .from('messages')
    .insert({
      sender_id: senderId,
      receiver_id: receiverId,
      content,
      job_id: jobId || null,
      is_read: false
    })
    .select()
    .single();

  if (error) throw error;
  return data;
};

export const markAsRead = async (receiverId: string, senderId: string) => {
  const { error } = await insforge.database
    .from('messages')
    .update({ is_read: true })
    .eq('receiver_id', receiverId)
    .eq('sender_id', senderId)
    .eq('is_read', false);

  if (error) throw error;
};

export const getUnreadCount = async (userId: string): Promise<number> => {
  const { count, error } = await insforge.database
    .from('messages')
    .select('*', { count: 'exact', head: true })
    .eq('receiver_id', userId)
    .eq('is_read', false);

  if (error) return 0;
  return count || 0;
};

import { insforge } from '@/lib/insforge';

export interface UserProfile {
  id: string;
  email: string;
  name: string;
  role: string;
  phone?: string;
  location?: string;
  bio?: string;
  avatar_url?: string;
  candidate_profiles?: CandidateProfile;
}

export interface CandidateProfile {
  id: string;
  headline?: string;
  skills?: string[];
  experience_years?: number;
  education?: any[];
  work_history?: any[];
  resume_url?: string;
  linkedin_url?: string;
  github_url?: string;
  portfolio_url?: string;
  job_types?: string[];
  preferred_locations?: string[];
  salary_min?: number;
  salary_max?: number;
  currency?: string;
  open_to_remote?: boolean;
  profile_strength: number;
  is_visible?: boolean;
  updated_at?: string;
}

/**
 * Fetches the current user's profile with joined candidate details.
 */
export async function getMyProfile(): Promise<UserProfile> {
  const { data: { session } } = await insforge.auth.getCurrentSession();
  if (!session?.user) {
    throw new Error('Unauthorized');
  }

  const { data, error } = await insforge.database
    .from('profiles')
    .select('*, candidate_profiles(*)')
    .eq('id', session.user.id)
    .single();

  if (error) {
    throw new Error(`Failed to fetch profile: ${error.message}`);
  }

  return data as unknown as UserProfile;
}

/**
 * Updates the base user profile (profiles table).
 */
export async function updateProfile(data: Partial<UserProfile>): Promise<void> {
  const { data: { session } } = await insforge.auth.getCurrentSession();
  if (!session?.user) throw new Error('Unauthorized');

  const { error } = await insforge.database
    .from('profiles')
    .update(data)
    .eq('id', session.user.id);

  if (error) {
    throw new Error(`Failed to update profile: ${error.message}`);
  }
}

/**
 * Updates the candidate-specific profile details.
 */
export async function updateCandidateProfile(data: Partial<CandidateProfile>): Promise<void> {
  const { data: { session } } = await insforge.auth.getCurrentSession();
  if (!session?.user) throw new Error('Unauthorized');

  // Calculate new strength if relevant fields have changed
  const [{ data: current }, { data: baseProfile }] = await Promise.all([
    insforge.database.from('candidate_profiles').select('*').eq('id', session.user.id).single(),
    insforge.database.from('profiles').select('bio').eq('id', session.user.id).single()
  ]);

  const mergedForStrength = { ...current, ...data, bio: baseProfile?.bio };
  const strength = calculateProfileStrength(mergedForStrength);

  const { error } = await insforge.database
    .from('candidate_profiles')
    .update({ ...data, profile_strength: strength })
    .eq('id', session.user.id);

  if (error) {
    throw new Error(`Failed to update candidate profile: ${error.message}`);
  }
}

/**
 * Logic to calculate profile strength percentage 0-100.
 */
export function calculateProfileStrength(profile: any): number {
  if (!profile) return 0;

  const rules = [
    { field: 'headline', weight: 5 },
    { field: 'bio', weight: 10 },
    { field: 'skills', weight: 15, check: (v: any) => Array.isArray(v) && v.length >= 3 },
    { field: 'experience_years', weight: 5, check: (v: any) => v != null && v >= 0 },
    { field: 'resume_url', weight: 20 },
    { field: 'education', weight: 10, check: (v: any) => Array.isArray(v) && v.length > 0 },
    { field: 'work_history', weight: 20, check: (v: any) => Array.isArray(v) && v.length > 0 },
    { field: 'job_types', weight: 10, check: (v: any) => Array.isArray(v) && v.length > 0 },
    { field: 'preferred_locations', weight: 5, check: (v: any) => Array.isArray(v) && v.length > 0 },
  ];

  let strength = 0;
  rules.forEach(rule => {
    const value = profile[rule.field];
    const isValid = rule.check ? rule.check(value) : !!value;
    if (isValid) {
      strength += rule.weight;
    }
  });

  return Math.min(strength, 100);
}

import { insforge } from '@/lib/insforge';

export interface RecruiterDashboardStats {
  activeJobs: number;
  totalApplications: number;
  recentApplicants: any[];
}

/**
 * Fetches dashboard stats for the logged-in recruiter.
 */
export async function getRecruiterDashboard(): Promise<RecruiterDashboardStats> {
  const { data: { session } } = await insforge.auth.getCurrentSession();
  if (!session?.user) throw new Error('Unauthorized');

  const [
    { count: activeJobs },
    { count: totalApps },
    { data: recentApplicants }
  ] = await Promise.all([
    insforge.database.from('jobs')
      .select('*', { count: 'exact', head: true })
      .eq('recruiter_id', session.user.id)
      .eq('status', 'active'),

    insforge.database.from('applications')
      .select('*, jobs!inner(*)', { count: 'exact', head: true })
      .eq('jobs.recruiter_id', session.user.id),

    insforge.database.from('applications')
      .select('*, jobs!inner(title), profiles!applications_candidate_id_fkey(name, email)')
      .eq('jobs.recruiter_id', session.user.id)
      .order('applied_at', { ascending: false })
      .limit(5)
  ]);

  return {
    activeJobs: activeJobs || 0,
    totalApplications: totalApps || 0,
    recentApplicants: recentApplicants || []
  };
}

/**
 * Fetches all applicants for a specific job posted by the recruiter.
 */
export async function getJobApplicants(jobId: string) {
  const { data, error } = await insforge.database
    .from('applications')
    .select('*, profiles!applications_candidate_id_fkey(*, candidate_profiles(*))')
    .eq('job_id', jobId)
    .order('applied_at', { ascending: false });

  if (error) throw new Error(`Failed to fetch applicants: ${error.message}`);
  return data;
}

/**
 * Moves an application to a new stage in the recruitment pipeline.
 */
export async function moveApplicationStage(applicationId: string, status: string) {
  const { error } = await insforge.database
    .from('applications')
    .update({ status, updated_at: new Date().toISOString() })
    .eq('id', applicationId);

  if (error) throw new Error(`Failed to update application stage: ${error.message}`);
}

/**
 * Completes recruiter setup by linking to a company and setting role details.
 */
export async function completeRecruiterSetup(data: { 
  companyName: string; 
  jobTitle: string; 
  department: string; 
}) {
  const { data: { session } } = await insforge.auth.getCurrentSession();
  if (!session?.user) throw new Error('Unauthorized');

  // 1. Find or create company by name
  let { data: company } = await insforge.database
    .from('companies')
    .select('id')
    .eq('name', data.companyName)
    .maybeSingle();

  if (!company) {
    const { data: newCompany, error: createError } = await insforge.database
      .from('companies')
      .insert([{ name: data.companyName }])
      .select('id')
      .single();

    if (createError) throw new Error(`Failed to create company: ${createError.message}`);
    company = newCompany;
  }

  // 2. Upsert recruiter profile
  const { error: profileError } = await insforge.database
    .from('recruiter_profiles')
    .upsert([{
      id: session.user.id,
      company_id: company!.id,
      job_title: data.jobTitle,
      department: data.department,
      is_approved: false
    }]);

  if (profileError) throw new Error(`Failed to save recruiter profile: ${profileError.message}`);

  // 3. Activity log
  await insforge.database.from('activity').insert([{
    user_id: session.user.id,
    type: 'onboarding_complete',
    description: `Completed recruiter setup at ${data.companyName}`
  }]);
}

import { insforge } from '@/lib/insforge';

/**
 * Utility for uploading resumes to the 'resumes' bucket.
 * Constraints: Max 5MB, application/pdf only.
 */
export async function uploadResume(file: File, userId: string): Promise<string> {
  // 1. Validate file type
  if (file.type !== 'application/pdf') {
    throw new Error('Invalid file type. Only PDF resumes are accepted.');
  }

  // 2. Validate file size (5MB)
  const MAX_SIZE = 5 * 1024 * 1024;
  if (file.size > MAX_SIZE) {
    throw new Error('File too large. Resume must be less than 5MB.');
  }

  // 3. Upload to userId/filename.pdf
  const path = `${userId}/${Date.now()}_${file.name}`;
  const { data, error } = await insforge.storage
    .from('resumes')
    .upload(path, file);

  if (error) {
    console.error('Resume upload error:', error);
    throw new Error(`Failed to upload resume: ${error.message}`);
  }

  if (!data?.url) {
    throw new Error('Upload succeeded but no URL was returned.');
  }

  return data.url;
}

/**
 * Utility for uploading profile pictures to the 'avatars' bucket.
 * Constraints: Max 2MB, images only (jpeg, png, webp).
 */
export async function uploadAvatar(file: File, userId: string): Promise<string> {
  // 1. Validate file type
  const allowedTypes = ['image/jpeg', 'image/png', 'image/webp'];
  if (!allowedTypes.includes(file.type)) {
    throw new Error('Invalid image type. Use JPEG, PNG, or WebP.');
  }

  // 2. Validate file size (2MB)
  const MAX_SIZE = 2 * 1024 * 1024;
  if (file.size > MAX_SIZE) {
    throw new Error('Image too large. Profile picture must be less than 2MB.');
  }

  // 3. Upload to userId/filename
  const path = `${userId}/${Date.now()}_${file.name}`;
  const { data, error } = await insforge.storage
    .from('avatars')
    .upload(path, file);

  if (error) {
    console.error('Avatar upload error:', error);
    throw new Error(`Failed to upload avatar: ${error.message}`);
  }

  if (!data?.url) {
    throw new Error('Upload succeeded but no URL was returned.');
  }

  return data.url;
}

/**
 * Utility for uploading company logos to the 'company-logos' bucket.
 * Constraints: Max 2MB, images + SVG.
 */
export async function uploadCompanyLogo(file: File, companyId: string): Promise<string> {
  // 1. Validate file type
  const allowedTypes = ['image/jpeg', 'image/png', 'image/webp', 'image/svg+xml'];
  if (!allowedTypes.includes(file.type)) {
    throw new Error('Invalid image type. Use JPEG, PNG, WebP, or SVG.');
  }

  // 2. Validate file size (2MB)
  const MAX_SIZE = 2 * 1024 * 1024;
  if (file.size > MAX_SIZE) {
    throw new Error('Logo too large. Company logo must be less than 2MB.');
  }

  // 3. Upload to companyId/filename
  const path = `${companyId}/${Date.now()}_${file.name}`;
  const { data, error } = await insforge.storage
    .from('company-logos')
    .upload(path, file);

  if (error) {
    console.error('Logo upload error:', error);
    throw new Error(`Failed to upload logo: ${error.message}`);
  }

  if (!data?.url) {
    throw new Error('Upload succeeded but no URL was returned.');
  }

  return data.url;
}

/**
 * Utility for deleting files from a storage bucket.
 */
export async function deleteFile(bucket: string, path: string): Promise<void> {
  const { error } = await insforge.storage.from(bucket).remove(path);

  if (error) {
    console.error(`Delete error in ${bucket}:`, error);
    throw new Error(`Failed to delete file from ${bucket}: ${error.message}`);
  }
}

"use client";

import React, { createContext, useCallback, useContext, useEffect, useState, type ReactNode } from 'react';

import { insforge } from '@/lib/insforge';
import type { User, UserRole } from '@/types/auth';

interface AuthContextType {
  user: User | null;
  isAdmin: boolean;
  isLoading: boolean;
  signIn: (email: string, password: string) => Promise<{ error?: string; user?: User | null }>;
  signUp: (email: string, password: string, role: UserRole, name: string) => Promise<{ error?: string; requireEmailVerification?: boolean }>;
  signOut: () => Promise<void>;
  logout: () => Promise<void>;
  refreshUser: () => Promise<User | null>;
  login: (token: string, user: User) => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

function isAdminEmail(email: string | null | undefined): boolean {
  if (!email) {
    return false;
  }

  const envEmails = (process.env.NEXT_PUBLIC_ADMIN_EMAILS || '')
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean);

  return envEmails.includes(email.trim().toLowerCase());
}

function normalizeRole(role: UserRole, email: string): UserRole {
  if (isAdminEmail(email) && role !== 'admin' && role !== 'super_admin') {
    return 'admin';
  }

  return role;
}

const USER_STORAGE_KEY = 'tm_user';

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  const isAdmin = user?.role === 'admin' || user?.role === 'super_admin';

  const clearAuthCookies = useCallback(() => {
    document.cookie = 'tm_access_token=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT';
    document.cookie = 'tm_role=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT';
    document.cookie = 'tm_admin_access=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT';
    if (typeof window !== 'undefined') {
      window.sessionStorage.removeItem(USER_STORAGE_KEY);
    }
  }, []);

  const syncAuthCookies = useCallback((token: string, authUser: Pick<User, 'role' | 'email'>) => {
    clearAuthCookies();
    document.cookie = `tm_access_token=${token}; path=/; max-age=3600; SameSite=Lax`;
    document.cookie = `tm_role=${authUser.role}; path=/; max-age=3600; SameSite=Lax`;

    if (authUser.role === 'admin' || authUser.role === 'super_admin' || isAdminEmail(authUser.email)) {
      document.cookie = 'tm_admin_access=true; path=/; max-age=3600; SameSite=Lax';
    }
  }, [clearAuthCookies]);

  const cacheUser = useCallback((authUser: User | null) => {
    if (typeof window === 'undefined') {
      return;
    }

    if (!authUser) {
      window.sessionStorage.removeItem(USER_STORAGE_KEY);
      return;
    }

    window.sessionStorage.setItem(USER_STORAGE_KEY, JSON.stringify(authUser));
  }, []);

  const fetchProfile = useCallback(async (
    userId: string,
    email: string,
    metadata?: Record<string, unknown>,
  ): Promise<User | null> => {
    try {
      const { data: profile, error } = await insforge.database
        .from('profiles')
        .select('*')
        .eq('id', userId)
        .single();

      if (error || !profile) {
        const fallbackRole = normalizeRole(((metadata?.role as UserRole) || 'candidate'), email);
        const fallbackName = email.split('@')[0];

        try {
          const { data: createdProfile, error: insertError } = await insforge.database
            .from('profiles')
            .insert([{
              id: userId,
              email,
              role: fallbackRole,
              name: fallbackName,
            }])
            .select()
            .single();

          if (!insertError && createdProfile) {
            return {
              id: userId,
              email,
              role: normalizeRole(createdProfile.role as UserRole, email),
              name: createdProfile.name || fallbackName,
              avatar_url: createdProfile.avatar_url || null,
              company_id: createdProfile.company_id,
              created_at: createdProfile.created_at,
              mfa_enabled: createdProfile.mfa_enabled || false,
              password_set_at: createdProfile.password_set_at,
            };
          }
        } catch {
          // Fall through to a minimal in-memory user object.
        }

        return {
          id: userId,
          email,
          role: fallbackRole,
          name: fallbackName,
          avatar_url: null,
        };
      }

      return {
        id: userId,
        email,
        role: normalizeRole(((profile.role as UserRole) || 'candidate'), email),
        name: profile.name || '',
        avatar_url: profile.avatar_url || null,
        company_id: profile.company_id,
        created_at: profile.created_at,
        mfa_enabled: profile.mfa_enabled || false,
        password_set_at: profile.password_set_at,
      };
    } catch (err) {
      console.error('Unexpected error fetching profile:', err);
      return null;
    }
  }, []);

  const refreshUser = useCallback(async () => {
    setIsLoading(true);

    try {
      const response = await fetch('/api/auth/session', {
        credentials: 'include',
        cache: 'no-store',
      });

      if (!response.ok) {
        if (user) {
          return user;
        }

        clearAuthCookies();
        setUser(null);
        return null;
      }

      const payload = await response.json();
      const resolvedUser = (payload?.user || null) as User | null;

      if (!resolvedUser) {
        if (user) {
          return user;
        }

        clearAuthCookies();
        setUser(null);
        return null;
      }

      document.cookie = `tm_role=${resolvedUser.role}; path=/; max-age=3600; SameSite=Lax`;
      if (resolvedUser.role === 'admin' || resolvedUser.role === 'super_admin' || isAdminEmail(resolvedUser.email)) {
        document.cookie = 'tm_admin_access=true; path=/; max-age=3600; SameSite=Lax';
      }

      setUser(resolvedUser);
      cacheUser(resolvedUser);
      return resolvedUser;
    } catch (err) {
      if (user) {
        return user;
      }

      if (!(err instanceof TypeError && err.message === 'Failed to fetch')) {
        console.error('Refresh user error:', err);
      }

      clearAuthCookies();
      setUser(null);
      return null;
    } finally {
      setIsLoading(false);
    }
  }, [cacheUser, clearAuthCookies, user]);

  useEffect(() => {
    try {
      const cached = window.sessionStorage.getItem(USER_STORAGE_KEY);
      if (cached) {
        setUser(JSON.parse(cached) as User);
      }
    } catch {
      window.sessionStorage.removeItem(USER_STORAGE_KEY);
    }
  }, []);

  useEffect(() => {
    refreshUser();
  }, [refreshUser]);

  const signIn = async (email: string, password: string) => {
    try {
      const { data, error } = await insforge.auth.signInWithPassword({ email, password });

      if (error) {
        let message = error.message;
        if (message.includes('Invalid login credentials')) {
          message = 'Invalid email or password. Please try again.';
        } else if (message.includes('Email not confirmed')) {
          message = 'Please confirm your email address before logging in.';
        }
        return { error: message };
      }

      if (!data?.accessToken || !data.user?.id || !data.user?.email) {
        return { error: 'Sign in succeeded, but the session payload was incomplete.' };
      }

      const fullUser = await fetchProfile(data.user.id, data.user.email, data.user.metadata || undefined);
      if (!fullUser) {
        return { error: 'Signed in, but failed to load your profile.' };
      }

      syncAuthCookies(data.accessToken, fullUser);
      setUser(fullUser);
      cacheUser(fullUser);
      return { user: fullUser };
    } catch {
      return { error: 'An unexpected error occurred during sign in.' };
    }
  };

  const signUp = async (email: string, password: string, role: UserRole, name: string) => {
    try {
      const { error, data } = await insforge.auth.signUp({
        email,
        password,
        name,
      });

      if (error) {
        return { error: error.message };
      }

      if (data?.user) {
        await insforge.database
          .from('profiles')
          .update({ role })
          .eq('id', data.user.id);
      }

      await refreshUser();
      return { requireEmailVerification: data?.requireEmailVerification };
    } catch {
      return { error: 'An unexpected error occurred during sign up.' };
    }
  };

  const signOut = async () => {
    await insforge.auth.signOut();
    clearAuthCookies();
    setUser(null);
    window.location.replace('/login');
  };

  const login = useCallback((token: string, authUser: User) => {
    syncAuthCookies(token, authUser);
    setUser(authUser);
    cacheUser(authUser);
  }, [cacheUser, syncAuthCookies]);

  return (
    <AuthContext.Provider value={{ user, isAdmin, isLoading, signIn, signUp, signOut, logout: signOut, refreshUser, login }}>
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

export interface CandidateProfileFormData {
  headline: string;
  skills: string[];
  experience_years: number | null;
  education: string;
  resume_url: string;
  salary_min: number | null;
  salary_max: number | null;
  preferred_locations: string[];
  job_type: string;
  profile_strength: number;
}

export interface CandidateSettingsBundle {
  profile: {
    id: string;
    email: string;
    name: string;
    phone: string;
    location: string;
    role_id: string | null;
  };
  candidateProfile: CandidateProfileFormData;
}

const SKILL_KEYWORDS = [
  'javascript',
  'typescript',
  'react',
  'next.js',
  'nextjs',
  'node.js',
  'node',
  'python',
  'java',
  'c++',
  'c#',
  'sql',
  'postgresql',
  'mongodb',
  'aws',
  'docker',
  'kubernetes',
  'tailwind',
  'figma',
  'graphql',
  'rest',
  'html',
  'css',
  'vue',
  'angular',
  'php',
  'go',
  'rust',
  'firebase',
  'supabase',
  'insforge',
];

const HEADLINE_KEYWORDS = [
  'frontend',
  'backend',
  'fullstack',
  'developer',
  'engineer',
  'designer',
  'manager',
  'analyst',
  'marketer',
  'product',
  'data',
  'devops',
  'mobile',
  'ios',
  'android',
  'qa',
  'recruiter',
];

function isFilled(value: unknown): boolean {
  return typeof value === 'string' ? value.trim().length > 0 : value !== null && value !== undefined;
}

function titleCase(value: string): string {
  return value
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join(' ');
}

export function sanitizeStringArray(value: unknown): string[] {
  if (Array.isArray(value)) {
    return [...new Set(
      value
        .map((item) => String(item).trim())
        .filter(Boolean)
    )];
  }

  if (typeof value === 'string') {
    return [...new Set(
      value
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean)
    )];
  }

  return [];
}

export function sanitizeOptionalNumber(value: unknown): number | null {
  if (value === '' || value === null || value === undefined) {
    return null;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

export function getDefaultCandidateProfile(): CandidateProfileFormData {
  return {
    headline: '',
    skills: [],
    experience_years: null,
    education: '',
    resume_url: '',
    salary_min: null,
    salary_max: null,
    preferred_locations: [],
    job_type: '',
    profile_strength: 0,
  };
}

export function calculateCandidateProfileStrength(
  profile: Pick<CandidateSettingsBundle['profile'], 'name' | 'phone' | 'location'>,
  candidateProfile: Partial<CandidateProfileFormData>,
): number {
  let score = 0;

  if (isFilled(profile.name)) score += 10;
  if (isFilled(profile.phone)) score += 10;
  if (isFilled(profile.location)) score += 10;

  if (sanitizeStringArray(candidateProfile.skills).length > 0) score += 20;
  if (candidateProfile.experience_years !== null && candidateProfile.experience_years !== undefined) score += 20;

  if (isFilled(candidateProfile.resume_url)) score += 15;

  if (candidateProfile.salary_min !== null && candidateProfile.salary_min !== undefined) score += 5;
  if (candidateProfile.salary_max !== null && candidateProfile.salary_max !== undefined) score += 5;

  const hasPreferenceTarget =
    sanitizeStringArray(candidateProfile.preferred_locations).length > 0 || isFilled(candidateProfile.job_type);
  if (hasPreferenceTarget) score += 5;

  return Math.min(score, 100);
}

export function deriveResumeAutoFill(resumeUrl: string): Pick<CandidateProfileFormData, 'headline' | 'skills'> {
  if (!resumeUrl) {
    return { headline: '', skills: [] };
  }

  const decoded = decodeURIComponent(resumeUrl).toLowerCase();
  const rawFileName = decoded.split('/').pop()?.split('?')[0] ?? '';
  const cleaned = rawFileName
    .replace(/\.[a-z0-9]+$/i, '')
    .replace(/[_-]+/g, ' ')
    .replace(/\d+/g, ' ')
    .replace(/\b(resume|cv|profile|updated|final|latest|copy)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  const words = cleaned.split(' ').filter(Boolean);
  const headlineTokens = words.filter((word) => HEADLINE_KEYWORDS.includes(word));
  const skillMatches = SKILL_KEYWORDS.filter((skill) => decoded.includes(skill));

  return {
    headline: headlineTokens.length > 0 ? titleCase(headlineTokens.slice(0, 4).join(' ')) : '',
    skills: skillMatches.map((skill) => titleCase(skill.replace('.js', ''))),
  };
}

export function applyResumeAutofill(candidateProfile: CandidateProfileFormData): CandidateProfileFormData {
  if (!candidateProfile.resume_url) {
    return candidateProfile;
  }

  const derived = deriveResumeAutoFill(candidateProfile.resume_url);

  return {
    ...candidateProfile,
    headline: candidateProfile.headline || derived.headline,
    skills: candidateProfile.skills.length > 0 ? candidateProfile.skills : derived.skills,
  };
}

export function normalizeCandidateProfile(input: Partial<CandidateProfileFormData>): CandidateProfileFormData {
  return {
    headline: typeof input.headline === 'string' ? input.headline.trim() : '',
    skills: sanitizeStringArray(input.skills),
    experience_years: sanitizeOptionalNumber(input.experience_years),
    education: typeof input.education === 'string' ? input.education.trim() : '',
    resume_url: typeof input.resume_url === 'string' ? input.resume_url.trim() : '',
    salary_min: sanitizeOptionalNumber(input.salary_min),
    salary_max: sanitizeOptionalNumber(input.salary_max),
    preferred_locations: sanitizeStringArray(input.preferred_locations),
    job_type: typeof input.job_type === 'string' ? input.job_type.trim() : '',
    profile_strength: sanitizeOptionalNumber(input.profile_strength) ?? 0,
  };
}

import { useEffect, RefObject } from 'react';

export function useClickOutside(ref: RefObject<HTMLElement | null>, handler: (event: MouseEvent | TouchEvent) => void) {
  useEffect(() => {
    const listener = (event: MouseEvent | TouchEvent) => {
      if (!ref.current || ref.current.contains(event.target as Node)) {
        return;
      }
      handler(event);
    };

    document.addEventListener('mousedown', listener);
    document.addEventListener('touchstart', listener);

    return () => {
      document.removeEventListener('mousedown', listener);
      document.removeEventListener('touchstart', listener);
    };
  }, [ref, handler]);
}

"use client";

import { useState, useEffect, useCallback } from 'react';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';
import { 
  getMessages, 
  sendMessage as sendMsgApi, 
  markAsRead as markReadApi, 
  type Message 
} from '@/lib/api/messages';

export function useMessages(receiverId: string | null) {
  const { user } = useAuth();
  const [messages, setMessages] = useState<Message[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const fetchMessages = useCallback(async () => {
    if (!user || !receiverId) {
      setMessages([]);
      return;
    }

    setLoading(true);
    try {
      const data = await getMessages(user.id, receiverId);
      setMessages(data);
      // Auto mark as read
      await markReadApi(user.id, receiverId);
    } catch (err: any) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  }, [user, receiverId]);

  useEffect(() => {
    if (!user || !receiverId) return;

    fetchMessages();

    const handleNewMessage = (payload: any) => {
      const newMsg = payload as Message;
      // Only add if it belongs to this conversation
      if (
        (newMsg.sender_id === receiverId && newMsg.receiver_id === user.id) ||
        (newMsg.sender_id === user.id && newMsg.receiver_id === receiverId)
      ) {
        setMessages(prev => {
          if (prev.find(m => m.id === newMsg.id)) return prev;
          return [...prev, newMsg];
        });

        if (newMsg.receiver_id === user.id) {
          markReadApi(user.id, receiverId).catch(console.error);
        }
      }
    };

    const setupRealtime = async () => {
      try {
        await insforge.realtime.connect();
        await insforge.realtime.subscribe('messages:' + user.id);
        insforge.realtime.on('INSERT_messages', handleNewMessage);
      } catch (err) {
        console.error('Realtime setup error:', err);
      }
    };

    setupRealtime();

    return () => {
        insforge.realtime.off('INSERT_messages', handleNewMessage);
        insforge.realtime.unsubscribe('messages:' + user.id);
    };
  }, [user, receiverId, fetchMessages]);

  const sendMessage = async (content: string, jobId?: string) => {
    if (!user || !receiverId) return;

    try {
      const newMsg = await sendMsgApi(user.id, receiverId, content, jobId);
      setMessages(prev => {
        if (prev.find(m => m.id === newMsg.id)) return prev;
        return [...prev, newMsg];
      });
      return newMsg;
    } catch (err: any) {
      console.error('Send error:', err);
      throw err;
    }
  };

  return {
    messages,
    loading,
    error,
    sendMessage,
    markAsRead: () => user && receiverId && markReadApi(user.id, receiverId),
    refresh: fetchMessages
  };
}

"use client";

import { useState, useEffect, useCallback } from 'react';
import { insforge } from '@/lib/insforge';
import { useAuth } from '@/lib/auth/AuthContext';

export interface NotificationData {
  id: string;
  user_id: string;
  type: string;
  title: string;
  message: string;
  is_read: boolean;
  metadata: any;
  created_at: string;
}

export function useRealTimeNotifications() {
  const { user } = useAuth();
  const [notifications, setNotifications] = useState<NotificationData[]>([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);

  const fetchNotifications = useCallback(async () => {
    if (!user) return;

    try {
      const { data, error } = await insforge.database
        .from('notifications')
        .select('*')
        .eq('user_id', user.id)
        .order('created_at', { ascending: false })
        .limit(20);

      if (!error && data) {
        setNotifications(data);
        const unread = data.filter((n: NotificationData) => !n.is_read).length;
        setUnreadCount(unread);
      }
    } catch (err) {
      console.error('Error fetching notifications:', err);
    } finally {
      setIsLoading(false);
    }
  }, [user]);

  useEffect(() => {
    if (!user) return;

    fetchNotifications();

    const handleNewNotification = (payload: any) => {
      const newNotif = payload as NotificationData;
      setNotifications(prev => [newNotif, ...prev.slice(0, 19)]);
      setUnreadCount(prev => prev + 1);

      // Show browser notification if permission granted
      if (typeof window !== 'undefined' && 'Notification' in window && Notification.permission === 'granted') {
        new Notification(newNotif.title, {
          body: newNotif.message,
          icon: '/TalentMesh_Logo-removebg-preview.png',
        });
      }
    };

    const setupRealtime = async () => {
      try {
        await insforge.realtime.connect();
        await insforge.realtime.subscribe('notifications:' + user.id);
        insforge.realtime.on('INSERT_notifications', handleNewNotification);
      } catch (err) {
        console.error('Realtime connection error:', err);
      }
    };

    setupRealtime();

    return () => {
      insforge.realtime.off('INSERT_notifications', handleNewNotification);
      insforge.realtime.unsubscribe('notifications:' + user.id);
    };
  }, [user, fetchNotifications]);

  const markAllAsRead = async () => {
    if (!user) return;

    try {
      const { error } = await insforge.database
        .from('notifications')
        .update({ is_read: true })
        .eq('user_id', user.id)
        .eq('is_read', false);

      if (!error) {
        setNotifications(prev => prev.map(n => ({ ...n, is_read: true })));
        setUnreadCount(0);
      }
    } catch (err) {
      console.error('Error marking notifications as read:', err);
    }
  };

  const markAsRead = async (id: string) => {
    try {
      const { error } = await insforge.database
        .from('notifications')
        .update({ is_read: true })
        .eq('id', id);

      if (!error) {
        setNotifications(prev => prev.map(n => n.id === id ? { ...n, is_read: true } : n));
        setUnreadCount(prev => Math.max(0, prev - 1));
      }
    } catch (err) {
      console.error('Error marking notification as read:', err);
    }
  };

  return {
    notifications,
    unreadCount,
    isLoading,
    markAllAsRead,
    markAsRead,
    refresh: fetchNotifications,
  };
}

"use client";

import { useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/AuthContext';

export const useRequireAuth = () => {
  const { user, isLoading } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!isLoading && !user) {
      router.push('/login');
    }
  }, [user, isLoading, router]);

  return { user, isLoading };
};

import { createClient } from '@insforge/sdk';

// Ensure this code is not accidentally imported into a client component bundle
if (typeof window !== 'undefined') {
  throw new Error('CRITICAL SECURITY ERROR: lib/insforge-admin.ts cannot be imported on the client. It exposes the service role key.');
}

const supabaseUrl = process.env.NEXT_PUBLIC_INSFORGE_URL;
const serviceKey = process.env.INSFORGE_SERVICE_KEY;

if (!supabaseUrl) {
  throw new Error('CRITICAL ERROR: Missing environment variable NEXT_PUBLIC_INSFORGE_URL');
}

// Admin client containing the service key, capable of bypassing Row Level Security
// If the service key is missing, we export a proxy that throws only when used,
// OR we export null and handle it in consumers. 
// Given the use case, we'll export the client only if the key exists.
export const insforgeAdmin = serviceKey 
  ? createClient({
      baseUrl: supabaseUrl,
      anonKey: serviceKey, // Passing the service key as the auth header token
    })
  : null;

if (!serviceKey && typeof window === 'undefined') {
  console.warn('⚠️ WARNING: Missing environment variable INSFORGE_SERVICE_KEY. Admin operations will fail.');
}

import { createClient } from '@insforge/sdk';
import { User } from '@/types/auth';

const supabaseUrl = process.env.NEXT_PUBLIC_INSFORGE_URL;
const supabaseAnonKey = process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY;

if (!supabaseUrl) {
  throw new Error('CRITICAL ERROR: Missing environment variable NEXT_PUBLIC_INSFORGE_URL');
}

if (!supabaseAnonKey) {
  throw new Error('CRITICAL ERROR: Missing environment variable NEXT_PUBLIC_INSFORGE_ANON_KEY');
}

// Client containing the anon key, safe for both client and server pages
export const insforge = createClient({
  baseUrl: supabaseUrl,
  anonKey: supabaseAnonKey,
});

/**
 * Helper to fetch the current active session
 */
export async function getSession() {
  const { data, error } = await insforge.auth.getCurrentSession();
  if (error) {
    console.error('Error fetching session:', error.message);
    return null;
  }
  return data?.session || null;
}

/**
 * Helper to fetch the current user
 */
export async function getCurrentUser() {
  const session = await getSession();
  return session?.user || null;
}

/**
 * Helper to fetch the full user profile on the server
 */
export async function getServerUser(): Promise<User | null> {
  const user = await getCurrentUser();
  if (!user) return null;

  try {
    const { data: profile, error } = await insforge.database
      .from('profiles')
      .select('*')
      .eq('id', user.id)
      .single();

    if (error || !profile) {
      console.error('Error fetching server user profile:', error?.message);
      return null;
    }

    return {
      id: user.id,
      email: user.email!,
      name: profile.name || '',
      role: profile.role as any,
      avatar_url: profile.avatar_url || null,
      company_id: profile.company_id,
      created_at: profile.created_at,
    };
  } catch (err) {
    console.error('Unexpected error in getServerUser:', err);
    return null;
  }
}

import 'server-only';

import { createClient } from '@insforge/sdk';
import { cookies } from 'next/headers';

import type { User } from '@/types/auth';

function isAdminEmail(email: string | null | undefined): boolean {
  if (!email) return false;

  const envEmails = process.env.ADMIN_EMAILS || process.env.NEXT_PUBLIC_ADMIN_EMAILS || '';
  return envEmails
    .split(',')
    .map((value) => value.trim().toLowerCase())
    .filter(Boolean)
    .includes(email.toLowerCase());
}

export async function getServerUser(): Promise<User | null> {
  const cookieStore = await cookies();
  const token = cookieStore.get('tm_access_token')?.value;

  if (!token) return null;

  const insforge = createClient({
    baseUrl: process.env.NEXT_PUBLIC_INSFORGE_URL!,
    anonKey: process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY!,
    edgeFunctionToken: token,
  });

  const { data: { user }, error: userError } = await insforge.auth.getCurrentUser();

  if (userError || !user) return null;

  const { data: profile } = await insforge.database
    .from('profiles')
    .select('*')
    .eq('id', user.id)
    .single();

  const role = profile?.role || (isAdminEmail(user.email) ? 'admin' : 'candidate');

  return {
    id: user.id,
    email: user.email!,
    name: profile?.name || user.email?.split('@')[0] || '',
    role: isAdminEmail(user.email) && !['admin', 'super_admin'].includes(role) ? 'admin' : role,
    avatar_url: profile?.avatar_url || null,
    company_id: profile?.company_id,
    created_at: profile?.created_at,
    mfa_enabled: profile?.mfa_enabled || false,
    password_set_at: profile?.password_set_at,
  };
}

import 'server-only';

import { createClient } from '@insforge/sdk';
