/**
 * Calculates candidate profile strength (0-100)
 * 
 * Rules:
 * - name (from profiles): 10pts
 * - avatar: 10pts
 * - skills 3+: 20pts
 * - experience: 15pts
 * - resume: 20pts
 * - linkedin: 10pts
 * - bio: 15pts
 */
export function calculateProfileStrength(profile: any, candidateProfile: any): number {
    let score = 0;

    // 1. Name (10pts)
    if (profile?.name && profile.name.trim().length > 0) {
        score += 10;
    }

    // 2. Avatar (10pts)
    if (profile?.avatar_url) {
        score += 10;
    }

    // 3. Skills 3+ (20pts)
    if (candidateProfile?.skills && Array.isArray(candidateProfile.skills) && candidateProfile.skills.length >= 3) {
        score += 20;
    }

    // 4. Experience (15pts)
    if (candidateProfile?.experience_years !== undefined && candidateProfile.experience_years !== null) {
        score += 15;
    }

    // 5. Resume (20pts)
    if (candidateProfile?.resume_url) {
        score += 20;
    }

    // 6. LinkedIn (10pts)
    if (candidateProfile?.linkedin_url) {
        score += 10;
    }

    // 7. Bio (15pts)
    // Assuming 'headline' or a field in profiles maps to bio if not explicitly named 'bio'
    // Following candidate_profiles schema, let's check for 'headline'
    if (candidateProfile?.headline && candidateProfile.headline.trim().length > 0) {
        score += 15;
    }

    return Math.min(score, 100);
}

import { z } from 'zod';

const passwordSchema = z
  .string()
  .min(8, 'Password must be at least 8 characters')
  .regex(/[A-Z]/, 'Password must contain at least one uppercase letter')
  .regex(/[0-9]/, 'Password must contain at least one number');

export const loginSchema = z.object({
  email: z.string().email('Invalid email address'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
});

export const signupSchema = z.object({
  name: z.string().min(2, 'Name must be at least 2 characters').max(100, 'Name must be less than 100 characters'),
  email: z.string().email('Invalid email address'),
  password: passwordSchema,
  role: z.enum(['candidate', 'recruiter'], {
    message: 'Please select a valid role',
  }),
});

export const forgotPasswordSchema = z.object({
  email: z.string().email('Invalid email address'),
});

export const resetPasswordSchema = z.object({
  password: passwordSchema,
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ['confirmPassword'],
});

export type LoginInput = z.infer<typeof loginSchema>;
export type SignupInput = z.infer<typeof signupSchema>;
export type ForgotPasswordInput = z.infer<typeof forgotPasswordSchema>;
export type ResetPasswordInput = z.infer<typeof resetPasswordSchema>;

const flattenErrors = (error: z.ZodError) => {
  const errors: Record<string, string> = {};
  error.issues.forEach((err: z.ZodIssue) => {
    const path = err.path[0]?.toString();
    if (path && !errors[path]) {
      errors[path] = err.message;
    }
  });
  return errors;
};

export const validateLogin = (data: unknown) => {
  const result = loginSchema.safeParse(data);
  return result.success 
    ? { success: true, data: result.data, errors: null } 
    : { success: false, data: null, errors: flattenErrors(result.error) };
};

export const validateSignup = (data: unknown) => {
  const result = signupSchema.safeParse(data);
  return result.success 
    ? { success: true, data: result.data, errors: null } 
    : { success: false, data: null, errors: flattenErrors(result.error) };
};

export const validateForgotPassword = (data: unknown) => {
  const result = forgotPasswordSchema.safeParse(data);
  return result.success 
    ? { success: true, data: result.data, errors: null } 
    : { success: false, data: null, errors: flattenErrors(result.error) };
};

export const validateResetPassword = (data: unknown) => {
  const result = resetPasswordSchema.safeParse(data);
  return result.success 
    ? { success: true, data: result.data, errors: null } 
    : { success: false, data: null, errors: flattenErrors(result.error) };
};

import { z } from 'zod';

export const candidateProfileSchema = z.object({
  // Profiles table fields
  name: z.string().min(2, 'Name must be at least 2 characters').max(100).optional(),
  phone: z.string().max(20).optional(),
  location: z.string().max(100).optional(),
  bio: z.string().max(1000, 'Bio must be at most 1000 characters').optional(),

  // Candidate profiles table fields
  headline: z.string().max(160, 'Headline must be at most 160 characters').optional(),
  skills: z.array(z.string()).max(30, 'You can add up to 30 skills').default([]),
  experience_years: z.number().min(0).max(50, 'Experience must be between 0 and 50 years').default(0),
  salary_min: z.number().min(0).optional(),
  salary_max: z.number().min(0).optional(),
  job_types: z.array(z.string()).default([]),
  preferred_locations: z.array(z.string()).default([]),
  open_to_remote: z.boolean().default(true),
  linkedin_url: z.string().url('Invalid LinkedIn URL').or(z.literal('')).optional(),
