import { createClient } from '@insforge/sdk';
import * as readline from 'readline';

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout
});

const question = (query: string): Promise<string> =>
  new Promise((resolve) => rl.question(query, resolve));

async function main() {
  console.log('--- TalentMesh Admin Creation ---');

  const email = process.env.ADMIN_EMAIL || await question('Enter Admin Email: ');
  const password = process.env.ADMIN_PASSWORD || await question('Enter Admin Password (min 8 chars, uppercase + number): ');
  const name = process.env.ADMIN_NAME || await question('Enter Admin Display Name: ');
  const insforgeUrl = process.env.NEXT_PUBLIC_INSFORGE_URL || await question('Enter InsForge URL: ');
  const insforgeAnonKey = process.env.NEXT_PUBLIC_INSFORGE_ANON_KEY || await question('Enter InsForge Anon Key: ');

  if (!email || !password || !name || !insforgeUrl || !insforgeAnonKey) {
    console.error('Error: All fields are required.');
    process.exit(1);
  }

  // Basic password validation
  if (password.length < 8 || !/[A-Z]/.test(password) || !/[0-9]/.test(password)) {
    console.error('Error: Password must be at least 8 chars and contain an uppercase letter and a number.');
    process.exit(1);
  }

  const insforge = createClient({
    baseUrl: insforgeUrl,
    anonKey: insforgeAnonKey,
  });

  try {
    const { data, error } = await insforge.auth.signUp({
      email,
      password,
      name,
    });

    if (error) {
      if (error.message.includes('User already exists')) {
        console.log('Account already exists. Use /admin/login to sign in.');
      } else {
        console.error('Signup failed:', error.message);
      }
      process.exit(1);
    }

    // Since we can't directly set the role via signUp options in some SDK versions,
    // we assume the 'handle_new_user' trigger or metadata handling is in place.
    // The user's prompt specifically asked for data: { role: 'admin', name: ADMIN_NAME }
    // However, @insforge/sdk signUp usually takes (options: { email, password, name, ... })

    console.log(`\n✓ Admin account created for ${email}`);
    console.log(`✓ Add this email to your ADMIN_EMAILS env var: ${email}`);
    console.log('✓ You can now log in at /admin/login');

  } catch (err: any) {
    console.error('An unexpected error occurred:', err.message);
  } finally {
    rl.close();
  }
}

main();

const fs = require('fs');
const path = require('path');

const CONFIG = {
  includeExtensions: ['.js', '.jsx', '.ts', '.tsx', '.css', '.scss', '.html', '.md', '.json', '.yaml', '.yml', '.sql'],
  excludeDirectories: ['node_modules', '.git', '.next', 'dist', 'build', '.vercel', 'bundles', 'tmp'],
  excludeFiles: ['.env', '.env.local', 'package-lock.json', 'yarn.lock', '.DS_Store', 'tsconfig.tsbuildinfo'],
  projectRoot: path.resolve(__dirname, '..'),
  outputDir: path.resolve(__dirname, '../bundles'),
};

function getRelativePath(absolutePath) {
  return path.relative(CONFIG.projectRoot, absolutePath);
}

function shouldInclude(filePath) {
  const ext = path.extname(filePath).toLowerCase();
  const basename = path.basename(filePath);

  if (CONFIG.excludeFiles.includes(basename)) return false;
  if (!CONFIG.includeExtensions.includes(ext)) return false;

  return true;
}

function escapeXml(unsafe) {
  return unsafe.replace(/[<>&'"]/g, (c) => {
    switch (c) {
      case '<': return '&lt;';
      case '>': return '&gt;';
      case '&': return '&amp;';
      case '\'': return '&apos;';
      case '"': return '&quot;';
    }
  });
}

function walk(dir, fileList = []) {
  const files = fs.readdirSync(dir);
  for (const file of files) {
    const filePath = path.join(dir, file);
    const stat = fs.statSync(filePath);

    if (stat.isDirectory()) {
      if (!CONFIG.excludeDirectories.includes(file)) {
        walk(filePath, fileList);
      }
    } else {
      if (shouldInclude(filePath)) {
        fileList.push(filePath);
      }
    }
  }
  return fileList;
}

function generateBundle() {
  console.log('Generating project bundle...');
  const files = walk(CONFIG.projectRoot);
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const outputFileName = `project_${timestamp}.xml`;
  const outputPath = path.join(CONFIG.outputDir, outputFileName);

  if (!fs.existsSync(CONFIG.outputDir)) {
    fs.mkdirSync(CONFIG.outputDir, { recursive: true });
  }

  const xmlHeader = `<?xml version="1.0" encoding="UTF-8"?>\n<bundle>\n  <metadata>\n    <created>${new Date().toISOString()}</created>\n    <projectPath>${CONFIG.projectRoot}</projectPath>\n  </metadata>\n  <files>\n`;
  const xmlFooter = `  </files>\n</bundle>`;

  const stream = fs.createWriteStream(outputPath);
  stream.write(xmlHeader);

  for (const filePath of files) {
    const relPath = getRelativePath(filePath);
    const content = fs.readFileSync(filePath, 'utf8');
    const type = relPath.endsWith('.json') || relPath.endsWith('.yaml') ? 'config' : 'code';

    stream.write(`    <file path="${escapeXml(relPath)}" type="${type}">\n`);
    stream.write(`      <content>${escapeXml(content)}</content>\n`);
    stream.write(`    </file>\n`);
  }

  stream.write(xmlFooter);
  stream.end();

  console.log(`Bundle generated successfully: ${outputPath}`);
}

generateBundle();

